window.MN_DATA = {"bab": [{"no": 1, "label": "Bab 1", "title": "Mengenal Mensetsu", "kj": "面接", "kjr": "mensetsu · wawancara kerja", "col": "#2A4B8D", "colL": "#E4EBF8", "dur": "±8 menit", "lessons": ["Apa Itu Mensetsu?", "Yang Dinilai Pewawancara", "Persiapan Sebelum Wawancara"], "blurb": "Sebelum berlatih perkenalan diri dan menjawab pertanyaan, kenali dulu seperti apa wawancara kerja di perusahaan Jepang dan apa yang dinilai pewawancara.", "slides": ["B1-01", "B1-02", "B1-03", "B1-04", "B1-05", "B1-06", "B1-07", "B1-08", "B1-09", "B1-10", "B1-11", "B1-12"], "kuis": [{"ind": "1.1", "stem": "Seorang teman berkata, “Yang penting level JLPT-ku tinggi. Sikap saat wawancara tidak terlalu dinilai.” Tanggapan yang paling tepat adalah …", "opts": ["Benar, karena level JLPT adalah syarat utama perusahaan Jepang.", "Kurang tepat, karena perusahaan Jepang juga menilai sikap, kejujuran, dan kesungguhan.", "Kurang tepat, karena perusahaan Jepang tidak memperhatikan kemampuan bahasa.", "Benar, asalkan rirekisho yang dibawa sudah lengkap."], "key": "B", "exp": "perusahaan Jepang menilai bahasa sekaligus sikap, kejujuran, dan kesungguhan. A dan D mengabaikan sikap; C keliru karena bahasa tetap dinilai.", "ok": "Tepat! Bahasa memang penting, tetapi perusahaan Jepang juga menilai sikap, kejujuran, dan kesungguhanmu. Level JLPT saja tidak cukup.", "no": "Kurang tepat. Perusahaan Jepang tidak hanya melihat level JLPT, tetapi juga tidak mengabaikan bahasa. Keduanya dinilai bersama sikap dan kejujuran. Pelajari lagi: B1-03 Apa Itu Mensetsu?", "bab": null, "remed": ["B1-03"]}, {"ind": "1.1", "stem": "Pewawancara baru saja selesai mendengarkan perkenalan dirimu. Tahap apa yang biasanya berlangsung berikutnya?", "opts": ["入室 (nyuushitsu, masuk ruangan)", "退室 (taishitsu, keluar ruangan)", "逆質問 (gyaku shitsumon, kamu bertanya balik)", "質疑応答 (shitsugi outou, tanya jawab tentang dirimu)"], "key": "D", "exp": "alurnya 入室 (nyuushitsu) → 自己紹介 (jikoshoukai) → 質疑応答 (shitsugi outou) → 逆質問 (gyaku shitsumon) → 退室 (taishitsu). Setelah jikoshoukai, pewawancara mengajukan pertanyaan tentang dirimu. 逆質問 (gyaku shitsumon) baru muncul di akhir.", "ok": "Tepat! Setelah jikoshoukai, pewawancara masuk ke tanya jawab (質疑応答, shitsugi outou) tentang motivasi, kelebihan, dan pengalamanmu.", "no": "Kurang tepat. Ingat urutannya: 入室 (nyuushitsu) → 自己紹介 (jikoshoukai) → 質疑応答 (shitsugi outou) → 逆質問 (gyaku shitsumon) → 退室 (taishitsu). Pertanyaan balik (逆質問, gyaku shitsumon) baru datang di akhir. Pelajari lagi: B1-04 Alur Mensetsu.", "bab": null, "remed": ["B1-04"]}, {"ind": "1.1", "stem": "Di akhir wawancara, pewawancara bertanya apakah kamu siap bekerja sampai masa kontrak selesai. Mengapa pertanyaan ini penting bagi perusahaan Jepang?", "opts": ["Karena perusahaan Jepang cenderung menghargai kesungguhan dan komitmen bekerja jangka panjang.", "Karena perusahaan hanya mau menerima pekerja yang sudah berpengalaman.", "Karena pewawancara ingin menguji tata bahasa bentuk lampau.", "Karena pertanyaan itu hanya formalitas yang tidak ikut dinilai."], "key": "A", "exp": "kesungguhan dan komitmen jangka panjang termasuk hal yang diperhatikan perusahaan Jepang (B1-03). B keliru karena kandidat tanpa pengalaman tetap bisa diterima, C keliru karena yang ditanyakan adalah kesiapan, dan D keliru karena semua jawaban ikut membentuk penilaian.", "ok": "Tepat! Perusahaan Jepang menghargai kesungguhan dan komitmen bekerja jangka panjang.", "no": "Kurang tepat. Ingat perbandingan di slide Apa Itu Mensetsu: selain kemampuan, perusahaan Jepang memperhatikan kesungguhan dan komitmen. Pelajari lagi: B1-03 Apa Itu Mensetsu?", "bab": null, "remed": ["B1-03"]}, {"ind": "1.2", "stem": "Saat tiba, Dimas menyapa resepsionis dengan sopan, lalu duduk tegak di ruang tunggu tanpa bermain HP. Perilaku ini paling mencerminkan aspek penilaian …", "opts": ["komunikasi", "kejujuran dan kemauan beradaptasi", "sikap dan etika", "kemampuan bahasa Jepang"], "key": "C", "exp": "sapaan sopan, postur tegak, dan tidak bermain HP adalah wujud etika (マナー, manaa). Menyapa memang melibatkan komunikasi, tetapi yang ditonjolkan di sini adalah sikapnya.", "ok": "Tepat! Menyapa dengan sopan, duduk tegak, dan tidak bermain HP adalah wujud sikap dan etika (マナー, manaa).", "no": "Kurang tepat. Dimas memang menyapa, tetapi yang paling menonjol dari perilakunya adalah sopan santun dan caranya bersikap selama menunggu. Pelajari lagi: B1-05 Tiga Hal yang Dinilai.", "bab": null, "remed": ["B1-05"]}, {"ind": "1.2", "stem": "Pernyataan yang paling tepat tentang 第一印象 (daiichi inshou, kesan pertama) dalam mensetsu adalah …", "opts": ["Kesan pertama terbentuk sejak kandidat tiba, termasuk di resepsionis dan ruang tunggu.", "Kesan pertama hanya ditentukan oleh isi jikoshoukai.", "Kesan pertama baru terbentuk saat pewawancara mulai bertanya.", "Kesan pertama hanya dinilai dari pakaian yang dikenakan."], "key": "A", "exp": "penilaian dimulai sejak kandidat tiba di lokasi. B, C, dan D masing-masing hanya menyebut satu bagian kecil dari kesan pertama.", "ok": "Tepat! Kesan pertama (第一印象, daiichi inshou) mulai terbentuk sejak kamu tiba di lokasi.", "no": "Kurang tepat. Kesan pertama tidak hanya datang dari jikoshoukai, pakaian, atau pertanyaan pertama. Sikapmu di resepsionis dan ruang tunggu juga diperhatikan. Pelajari lagi: B1-06 Penilaian Dimulai Sejak Kamu Tiba.", "bab": null, "remed": ["B1-06"]}, {"ind": "1.2", "stem": "Setelah wawancara, pewawancara mencatat: “Komunikasinya baik, tetapi etikanya kurang.” Situasi mana yang paling mungkin menyebabkan catatan itu?", "opts": ["Kandidat menjawab terbata-bata, tetapi selalu memberi salam dan ojigi.", "Kandidat mengaku masih belajar kosakata yang sulit.", "Kandidat datang 10 menit lebih awal dan membawa rirekisho.", "Kandidat menjawab dengan jelas, tetapi langsung duduk sebelum dipersilakan."], "key": "D", "exp": "D cocok dengan kedua bagian catatan: jawaban jelas (komunikasi baik) dan duduk sebelum dipersilakan (etika kurang). A kebalikannya, sedangkan B dan C justru perilaku yang baik.", "ok": "Tepat! Menjawab dengan jelas berarti komunikasinya baik, tetapi duduk sebelum dipersilakan menunjukkan etika yang kurang.", "no": "Kurang tepat. Cari situasi yang cocok dengan kedua bagian catatan: komunikasi baik dan etika kurang. Beberapa pilihan justru menggambarkan perilaku yang baik. Pelajari lagi: B1-05 Tiga Hal yang Dinilai.", "bab": null, "remed": ["B1-05"]}, {"ind": "1.2", "stem": "Kamu memiliki sertifikat N4, tetapi masih sering kesulitan memahami kata-kata sulit. Saat ditanya kemampuan bahasa Jepang, sikap jawaban yang paling tepat adalah …", "opts": ["Mengatakan sudah fasih agar terlihat percaya diri.", "Mengatakan tidak bisa bahasa Jepang agar terlihat rendah hati.", "Menyebut level N4, mengakui masih ada kata sulit, dan menunjukkan usaha belajar.", "Mengalihkan pembicaraan ke pengalaman kerja agar kekurangan tidak terlihat."], "key": "C", "exp": "pewawancara menghargai kejujuran dan kemauan belajar. A melebih-lebihkan, B merendah berlebihan sehingga tidak akurat, dan D terkesan menghindar.", "ok": "Tepat! Jujur menyebut levelmu sambil menunjukkan usaha belajar membuat pewawancara percaya padamu.", "no": "Kurang tepat. Melebih-lebihkan, merendah berlebihan, atau menghindar sama-sama mengurangi kepercayaan. Pewawancara menghargai jawaban yang jujur disertai kemauan belajar. Pelajari lagi: B1-05 Tiga Hal yang Dinilai.", "bab": null, "remed": ["B1-05"]}, {"ind": "1.3", "stem": "Wawancaramu dijadwalkan pukul 13.00 di kantor perusahaan. Kapan sebaiknya kamu tiba di lokasi?", "opts": ["Pukul 12.15", "Pukul 13.00", "Pukul 12.50", "Pukul 12.58"], "key": "C", "exp": "sekitar 10 menit lebih awal memberi waktu melapor ke resepsionis dan menenangkan diri. A terlalu awal sehingga bisa merepotkan perusahaan; B dan D terlalu mepet.", "ok": "Tepat! Sekitar 10 menit lebih awal memberimu waktu untuk melapor ke resepsionis dan menenangkan diri.", "no": "Kurang tepat. Datang terlalu awal bisa merepotkan perusahaan, sedangkan datang mepet membuatmu terburu-buru. Waktu yang dianjurkan sekitar 10 menit sebelum jadwal. Pelajari lagi: B1-09 Persiapan 3.", "bab": null, "remed": ["B1-09"]}, {"ind": "1.3", "stem": "Kereta yang kamu naiki terlambat, dan kamu diperkirakan tiba 15 menit setelah jadwal wawancara. Tindakan yang paling tepat adalah …", "opts": ["Tetap datang, lalu meminta maaf kepada pewawancara saat masuk ruangan.", "Segera menghubungi perusahaan sebelum jadwal, menjelaskan alasan, dan memberi perkiraan waktu tiba.", "Membatalkan wawancara tanpa kabar karena merasa sudah pasti gagal.", "Mengirim pesan permintaan maaf setelah wawancara selesai untuk menjelaskan alasan."], "key": "B", "exp": "kabar sebelum jadwal (renraku) menunjukkan tanggung jawab. A dan D terlambat memberi kabar, sedangkan C tidak bertanggung jawab.", "ok": "Tepat! Mengabari perusahaan sebelum jadwal (renraku) menunjukkan tanggung jawab, walaupun kamu terlambat karena hal di luar kendalimu.", "no": "Kurang tepat. Kabar harus disampaikan sebelum jadwal wawancara, bukan saat tiba atau sesudahnya. Wawancara juga tidak boleh ditinggalkan tanpa kabar. Pelajari lagi: B1-09 Persiapan 3.", "bab": null, "remed": ["B1-09"]}, {"ind": "1.3", "stem": "Rina akan mengikuti wawancara di kantor perusahaan. Penampilan yang paling sesuai dengan 身だしなみ (midashinami, kerapian penampilan) adalah …", "opts": ["Setelan jas gelap, kemeja putih, sepatu pantofel bersih, dan parfum yang tidak menyengat.", "Kemeja rapi dengan aksesori mencolok agar mudah diingat pewawancara.", "Pakaian santai yang bersih karena yang dinilai hanya jawaban.", "Setelan jas gelap yang rapi dengan sepatu kets agar nyaman berjalan."], "key": "A", "exp": "A memenuhi semua unsur kerapian. B berlebihan, C mengabaikan bahwa penampilan ikut dinilai, dan D tidak serasi meskipun jasnya sudah tepat.", "ok": "Tepat! Jas gelap, kemeja putih, sepatu pantofel bersih, dan parfum yang tidak menyengat memenuhi standar 身だしなみ (midashinami).", "no": "Kurang tepat. Penampilan ikut dinilai, dan seluruh unsurnya harus serasi, mulai dari pakaian sampai sepatu dan aksesori. Pelajari lagi: B1-08 Persiapan 2.", "bab": null, "remed": ["B1-08"]}], "glos": [{"jp": "面接", "ro": "mensetsu", "ar": "wawancara kerja", "kat": "wawancara", "k": 2}, {"jp": "面接官", "ro": "mensetsukan", "ar": "pewawancara", "kat": "wawancara", "k": 2}, {"jp": "入室", "ro": "nyuushitsu", "ar": "masuk ruangan", "kat": "wawancara", "k": 3}, {"jp": "自己紹介", "ro": "jikoshoukai", "ar": "perkenalan diri", "kat": "wawancara", "k": 3}, {"jp": "質疑応答", "ro": "shitsugi outou", "ar": "tanya jawab", "kat": "wawancara", "k": 3}, {"jp": "逆質問", "ro": "gyaku shitsumon", "ar": "pertanyaan balik dari kandidat", "kat": "wawancara", "k": 3}, {"jp": "退室", "ro": "taishitsu", "ar": "keluar ruangan", "kat": "wawancara", "k": 3}, {"jp": "第一印象", "ro": "daiichi inshou", "ar": "kesan pertama", "kat": "wawancara", "k": 5}, {"jp": "履歴書", "ro": "rirekisho", "ar": "daftar riwayat hidup format Jepang", "kat": "wawancara", "k": 6}, {"jp": "身だしなみ", "ro": "midashinami", "ar": "kerapian penampilan", "kat": "wawancara", "k": 7}, {"jp": "マナー", "ro": "manaa", "ar": "etika, tata krama", "kat": "wawancara", "k": 4}, {"jp": "失礼します", "ro": "shitsurei shimasu", "ar": "permisi (saat masuk/keluar ruangan)", "kat": "sopan", "k": 3}]}, {"no": 2, "label": "Bab 2", "title": "Hou-Ren-Sou", "kj": "報連相", "kjr": "hou · ren · sou", "col": "#0E7470", "colL": "#DDF2F0", "dur": "±12 menit", "lessons": ["Mengenal Hou-Ren-Sou", "Membedakan Ketiganya", "Hou-Ren-Sou di Wawancara"], "blurb": "Hou-Ren-Sou (melapor, mengabari, berkonsultasi) adalah cara berkomunikasi yang sangat dihargai di tempat kerja Jepang dan sering muncul dalam pertanyaan wawancara.", "slides": ["B2-01", "B2-02", "B2-03", "B2-04", "B2-05", "B2-06", "B2-07", "B2-08", "B2-09", "B2-10", "B2-11", "B2-12", "B2-13"], "kuis": [{"ind": "2.1", "stem": "Apa arti 報告 (houkoku) di tempat kerja Jepang?", "opts": ["Mengabari semua orang tentang perubahan jadwal.", "Meminta saran sebelum mengambil keputusan.", "Melaporkan hasil dan perkembangan pekerjaan kepada atasan.", "Menyampaikan pendapat pribadi dalam rapat."], "key": "C", "exp": "houkoku adalah laporan tentang pekerjaan yang ditugaskan. A adalah renraku, B adalah soudan, dan D bukan bagian dari Hou-Ren-Sou.", "ok": "Tepat! Houkoku = melaporkan hasil dan perkembangan pekerjaan kepada atasan.", "no": "Kurang tepat. Ingat cara mudahnya: houkoku = hasil kerja, renraku = kabar, soudan = minta saran. Pelajari lagi: B2-04 Houkoku.", "bab": null, "remed": ["B2-04"]}, {"ind": "2.1", "stem": "Kapan sebaiknya kamu melaporkan kesalahan yang kamu buat dalam pekerjaan?", "opts": ["Secepatnya, begitu kamu menyadarinya.", "Setelah kamu berhasil memperbaikinya sendiri.", "Saat rapat mingguan agar semua orang tahu.", "Jika atasan bertanya tentang kesalahan itu."], "key": "A", "exp": "kabar buruk disampaikan secepatnya agar masalah tidak membesar. B dan C menunda laporan, sedangkan D berarti menunggu ditanya.", "ok": "Tepat! Semakin buruk kabarnya, semakin cepat harus dilaporkan.", "no": "Kurang tepat. Memperbaiki sendiri atau menunggu ditanya membuat atasan terlambat tahu, padahal mungkin ada dampak lain yang harus segera ditangani. Pelajari lagi: B2-04 Houkoku.", "bab": null, "remed": ["B2-04"]}, {"ind": "2.1", "stem": "Pernyataan yang paling tepat tentang 相談 (soudan) adalah …", "opts": ["Dilakukan setelah keputusan diambil agar atasan mengetahuinya.", "Hanya dilakukan oleh atasan kepada bawahannya.", "Sama dengan melaporkan hasil pekerjaan kepada atasan.", "Meminta saran atasan atau senior sebelum memutuskan hal yang belum dipahami."], "key": "D", "exp": "soudan dilakukan sebelum memutuskan, oleh siapa pun yang ragu. A terbalik urutannya, B keliru soal arah, dan C adalah houkoku.", "ok": "Tepat! Soudan = bertanya dan meminta saran sebelum memutuskan.", "no": "Kurang tepat. Kunci soudan ada pada waktunya: sebelum keputusan diambil, saat kamu masih ragu. Pelajari lagi: B2-06 Soudan.", "bab": null, "remed": ["B2-06"]}, {"ind": "2.2", "stem": "Bagian gudang memberi tahu bahwa bahan baku akan datang terlambat besok pagi. Kamu meneruskan informasi ini kepada rekan satu tim. Tindakanmu termasuk …", "opts": ["報告 (houkoku), karena kamu menyampaikan hasil pekerjaanmu.", "連絡 (renraku), karena kamu meneruskan informasi kepada pihak terkait.", "相談 (soudan), karena kamu meminta pendapat tim tentang langkah berikutnya.", "報告 (houkoku), karena informasinya disampaikan kepada atasan."], "key": "B", "exp": "kamu meneruskan fakta kepada orang yang perlu tahu, jadi termasuk renraku. Kamu tidak melaporkan hasil kerja (A), tidak meminta saran (C), dan tidak menyampaikannya kepada atasan (D).", "ok": "Tepat! Meneruskan informasi kepada pihak terkait adalah renraku.", "no": "Kurang tepat. Perhatikan isinya: ini kabar tentang jadwal, bukan hasil kerjamu, dan kamu tidak sedang meminta saran. Pelajari lagi: B2-05 dan B2-07.", "bab": null, "remed": ["B2-05", "B2-07"]}, {"ind": "2.2", "stem": "Kamu ditugasi menempel label pada produk baru, tetapi ada dua jenis label yang mirip dan kamu tidak yakin mana yang benar. Tindakan yang sesuai Hou-Ren-Sou adalah …", "opts": ["Memilih salah satu label agar pekerjaan cepat selesai.", "Menempel kedua label sekaligus agar pasti ada yang benar.", "Bertanya kepada atasan atau senior sebelum mulai menempel.", "Menunda pekerjaan sampai atasan datang memeriksa."], "key": "C", "exp": "saat ragu, lakukan soudan sebelum bertindak. A dan B berisiko salah, sedangkan D membuat pekerjaan tertunda tanpa ada yang tahu.", "ok": "Tepat! Bertanya sebelum bertindak mencegah kesalahan. Ini soudan.", "no": "Kurang tepat. Menebak bisa menimbulkan kesalahan, dan menunggu tanpa bertanya membuat pekerjaan terhambat. Pelajari lagi: B2-06 Soudan.", "bab": null, "remed": ["B2-06"]}, {"ind": "2.2", "stem": "Pasangan situasi dan prinsip manakah yang tepat?", "opts": ["Pekerjaanmu baru selesai separuh, dan kamu menyampaikan perkembangannya ke atasan — 報告 (houkoku).", "Kamu bertanya kepada senior cara memakai mesin baru — 連絡 (renraku).", "Kamu mengabari kantor bahwa kamu sakit hari ini — 相談 (soudan).", "Kamu memberi tahu rekan bahwa rapat pindah jam — 報告 (houkoku)."], "key": "A", "exp": "perkembangan pekerjaan termasuk houkoku. B seharusnya soudan, C seharusnya renraku, dan D seharusnya renraku.", "ok": "Tepat! Houkoku tidak hanya untuk hasil akhir, tetapi juga perkembangan pekerjaan.", "no": "Kurang tepat. Cocokkan setiap situasi dengan isinya: hasil kerja, kabar, atau minta saran. Pelajari lagi: B2-07 Bedanya Apa?", "bab": null, "remed": ["B2-07"]}, {"ind": "2.2", "stem": "Rina sedang demam dan menelepon kantor: 「すみません。熱があるので、今日は休ませてください。」 (Sumimasen. Netsu ga aru node, kyou wa yasumasete kudasai. “Maaf, saya demam, izinkan saya tidak masuk hari ini.”) Tindakan ini termasuk … dan sebaiknya dilakukan …", "opts": ["報告 (houkoku), setelah jam kerja dimulai", "相談 (soudan), setelah Rina sembuh", "連絡 (renraku), setelah jam kerja dimulai", "連絡 (renraku), sebelum jam kerja dimulai"], "key": "D", "exp": "mengabari ketidakhadiran adalah renraku dan harus disampaikan sebelum kejadian. A dan B salah jenisnya, sedangkan C benar jenisnya tetapi terlambat waktunya.", "ok": "Tepat! Renraku disampaikan sebelum kejadian, jadi kabari sebelum jam kerja dimulai.", "no": "Kurang tepat. Periksa dua hal: jenisnya (ini kabar) dan waktunya (kabar disampaikan sebelum kejadian). Pelajari lagi: B2-05 Renraku.", "bab": null, "remed": ["B2-05"]}, {"ind": "2.3", "stem": "Pewawancara bertanya: 「仕事でミスをしたら、どうしますか。」 (Shigoto de misu o shitara, dou shimasu ka. “Jika kamu membuat kesalahan dalam pekerjaan, apa yang kamu lakukan?”) Jawaban mana yang paling tepat?", "opts": ["「ミスをしないように、がんばります。」 (Misu o shinai you ni, ganbarimasu. Saya berusaha agar tidak membuat kesalahan.)", "「すぐに上司に報告して、謝ります。」 (Sugu ni joushi ni houkoku shite, ayamarimasu. Saya segera melapor ke atasan dan meminta maaf.)", "「自分で直してから、上司に話します。」 (Jibun de naoshite kara, joushi ni hanashimasu. Saya perbaiki sendiri dulu, baru memberi tahu atasan.)", "「ミスはしたことがありません。」 (Misu wa shita koto ga arimasen. Saya belum pernah membuat kesalahan.)"], "key": "B", "exp": "B menunjukkan houkoku dan tanggung jawab. A tidak menjawab pertanyaan, C menunda laporan, dan D terdengar tidak jujur.", "ok": "Tepat! Kamu menunjukkan houkoku: melapor segera dan meminta maaf.", "no": "Kurang tepat. Pewawancara ingin tahu apa tindakanmu setelah salah, bukan janji tidak akan salah. Laporan juga tidak boleh ditunda. Pelajari lagi: B2-10 Pertanyaan Situasional.", "bab": null, "remed": ["B2-10"]}, {"ind": "2.3", "stem": "Di tengah wawancara online, koneksimu terputus dan kamu tidak bisa masuk kembali selama beberapa menit. Tindakan yang paling tepat adalah …", "opts": ["Segera menghubungi kontak perusahaan lewat telepon atau pesan, lalu mencoba masuk kembali.", "Menunggu sampai pewawancara menghubungimu lebih dulu.", "Mengirim email permintaan maaf keesokan harinya.", "Mencoba masuk berulang kali tanpa mengabari siapa pun."], "key": "A", "exp": "pewawancara perlu tahu apa yang terjadi, jadi lakukan renraku secepatnya. B pasif, C terlambat, dan D membuat pewawancara menunggu tanpa kabar.", "ok": "Tepat! Mengabari secepatnya menunjukkan tanggung jawab, bahkan saat masalahnya bukan salahmu.", "no": "Kurang tepat. Saat ada kendala, pewawancara perlu segera tahu kondisimu. Jangan menunggu atau diam. Pelajari lagi: B2-09 Hou-Ren-Sou Sebelum Wawancara.", "bab": null, "remed": ["B2-09"]}, {"ind": "2.3", "stem": "Pewawancara bertanya 「分からないことがあったら、どうしますか。」 (Wakaranai koto ga attara, dou shimasu ka. “Jika ada yang tidak kamu pahami, apa yang kamu lakukan?”) dan kandidat menjawab 「自分で調べて、全部一人でやります。」 (Jibun de shirabete, zenbu hitori de yarimasu. “Saya cari tahu sendiri dan mengerjakan semuanya sendirian.”) Mengapa jawaban ini kurang tepat?", "opts": ["Karena mencari tahu sendiri dilarang di perusahaan Jepang.", "Karena jawabannya terlalu panjang untuk wawancara.", "Karena hal yang belum dipahami sebaiknya dikonsultasikan dulu agar tidak salah.", "Karena jawaban itu menunjukkan kandidat tidak punya inisiatif."], "key": "C", "exp": "perusahaan mengharapkan soudan untuk hal yang belum dipahami. A berlebihan karena mencari tahu sendiri tidak dilarang, B tidak relevan, dan D keliru karena jawaban itu justru menunjukkan inisiatif.", "ok": "Tepat! Inisiatif itu baik, tetapi hal yang belum dipahami sebaiknya ditanyakan dulu.", "no": "Kurang tepat. Masalahnya bukan pada inisiatif atau panjang jawaban, tetapi pada risiko salah karena tidak bertanya. Pelajari lagi: B2-10 dan B2-11.", "bab": null, "remed": ["B2-10", "B2-11"]}], "glos": [{"jp": "報連相", "ro": "hourensou", "ar": "Hou-Ren-Sou (melapor, mengabari, berkonsultasi)", "kat": "kerja", "k": 1}, {"jp": "ほうれん草", "ro": "hourensou", "ar": "bayam", "kat": "kerja", "k": 1}, {"jp": "報告", "ro": "houkoku", "ar": "melapor (hasil dan perkembangan kerja)", "kat": "kerja", "k": 3}, {"jp": "連絡", "ro": "renraku", "ar": "mengabari, menyampaikan informasi", "kat": "kerja", "k": 4}, {"jp": "相談", "ro": "soudan", "ar": "berkonsultasi, meminta saran", "kat": "kerja", "k": 5}, {"jp": "上司", "ro": "joushi", "ar": "atasan", "kat": "kerja", "k": 9}, {"jp": "先輩", "ro": "senpai", "ar": "senior", "kat": "kerja", "k": 5}, {"jp": "作業", "ro": "sagyou", "ar": "pekerjaan, tugas kerja", "kat": "kerja", "k": 3}, {"jp": "ミス", "ro": "misu", "ar": "kesalahan", "kat": "kerja", "k": 3}, {"jp": "遅刻", "ro": "chikoku", "ar": "terlambat", "kat": "kerja", "k": 9}, {"jp": "結論から", "ro": "ketsuron kara", "ar": "(sampaikan) kesimpulan dulu", "kat": "sopan", "k": 3}, {"jp": "申し訳ありません", "ro": "moushiwake arimasen", "ar": "mohon maaf (sopan)", "kat": "sopan", "k": 3}]}, {"no": 3, "label": "Bab 3", "title": "Nyuushitsu & Ojigi", "kj": "入室", "kjr": "nyuushitsu · お辞儀 ojigi", "col": "#B0436A", "colL": "#FBE6EE", "dur": "±12 menit", "lessons": ["Langkah Masuk Ruangan", "Ojigi", "Duduk dan Latihan Gabungan"], "blurb": "Wawancara dimulai sejak kamu mengetuk pintu. Di bab ini kamu berlatih masuk ruangan, membungkuk, dan duduk dengan benar.", "slides": ["B3-01", "B3-02", "B3-03", "B3-04", "B3-05", "B3-06", "B3-07", "B3-08", "B3-09", "B3-10", "B3-11", "B3-12", "B3-13", "B3-14"], "kuis": [{"ind": "3.1", "stem": "Setelah mengetuk pintu tiga kali, urutan langkah yang benar adalah … (「失礼します」 = shitsurei shimasu, “permisi”)", "opts": ["Membuka pintu → menunggu jawaban → mengucapkan 「失礼します」", "Menunggu jawaban → membuka pintu dan mengucapkan 「失礼します」 → menutup pintu", "Mengucapkan 「失礼します」 → langsung duduk → menutup pintu", "Menunggu jawaban → masuk → langsung duduk di kursi"], "key": "B", "exp": "kandidat menunggu dipersilakan, masuk sambil mengucapkan 「失礼します」, lalu menutup pintu. A membuka pintu sebelum ada jawaban, sedangkan C dan D duduk sebelum dipersilakan.", "ok": "Tepat! Tunggu dipersilakan, masuk dengan 「失礼します」, lalu tutup pintu dengan tenang.", "no": "Kurang tepat. Ingat dua aturan penting: jangan membuka pintu sebelum ada jawaban, dan jangan duduk sebelum dipersilakan. Pelajari lagi: B3-03 s.d. B3-05.", "bab": null, "remed": ["B3-03", "B3-05"]}, {"ind": "3.1", "stem": "Kamu sudah masuk dan menutup pintu, lalu berjalan ke kursi. Apa yang kamu lakukan selanjutnya?", "opts": ["Langsung duduk agar tidak terlihat gugup.", "Meletakkan tas di atas meja pewawancara.", "Diam menunggu sampai pewawancara bertanya.", "Berdiri di samping kursi, memperkenalkan diri singkat, lalu menunggu dipersilakan duduk."], "key": "D", "exp": "langkah 5–7 adalah berdiri di samping kursi, perkenalan singkat dengan ojigi, lalu duduk setelah dipersilakan. A duduk terlalu cepat, B salah menempatkan tas, dan C terlalu pasif.", "ok": "Tepat! Berdiri di samping kursi, perkenalkan diri, lalu tunggu 「どうぞおかけください」 (douzo okake kudasai, “silakan duduk”).", "no": "Kurang tepat. Di samping kursi, kamu masih harus menyapa dan memperkenalkan diri singkat sebelum dipersilakan duduk. Pelajari lagi: B3-06.", "bab": null, "remed": ["B3-06"]}, {"ind": "3.1", "stem": "Rudi mengetuk pintu tiga kali. Belum terdengar jawaban, tetapi ia langsung membuka pintu dan masuk. Apa kesalahan Rudi?", "opts": ["Ia masuk sebelum dipersilakan.", "Ia seharusnya mengetuk dua kali.", "Ia seharusnya mengucapkan 「よろしくお願いします」 (yoroshiku onegai shimasu, “mohon kerja samanya”) sebelum mengetuk.", "Ia seharusnya menunggu sampai pewawancara membukakan pintu."], "key": "A", "exp": "Rudi sudah benar mengetuk tiga kali, tetapi masuk tanpa menunggu 「どうぞ」 (douzo, “silakan”). B keliru karena dua ketukan tidak dipakai, C tidak perlu, dan D berlebihan karena kandidat membuka pintu sendiri setelah dipersilakan.", "ok": "Tepat! Ketukan Rudi sudah benar; masalahnya, ia tidak menunggu dipersilakan.", "no": "Kurang tepat. Jumlah ketukan Rudi sudah benar. Perhatikan apa yang terjadi setelah ia mengetuk. Pelajari lagi: B3-04.", "bab": null, "remed": ["B3-04"]}, {"ind": "3.2", "stem": "Pewawancara berkata 「どうぞおかけください。」 (douzo okake kudasai, “silakan duduk”). Apa yang kamu ucapkan sebelum duduk?", "opts": ["「はじめまして。」 (hajimemashite, “salam kenal”)", "「ありがとうございました。」 (arigatou gozaimashita, “terima kasih”)", "「失礼します。」 (shitsurei shimasu, “permisi”)", "「どうぞ。」 (douzo, “silakan”)"], "key": "C", "exp": "「失礼します」 diucapkan saat masuk dan sebelum duduk. A sudah diucapkan saat perkenalan, B adalah ucapan penutup, dan D adalah ucapan pewawancara.", "ok": "Tepat! 「失礼します」, ojigi ringan, lalu duduk.", "no": "Kurang tepat. Ungkapan yang sama dengan saat masuk ruangan juga dipakai sebelum duduk. Pelajari lagi: B3-06 dan B3-07.", "bab": null, "remed": ["B3-06", "B3-07"]}, {"ind": "3.2", "stem": "Saat berdiri di samping kursi, ungkapan perkenalan singkat yang paling tepat adalah …", "opts": ["「〇〇と申します。本日はよろしくお願いいたします。」 (… to moushimasu. Honjitsu wa yoroshiku onegai itashimasu. “Nama saya …. Mohon kerja samanya hari ini.”)", "「〇〇です。どうぞ。」 (… desu. Douzo. “Saya …. Silakan.”)", "「失礼しました。〇〇です。」 (Shitsurei shimashita. … desu. “Permisi (bentuk lampau). Saya ….”)", "「〇〇だよ。よろしくね。」 (… da yo. Yoroshiku ne. “Aku …. Salam kenal, ya.”)"], "key": "A", "exp": "A memakai bentuk sopan と申します dan salam pembuka. B memakai どうぞ yang merupakan ucapan pewawancara, C memakai 失礼しました yang dipakai saat keluar, dan D memakai bahasa santai.", "ok": "Tepat! と申します (to moushimasu) dan よろしくお願いいたします (yoroshiku onegai itashimasu) adalah bentuk sopan untuk wawancara.", "no": "Kurang tepat. Perhatikan tingkat kesopanan dan waktu pemakaiannya: ada ungkapan untuk pewawancara, untuk keluar ruangan, dan bahasa santai. Pelajari lagi: B3-06 dan B3-07.", "bab": null, "remed": ["B3-06", "B3-07"]}, {"ind": "3.3", "stem": "Ojigi dengan sudut sekitar 30° disebut … dan dipakai saat …", "opts": ["会釈 (eshaku), berpapasan dengan staf di lorong", "最敬礼 (saikeirei), berpapasan dengan staf di lorong", "会釈 (eshaku), meminta maaf dengan sungguh-sungguh", "敬礼 (keirei), memperkenalkan diri kepada pewawancara"], "key": "D", "exp": "敬礼 (30°) adalah salam hormat standar, termasuk saat memperkenalkan diri. 会釈 adalah 15° dan 最敬礼 adalah 45°.", "ok": "Tepat! 敬礼 (keirei) 30° adalah ojigi yang paling sering kamu pakai di wawancara.", "no": "Kurang tepat. Cocokkan nama, sudut, dan situasinya: 会釈 (eshaku) 15°, 敬礼 (keirei) 30°, 最敬礼 (saikeirei) 45°. Pelajari lagi: B3-08.", "bab": null, "remed": ["B3-08"]}, {"ind": "3.3", "stem": "Kamu datang terlambat 10 menit karena kereta dan meminta maaf kepada pewawancara. Ojigi yang paling sesuai adalah …", "opts": ["会釈 (eshaku, ±15°)", "最敬礼 (saikeirei, ±45°)", "敬礼 (keirei, ±30°)", "Mengangguk singkat tanpa membungkuk"], "key": "B", "exp": "permintaan maaf yang sungguh-sungguh memakai ojigi terdalam. A dan D terlalu ringan, sedangkan C dipakai untuk salam hormat biasa.", "ok": "Tepat! Permintaan maaf yang tulus memakai 最敬礼 (saikeirei) 45°.", "no": "Kurang tepat. Semakin besar rasa hormat atau penyesalan yang ingin ditunjukkan, semakin dalam ojigi-nya. Pelajari lagi: B3-08 dan B3-10.", "bab": null, "remed": ["B3-08", "B3-10"]}, {"ind": "3.3", "stem": "Nina mengucapkan 「よろしくお願いいたします」 (yoroshiku onegai itashimasu, “mohon kerja samanya”) sambil membungkuk pada saat yang sama. Menurut prinsip 語先後礼 (gosen gorei), apa yang sebaiknya Nina perbaiki?", "opts": ["Membungkuk lebih dalam, sampai sekitar 90°.", "Membungkuk dulu, baru mengucapkan salam.", "Mengucapkan salam dulu, baru membungkuk.", "Tidak perlu membungkuk karena sudah mengucapkan salam."], "key": "C", "exp": "語先後礼 berarti kata dulu, baru membungkuk. A tidak berhubungan dengan prinsip ini, B terbalik urutannya, dan D menghilangkan ojigi.", "ok": "Tepat! Kata dulu, baru membungkuk.", "no": "Kurang tepat. 語先後礼 dibaca ‘kata (語) dulu (先), hormat (礼) kemudian (後)’. Pelajari lagi: B3-09.", "bab": null, "remed": ["B3-09"]}, {"ind": "3.4", "stem": "Sikap duduk yang benar saat wawancara adalah …", "opts": ["Punggung tegak, tidak bersandar, tangan di atas paha.", "Bersandar penuh agar terlihat santai dan percaya diri.", "Menyilangkan kaki dan melipat tangan di depan dada.", "Duduk di ujung kursi sambil mencondongkan badan ke meja."], "key": "A", "exp": "punggung tegak tanpa bersandar dan tangan di paha menunjukkan kesungguhan. B terlihat terlalu santai, C terkesan menutup diri, dan D terlihat tidak stabil.", "ok": "Tepat! Duduk tegak tanpa bersandar dengan tangan di atas paha.", "no": "Kurang tepat. Sikap duduk yang baik terlihat tenang dan sungguh-sungguh, tidak terlalu santai dan tidak menutup diri. Pelajari lagi: B3-11.", "bab": null, "remed": ["B3-11"]}, {"ind": "3.4", "stem": "Di mana sebaiknya kamu meletakkan tas saat duduk di ruang wawancara?", "opts": ["Di atas meja pewawancara.", "Di pangkuan sepanjang wawancara.", "Di kursi kosong di sebelahmu.", "Di lantai, di samping kursimu."], "key": "D", "exp": "tas diletakkan di lantai di samping kursi. Meja adalah wilayah pewawancara, tas di pangkuan membuat tangan tidak bisa diletakkan dengan benar, dan kursi lain bukan tempat barang.", "ok": "Tepat! Tas di lantai, di samping kursimu.", "no": "Kurang tepat. Meja dan kursi lain bukan tempatmu, dan tas di pangkuan mengganggu posisi tangan. Pelajari lagi: B3-11.", "bab": null, "remed": ["B3-11"]}], "glos": [{"jp": "入室", "ro": "nyuushitsu", "ar": "masuk ruangan", "kat": "wawancara", "k": -1}, {"jp": "お辞儀", "ro": "ojigi", "ar": "membungkuk memberi hormat", "kat": "wawancara", "k": 7}, {"jp": "会釈", "ro": "eshaku", "ar": "ojigi ringan (±15°)", "kat": "wawancara", "k": 7}, {"jp": "敬礼", "ro": "keirei", "ar": "ojigi hormat (±30°)", "kat": "wawancara", "k": 7}, {"jp": "最敬礼", "ro": "saikeirei", "ar": "ojigi sangat hormat (±45°)", "kat": "wawancara", "k": 7}, {"jp": "語先後礼", "ro": "gosen gorei", "ar": "ucapkan dulu, baru membungkuk", "kat": "wawancara", "k": 8}, {"jp": "失礼します", "ro": "shitsurei shimasu", "ar": "permisi", "kat": "sopan", "k": 2}, {"jp": "どうぞ", "ro": "douzo", "ar": "silakan", "kat": "sopan", "k": 3}, {"jp": "お入りください", "ro": "ohairi kudasai", "ar": "silakan masuk", "kat": "sopan", "k": 3}, {"jp": "どうぞおかけください", "ro": "douzo okake kudasai", "ar": "silakan duduk", "kat": "sopan", "k": 5}, {"jp": "と申します", "ro": "to moushimasu", "ar": "nama saya … (sopan)", "kat": "sopan", "k": 5}, {"jp": "本日", "ro": "honjitsu", "ar": "hari ini (sopan)", "kat": "sopan", "k": 5}]}, {"no": 4, "label": "Bab 4", "title": "Jikoshoukai", "kj": "自己紹介", "kjr": "jikoshoukai · perkenalan diri", "col": "#A8650F", "colL": "#FBEEDA", "dur": "±18 menit", "lessons": ["Fungsi Jikoshoukai", "Lima Blok", "Pelafalan dan Kesalahan Umum", "Jikoshoukai-ku"], "blurb": "Setelah duduk, pewawancara hampir selalu memintamu memperkenalkan diri. Di bab inti ini kamu menyusun dan melatih jikoshoukai-mu sendiri.", "slides": ["B4-01", "B4-02", "B4-03", "B4-04", "B4-05", "B4-06", "B4-07", "B4-08", "B4-09", "B4-10", "B4-11", "B4-12", "B4-13", "B4-14", "B4-15", "B4-16", "B4-17"], "kuis": [{"ind": "4.1", "stem": "Pewawancara berkata 「自己紹介をお願いします。」 (Jikoshoukai o onegai shimasu. “Silakan perkenalkan diri.”) Apa yang sebaiknya kamu lakukan?", "opts": ["Menceritakan riwayat hidup lengkap sejak kecil selama sekitar lima menit.", "Menyebutkan nama saja, lalu menunggu pertanyaan berikutnya.", "Memperkenalkan diri sekitar satu menit: nama, asal, latar belakang, kelebihan, dan motivasi.", "Langsung menjelaskan panjang lebar alasan ingin bekerja di perusahaan itu."], "key": "C", "exp": "jikoshoukai adalah perkenalan singkat 30–60 detik yang mencakup lima blok. A terlalu panjang, B terlalu singkat, dan D hanya membahas motivasi.", "ok": "Tepat! Singkat, sekitar satu menit, dan mencakup lima blok.", "no": "Kurang tepat. Jikoshoukai tidak boleh terlalu singkat, tetapi juga bukan cerita panjang. Ingat ‘daftar isi’ dirimu dalam satu menit. Pelajari lagi: B4-03.", "bab": null, "remed": ["B4-03"]}, {"ind": "4.1", "stem": "Setelah kamu selesai jikoshoukai, pewawancara berkata 「自己PRをお願いします。」 (Jiko PR o onegai shimasu.) Apa yang diharapkan pewawancara?", "opts": ["Menjelaskan kelebihanmu lebih dalam, disertai contoh pengalaman.", "Mengulang jikoshoukai yang sama persis dari awal.", "Menyebutkan nama dan kota asal sekali lagi dengan lebih pelan.", "Menanyakan gaji dan fasilitas yang akan kamu terima."], "key": "A", "exp": "自己PR adalah promosi diri: satu kelebihan dijelaskan lebih dalam dengan contoh. B dan C mengulang jikoshoukai, sedangkan D tidak menjawab permintaan.", "ok": "Tepat! Jiko PR fokus pada kelebihanmu, dijelaskan lebih dalam dengan contoh.", "no": "Kurang tepat. Jiko PR berbeda dari jikoshoukai: bukan mengulang perkenalan, melainkan menjelaskan kelebihan lebih dalam. Pelajari lagi: B4-04.", "bab": null, "remed": ["B4-04"]}, {"ind": "4.2", "stem": "Urutan lima blok jikoshoukai yang benar adalah …", "opts": ["Salam dan nama → kelebihan → asal dan usia → motivasi dan penutup → latar belakang", "Asal dan usia → salam dan nama → latar belakang → motivasi dan penutup → kelebihan", "Salam dan nama → latar belakang → asal dan usia → kelebihan → motivasi dan penutup", "Salam dan nama → asal dan usia → latar belakang → kelebihan → motivasi dan penutup"], "key": "D", "exp": "urutannya Siapa → Dari mana → Pernah apa → Bisa apa → Mau apa. A dan B mengacak blok, sedangkan C menukar asal dan latar belakang.", "ok": "Tepat! Siapa, dari mana, pernah apa, bisa apa, mau apa.", "no": "Kurang tepat. Pakai lima pertanyaan pengingat: siapa, dari mana, pernah apa, bisa apa, mau apa. Pelajari lagi: B4-05.", "bab": null, "remed": ["B4-05"]}, {"ind": "4.2", "stem": "Kalimat 「私の長所は、まじめなことです。」 (Watashi no chousho wa, majime na koto desu.) termasuk blok ke berapa? (Arti kalimat tidak ditampilkan karena soal ini menguji pemahamannya.)", "opts": ["Blok 1, salam dan nama", "Blok 4, kelebihan", "Blok 3, latar belakang", "Blok 5, motivasi dan penutup"], "key": "B", "exp": "長所 (chousho) berarti kelebihan, jadi kalimat ini adalah blok 4: “Kelebihan saya adalah rajin dan sungguh-sungguh.”", "ok": "Tepat! 長所 (chousho) = kelebihan, jadi ini blok 4.", "no": "Kurang tepat. Perhatikan kata 長所 (chousho) dan pola 私の長所は (watashi no chousho wa). Pelajari lagi: B4-05 dan B4-08.", "bab": null, "remed": ["B4-05", "B4-08"]}, {"ind": "4.3", "stem": "Keempat kalimat berikut sama-sama berarti “Saya Rani”, tetapi tingkat kesopanannya berbeda. Mana yang paling tepat untuk wawancara?", "opts": ["「ラニと申します。」 (Rani to moushimasu.)", "「ラニだよ。」 (Rani da yo.)", "「ラニさんです。」 (Rani-san desu.)", "「名前はラニ。」 (Namae wa Rani.)"], "key": "A", "exp": "と申します adalah bentuk sopan untuk menyebut nama sendiri. B dan D bahasa santai, sedangkan C keliru karena さん (san) tidak dipakai untuk nama sendiri.", "ok": "Tepat! と申します (to moushimasu) adalah cara sopan menyebut nama sendiri.", "no": "Kurang tepat. Ingat: さん (san) hanya untuk nama orang lain, dan wawancara membutuhkan bentuk sopan, bukan santai. Pelajari lagi: B4-06.", "bab": null, "remed": ["B4-06"]}, {"ind": "4.3", "stem": "Kalimat penutup jikoshoukai yang paling tepat adalah …", "opts": ["「じゃあね。」 (Jaa ne. “Dah, sampai nanti.”)", "「ありがとう。」 (Arigatou. “Makasih.”)", "「どうぞよろしくお願いいたします。」 (Douzo yoroshiku onegai itashimasu. “Mohon bimbingan dan kerja samanya.”)", "「以上です。さようなら。」 (Ijou desu. Sayounara. “Sekian. Selamat tinggal.”)"], "key": "C", "exp": "C adalah penutup standar yang sopan. A dan B bahasa santai, sedangkan D memakai さようなら (sayounara) yang berarti berpisah, padahal wawancara baru dimulai.", "ok": "Tepat! Tutup dengan どうぞよろしくお願いいたします, lalu ojigi.", "no": "Kurang tepat. Penutup jikoshoukai harus sopan dan tidak terdengar seperti pamit. Pelajari lagi: B4-09.", "bab": null, "remed": ["B4-09"]}, {"ind": "4.4", "stem": "Dimas lulusan SMK, pernah bekerja di pabrik selama satu tahun, belajar bahasa Jepang delapan bulan, dan lulus N4. Kalimat mana yang paling tepat untuk blok 3 (latar belakang) jikoshoukai-nya?", "opts": ["「体力があります。」 (Tairyoku ga arimasu. “Saya punya stamina.”)", "「高校を卒業して、一年、工場で働いていました。日本語は八か月勉強して、N4に合格しました。」 (Koukou o sotsugyou shite, ichinen, koujou de hataraite imashita. Nihongo wa hachikagetsu benkyou shite, N4 ni goukaku shimashita. “Setelah lulus SMK, saya bekerja di pabrik satu tahun. Saya belajar bahasa Jepang delapan bulan dan lulus N4.”)", "「日本の会社で働きたいです。」 (Nihon no kaisha de hatarakitai desu. “Saya ingin bekerja di perusahaan Jepang.”)", "「二十歳です。」 (Hatachi desu. “Usia saya 20 tahun.”)"], "key": "B", "exp": "blok 3 berisi pendidikan, pengalaman kerja, dan belajar bahasa Jepang. A termasuk blok 4, C termasuk blok 5, dan D termasuk blok 2.", "ok": "Tepat! Blok 3 menjawab ‘pernah apa’: sekolah, kerja, dan belajar bahasa Jepang.", "no": "Kurang tepat. Kalimat itu milik blok lain. Blok 3 menjawab pertanyaan ‘pernah apa’. Pelajari lagi: B4-07 dan B4-14.", "bab": null, "remed": ["B4-07", "B4-14"]}, {"ind": "4.4", "stem": "Siti menyusun jikoshoukai berikut:\n「はじめまして。シティと申します。インドネシアのスラバヤから参りました。二十一歳です。日本語を一年勉強しました。どうぞよろしくお願いいたします。」\n(Hajimemashite. Shiti to moushimasu. Indoneshia no Surabaya kara mairimashita. Nijuuissai desu. Nihongo o ichinen benkyou shimashita. Douzo yoroshiku onegai itashimasu. “Salam kenal. Nama saya Siti. Saya berasal dari Surabaya, Indonesia. Usia saya 21 tahun. Saya belajar bahasa Jepang satu tahun. Mohon bimbingan dan kerja samanya.”)\nBagian apa yang belum ada?", "opts": ["Salam dan nama", "Asal dan usia", "Latar belakang", "Kelebihan dan motivasi"], "key": "D", "exp": "Siti sudah menyebut salam, nama, asal, usia, dan latar belakang, tetapi langsung menutup tanpa menyebut kelebihan (blok 4) dan motivasi (blok 5).", "ok": "Tepat! Siti belum menjawab ‘bisa apa’ dan ‘mau apa’.", "no": "Kurang tepat. Periksa setiap kalimat Siti dengan lima pertanyaan pengingat, lalu cari yang belum terjawab. Pelajari lagi: B4-05 dan B4-14.", "bab": null, "remed": ["B4-05", "B4-14"]}, {"ind": "4.5", "stem": "Rekaman jikoshoukai Andi berdurasi 5 detik: 「アンディです。二十歳です。よろしく。」 (Andi desu. Hatachi desu. Yoroshiku. “Saya Andi. 20 tahun. Salam kenal.”) Apa kesalahan utamanya?", "opts": ["Terlalu singkat dan penutupnya kurang sopan.", "Terlalu panjang sehingga menjadi 自己PR (jiko PR).", "Intonasi naik di akhir setiap kalimat.", "Salah membaca usia 20 tahun."], "key": "A", "exp": "Andi hanya menyebut dua blok dan menutup dengan よろしく (yoroshiku) yang santai. B kebalikannya, C tidak bisa disimpulkan dari teks, dan D keliru karena 二十歳 memang dibaca hatachi.", "ok": "Tepat! Lengkapi lima blok dan tutup dengan どうぞよろしくお願いいたします.", "no": "Kurang tepat. Hitung berapa blok yang Andi sebutkan dan perhatikan bentuk penutupnya. Pelajari lagi: B4-13.", "bab": null, "remed": ["B4-13"]}, {"ind": "4.5", "stem": "Analisis rekaman latihanmu menunjukkan: “Durasi 70 detik, 0 jeda.” Perbaikan yang paling tepat adalah …", "opts": ["Berbicara lebih cepat agar durasinya di bawah 60 detik.", "Menambah blok baru agar isinya lebih lengkap.", "Meringkas isi setiap blok dan memberi jeda napas di akhir setiap blok.", "Mengecilkan suara agar terdengar lebih sopan."], "key": "C", "exp": "durasi terlalu panjang dan tanpa jeda berarti isinya perlu diringkas dan diberi jeda. A membuat bicara makin terburu-buru, B menambah durasi, dan D membuat suara sulit didengar.", "ok": "Tepat! Ringkas isinya, lalu beri jeda di akhir setiap blok.", "no": "Kurang tepat. Bicara lebih cepat atau lebih pelan tidak memperbaiki masalahnya. Perhatikan isi yang terlalu panjang dan jeda yang tidak ada. Pelajari lagi: B4-12 dan B4-13.", "bab": null, "remed": ["B4-12", "B4-13"]}], "glos": [{"jp": "自己紹介", "ro": "jikoshoukai", "ar": "perkenalan diri", "kat": "wawancara", "k": 2}, {"jp": "自己PR", "ro": "jiko PR", "ar": "promosi diri (menjelaskan kelebihan secara mendalam)", "kat": "wawancara", "k": 3}, {"jp": "はじめまして", "ro": "hajimemashite", "ar": "salam kenal", "kat": "sopan", "k": 5}, {"jp": "と申します", "ro": "to moushimasu", "ar": "nama saya … (sopan)", "kat": "sopan", "k": 5}, {"jp": "参りました", "ro": "mairimashita", "ar": "datang, berasal dari (sopan)", "kat": "sopan", "k": 5}, {"jp": "歳", "ro": "sai", "ar": "tahun (usia); 二十歳 dibaca hatachi", "kat": "angka", "k": 1}, {"jp": "卒業", "ro": "sotsugyou", "ar": "lulus sekolah", "kat": "wawancara", "k": 6}, {"jp": "合格", "ro": "goukaku", "ar": "lulus ujian", "kat": "wawancara", "k": 6}, {"jp": "日本語能力試験", "ro": "nihongo nouryoku shiken", "ar": "Japanese Language Proficiency Test (JLPT)", "kat": "wawancara", "k": 6}, {"jp": "工場", "ro": "koujou", "ar": "pabrik", "kat": "kerja", "k": 6}, {"jp": "長所", "ro": "chousho", "ar": "kelebihan", "kat": "wawancara", "k": 3}, {"jp": "技術", "ro": "gijutsu", "ar": "keterampilan kerja, teknik", "kat": "kerja", "k": 8}, {"jp": "一生懸命", "ro": "isshoukenmei", "ar": "dengan sungguh-sungguh", "kat": "wawancara", "k": 8}, {"jp": "御社", "ro": "onsha", "ar": "perusahaan Anda (lisan, sopan)", "kat": "sopan", "k": 8}, {"jp": "どうぞよろしくお願いいたします", "ro": "douzo yoroshiku onegai itashimasu", "ar": "mohon bimbingan dan kerja samanya", "kat": "sopan", "k": 8}]}, {"no": 5, "label": "Bab 5", "title": "Menjawab Pertanyaan", "kj": "質疑応答", "kjr": "shitsugi outou · tanya jawab", "col": "#5B46A8", "colL": "#ECE7FA", "dur": "±15 menit", "lessons": ["Pola Menjawab", "Pertanyaan Umum dan Tak Terduga", "Tidak Paham dan Jujur", "Bertanya Balik", "Latihan Lisan"], "blurb": "Pewawancara akan bertanya lebih jauh tentang dirimu. Kamu belajar memahami pertanyaan, termasuk yang tak terduga, lalu menjawab dengan jelas dan jujur.", "slides": ["B5-01", "B5-02", "B5-03", "B5-04", "B5-05", "B5-06", "B5-07", "B5-08", "B5-09", "B5-10", "B5-11", "B5-12", "B5-13", "B5-14", "B5-15"], "kuis": [{"ind": "5.1", "stem": "Dengarkan pertanyaan pewawancara. Pewawancara menanyakan tentang …\nTranskrip (ditampilkan setelah menjawab): 「日本で働きたい一番の理由は何ですか。」 (Nihon de hatarakitai ichiban no riyuu wa nan desu ka. “Apa alasan utamamu ingin bekerja di Jepang?”)", "opts": ["Pengalaman kerjamu sebelumnya", "Alasan utamamu ingin bekerja di Jepang", "Kemampuan bahasa Jepangmu", "Berapa lama kamu ingin tinggal di Jepang"], "key": "B", "exp": "kata kunci 理由 (riyuu, alasan) dan 日本で働きたい (Nihon de hatarakitai, ingin bekerja di Jepang) menunjukkan pertanyaan tentang motivasi.", "ok": "Tepat! Kamu menangkap kata 理由 (riyuu, alasan).", "no": "Kurang tepat. Dengarkan lagi dan cari kata yang berarti ‘alasan’. Pelajari lagi: B5-04 dan B5-08.", "bab": null, "remed": ["B5-04", "B5-08"]}, {"ind": "5.1", "stem": "Dengarkan pertanyaan pewawancara. Pewawancara menanyakan tentang …\nTranskrip (ditampilkan setelah menjawab): 「十年後、どんな人になっていたいですか。」 (Juunengo, donna hito ni natte itai desu ka. “Sepuluh tahun lagi, kamu ingin menjadi orang seperti apa?”)", "opts": ["Tujuanmu di masa depan", "Pengalamanmu sepuluh tahun yang lalu", "Kekurangan yang ingin kamu perbaiki", "Lama kontrak kerjamu di Jepang"], "key": "A", "exp": "十年後 (juunengo) berarti “sepuluh tahun lagi”, jadi pertanyaannya tentang masa depan. B keliru karena 後 (go) berarti “setelah”, bukan “yang lalu”.", "ok": "Tepat! 十年後 (juunengo) = sepuluh tahun lagi.", "no": "Kurang tepat. Perhatikan kata 後 (go): artinya ‘setelah’ atau ‘lagi’. Pelajari lagi: B5-07 dan B5-08.", "bab": null, "remed": ["B5-07", "B5-08"]}, {"ind": "5.2", "stem": "Pewawancara bertanya 「志望動機を教えてください。」 (Shibou douki o oshiete kudasai. “Ceritakan alasanmu melamar ke perusahaan ini.”) Perusahaannya adalah pabrik makanan. Jawaban mana yang paling tepat?", "opts": ["「給料が高いからです。それだけです。」 (Kyuuryou ga takai kara desu. Sore dake desu. “Karena gajinya tinggi. Itu saja.”)", "「友達も行くので、私も一緒に行きたいです。」 (Tomodachi mo iku node, watashi mo issho ni ikitai desu. “Karena teman saya juga berangkat, saya ingin ikut.”)", "「御社で食品づくりの技術を学んで、一生懸命働きたいからです。」 (Onsha de shokuhin-zukuri no gijutsu o manande, isshoukenmei hatarakitai kara desu. “Karena saya ingin mempelajari teknik pembuatan makanan di perusahaan Bapak/Ibu dan bekerja dengan sungguh-sungguh.”)", "「分かりません。会社が決めてください。」 (Wakarimasen. Kaisha ga kimete kudasai. “Saya tidak tahu. Silakan perusahaan yang menentukan.”)"], "key": "C", "exp": "C menyebut hal spesifik tentang perusahaan dan menunjukkan semangat. A hanya soal uang, B tidak menunjukkan alasan pribadi, dan D tidak menjawab.", "ok": "Tepat! Kamu menghubungkan perusahaan dengan apa yang ingin kamu pelajari.", "no": "Kurang tepat. Alasan melamar yang baik menyebut sesuatu tentang perusahaan dan apa yang ingin kamu pelajari atau berikan. Pelajari lagi: B5-03 dan B5-04.", "bab": null, "remed": ["B5-03", "B5-04"]}, {"ind": "5.2", "stem": "Pewawancara bertanya 「あなたの短所は何ですか。」 (Anata no tansho wa nan desu ka. “Apa kekuranganmu?”) Jawaban mana yang paling tepat?", "opts": ["「短所はありません。」 (Tansho wa arimasen. “Saya tidak punya kekurangan.”)", "「心配しすぎることです。でも、メモを取って確認するようにしています。」 (Shinpai shisugiru koto desu. Demo, memo o totte kakunin suru you ni shite imasu. “Saya terlalu khawatir. Tetapi, saya selalu mencatat dan memeriksa ulang.”)", "「よく遅刻することです。」 (Yoku chikoku suru koto desu. “Saya sering terlambat.”)", "「たくさんあるので、言えません。」 (Takusan aru node, iemasen. “Terlalu banyak, jadi tidak bisa saya sebutkan.”)"], "key": "B", "exp": "B menyebut kekurangan yang nyata tetapi tidak berbahaya, lalu usaha memperbaikinya. A tidak jujur, C kekurangan yang fatal bagi pekerjaan, dan D menghindari pertanyaan.", "ok": "Tepat! Kekurangan yang jujur ditambah usaha memperbaikinya.", "no": "Kurang tepat. Kekurangan yang baik disebutkan itu nyata, tidak membahayakan pekerjaan, dan disertai usaha memperbaikinya. Pelajari lagi: B5-05.", "bab": null, "remed": ["B5-05"]}, {"ind": "5.2", "stem": "Kamu sudah lulus N4, tetapi masih kesulitan dengan kata-kata sulit. Pewawancara bertanya 「日本語はどのくらいできますか。」 (Nihongo wa dono kurai dekimasu ka. “Seberapa baik bahasa Jepangmu?”) Jawaban mana yang paling tepat?", "opts": ["「N4に合格しました。まだ難しい言葉もありますが、毎日勉強しています。」 (N4 ni goukaku shimashita. Mada muzukashii kotoba mo arimasu ga, mainichi benkyou shite imasu. “Saya lulus N4. Masih ada kata yang sulit, tetapi saya belajar setiap hari.”)", "「全部分かります。N2と同じぐらいです。」 (Zenbu wakarimasu. N2 to onaji gurai desu. “Saya paham semuanya. Setara N2.”)", "「少しだけです。」 (Sukoshi dake desu. “Hanya sedikit.”)", "「日本語はできません。」 (Nihongo wa dekimasen. “Saya tidak bisa bahasa Jepang.”)"], "key": "A", "exp": "A jujur tentang level dan menunjukkan usaha belajar. B melebih-lebihkan, sedangkan C dan D terlalu merendah sehingga tidak akurat.", "ok": "Tepat! Jujur tentang levelmu dan tunjukkan usaha belajar.", "no": "Kurang tepat. Melebih-lebihkan dan terlalu merendah sama-sama tidak akurat. Sebut levelmu apa adanya. Pelajari lagi: B5-06 dan B5-10.", "bab": null, "remed": ["B5-06", "B5-10"]}, {"ind": "5.2", "stem": "Kontrak kerja Rani di Jepang berlaku tiga tahun. Pewawancara bertanya 「日本でどのくらい働きたいですか。」 (Nihon de dono kurai hatarakitai desu ka. “Berapa lama kamu ingin bekerja di Jepang?”) Jawaban mana yang paling meyakinkan pewawancara?", "opts": ["「分かりません。」 (Wakarimasen. “Saya tidak tahu.”)", "「一か月ぐらいです。」 (Ikkagetsu gurai desu. “Sekitar satu bulan.”)", "「お金がたまったら、すぐ帰ります。」 (Okane ga tamattara, sugu kaerimasu. “Begitu uangnya terkumpul, saya langsung pulang.”)", "「契約の三年間、最後までがんばりたいです。」 (Keiyaku no sannenkan, saigo made ganbaritai desu. “Saya ingin berusaha sampai akhir selama masa kontrak tiga tahun.”)"], "key": "D", "exp": "pertanyaan ini menguji kemauan bertahan bekerja (定着意欲, teichaku iyoku). D menunjukkan komitmen sampai kontrak selesai. A ragu-ragu, B tidak sesuai kontrak, dan C menunjukkan akan berhenti di tengah jalan.", "ok": "Tepat! Pewawancara ingin yakin kamu bertahan sampai kontrak selesai.", "no": "Kurang tepat. Pikirkan apa yang dikhawatirkan perusahaan: pekerja yang berhenti di tengah jalan. Pelajari lagi: B5-07.", "bab": null, "remed": ["B5-07"]}, {"ind": "5.3", "stem": "Pewawancara bertanya 「残業は大丈夫ですか。」 (Zangyou wa daijoubu desu ka.) dan kamu tidak tahu arti kata 残業 (zangyou). (Arti kata ini sengaja tidak ditampilkan.) Apa yang sebaiknya kamu lakukan?", "opts": ["Mengangguk dan menjawab 「はい」 (hai, “ya”) meskipun tidak paham.", "Diam sampai pewawancara mengganti pertanyaan.", "Bertanya 「すみません、「残業」はどういう意味ですか。」 (Sumimasen, “zangyou” wa dou iu imi desu ka. “Maaf, apa arti ‘zangyou’?”)", "Menjawab dengan cerita tentang topik lain yang kamu kuasai."], "key": "C", "exp": "bertanya arti kata adalah cara jujur dan sopan. A berisiko menyetujui hal yang tidak kamu pahami (残業 berarti lembur), B membuat suasana canggung, dan D tidak menjawab pertanyaan.", "ok": "Tepat! Tanyakan kata yang tidak kamu pahami. (残業, zangyou = lembur.)", "no": "Kurang tepat. Menjawab ‘ya’ tanpa paham bisa berarti menyetujui sesuatu yang tidak kamu ketahui. Pelajari lagi: B5-09.", "bab": null, "remed": ["B5-09"]}, {"ind": "5.3", "stem": "Pewawancara berbicara sangat cepat, dan kamu hanya menangkap separuh pertanyaannya. Apa yang paling tepat kamu ucapkan?", "opts": ["Menebak maksudnya dan menjawab panjang agar terlihat percaya diri.", "「え？何？」 (E? Nani? “Hah? Apa?”)", "「分かりません。」 (Wakarimasen. “Saya tidak mengerti.”), lalu diam.", "「すみません、ゆっくり話していただけませんか。」 (Sumimasen, yukkuri hanashite itadakemasen ka. “Maaf, bisakah Bapak/Ibu berbicara lebih pelan?”)"], "key": "D", "exp": "D meminta dengan sopan agar pewawancara berbicara pelan. A berisiko jawaban tidak nyambung, B terlalu santai, dan C tidak memberi jalan keluar.", "ok": "Tepat! Minta pewawancara berbicara pelan dengan bahasa yang sopan.", "no": "Kurang tepat. Pilih cara yang sopan dan membuat percakapan bisa berlanjut. Pelajari lagi: B5-09.", "bab": null, "remed": ["B5-09"]}, {"ind": "5.4", "stem": "Pewawancara bertanya 「何か質問はありますか。」 (Nanika shitsumon wa arimasu ka. “Apakah ada pertanyaan?”) Pertanyaan balik mana yang paling baik?", "opts": ["「給料はいくらですか。休みは多いですか。」 (Kyuuryou wa ikura desu ka. Yasumi wa ooi desu ka. “Berapa gajinya? Apakah liburnya banyak?”)", "「日本に行く前に、勉強しておいたほうがいいことはありますか。」 (Nihon ni iku mae ni, benkyou shite oita hou ga ii koto wa arimasu ka. “Apakah ada yang sebaiknya saya pelajari sebelum berangkat ke Jepang?”)", "「いいえ、ありません。」 (Iie, arimasen. “Tidak, tidak ada.”)", "「この会社は何の会社ですか。」 (Kono kaisha wa nan no kaisha desu ka. “Ini perusahaan apa?”)"], "key": "B", "exp": "B menunjukkan kemauan bersiap dan belajar. A langsung soal keuntungan diri, C terkesan pasif, dan D menunjukkan tidak mencari tahu tentang perusahaan.", "ok": "Tepat! Pertanyaan tentang persiapan menunjukkan kesungguhanmu.", "no": "Kurang tepat. Pertanyaan balik yang baik menunjukkan minat pada pekerjaan dan kemauan belajar. Pelajari lagi: B5-11.", "bab": null, "remed": ["B5-11"]}, {"ind": "5.4", "stem": "Saat 逆質問 (gyaku shitsumon), Andi bertanya 「この会社は何をしている会社ですか。」 (Kono kaisha wa nani o shite iru kaisha desu ka. “Perusahaan ini bergerak di bidang apa?”) Mengapa pertanyaan ini kurang tepat?", "opts": ["Karena menunjukkan Andi tidak mencari tahu tentang perusahaan sebelum wawancara.", "Karena tata bahasa Jepangnya terlalu sulit untuk level N4.", "Karena 逆質問 seharusnya selalu tentang gaji dan libur.", "Karena pertanyaan balik seharusnya lebih panjang."], "key": "A", "exp": "bidang usaha perusahaan adalah hal dasar yang seharusnya dicari tahu sebelum wawancara (Bab 1). B tidak tepat karena kalimatnya sederhana, C keliru, dan D tidak relevan.", "ok": "Tepat! Hal dasar tentang perusahaan seharusnya sudah kamu cari tahu sebelum wawancara.", "no": "Kurang tepat. Pikirkan kesan apa yang muncul jika kandidat tidak tahu bidang usaha perusahaan yang ia lamar. Pelajari lagi: B5-11.", "bab": null, "remed": ["B5-11"]}], "glos": [{"jp": "質疑応答", "ro": "shitsugi outou", "ar": "tanya jawab", "kat": "wawancara", "k": -1}, {"jp": "志望動機", "ro": "shibou douki", "ar": "alasan melamar", "kat": "wawancara", "k": 1}, {"jp": "理由", "ro": "riyuu", "ar": "alasan", "kat": "wawancara", "k": 2}, {"jp": "長所 / 短所", "ro": "chousho / tansho", "ar": "kelebihan / kekurangan", "kat": "wawancara", "k": 4}, {"jp": "体力", "ro": "tairyoku", "ar": "stamina fisik", "kat": "kerja", "k": 4}, {"jp": "得意 / 苦手", "ro": "tokui / nigate", "ar": "mahir / kurang mahir", "kat": "wawancara", "k": 5}, {"jp": "経験", "ro": "keiken", "ar": "pengalaman", "kat": "kerja", "k": 3}, {"jp": "契約", "ro": "keiyaku", "ar": "kontrak", "kat": "kerja", "k": 6}, {"jp": "将来の目標", "ro": "shourai no mokuhyou", "ar": "tujuan masa depan", "kat": "wawancara", "k": 6}, {"jp": "定着意欲", "ro": "teichaku iyoku", "ar": "kemauan bertahan bekerja", "kat": "wawancara", "k": 6}, {"jp": "残業", "ro": "zangyou", "ar": "lembur", "kat": "kerja", "k": -1}, {"jp": "給料", "ro": "kyuuryou", "ar": "gaji", "kat": "kerja", "k": 10}, {"jp": "もう一度お願いします", "ro": "mou ichido onegai shimasu", "ar": "mohon diulang sekali lagi", "kat": "sopan", "k": 8}, {"jp": "ゆっくり話していただけませんか", "ro": "yukkuri hanashite itadakemasen ka", "ar": "bisakah berbicara lebih pelan?", "kat": "sopan", "k": 8}, {"jp": "どういう意味ですか", "ro": "dou iu imi desu ka", "ar": "apa artinya?", "kat": "sopan", "k": 8}, {"jp": "逆質問", "ro": "gyaku shitsumon", "ar": "pertanyaan balik dari kandidat", "kat": "wawancara", "k": 10}]}, {"no": 6, "label": "Bab 6", "title": "Taishitsu", "kj": "退室", "kjr": "taishitsu · keluar ruangan", "col": "#23784A", "colL": "#E1F3E8", "dur": "±8 menit", "lessons": ["Langkah Keluar Ruangan", "Setelah Keluar Ruangan", "Latihan"], "blurb": "Kesan terakhir sama pentingnya dengan kesan pertama. Di bab ini kamu belajar menutup wawancara dan keluar ruangan dengan baik.", "slides": ["B6-01", "B6-02", "B6-03", "B6-04", "B6-05", "B6-06", "B6-07", "B6-08", "B6-09", "B6-10", "B6-11"], "kuis": [{"ind": "6.1", "stem": "Pewawancara berkata 「以上で面接を終わります。」 (Ijou de mensetsu o owarimasu. “Dengan ini wawancara selesai.”) Urutan langkah yang benar adalah …", "opts": ["Berdiri → langsung berjalan ke pintu → keluar tanpa salam → menutup pintu", "Berterima kasih sambil berjalan ke pintu → keluar → menutup pintu dari luar", "Berterima kasih sambil duduk → berterima kasih lagi di samping kursi dan ojigi → salam dan ojigi di pintu → keluar", "Salam di pintu → kembali ke kursi untuk berterima kasih → ojigi → keluar"], "key": "C", "exp": "urutannya: duduk, samping kursi, pintu, keluar. A tanpa salam, B berbicara sambil berjalan, dan D urutannya terbalik.", "ok": "Tepat! Kursi, samping kursi, pintu, lalu keluar.", "no": "Kurang tepat. Ikuti arah gerakmu: dari kursi, ke samping kursi, lalu ke pintu, dengan salam di setiap titik. Pelajari lagi: B6-03.", "bab": null, "remed": ["B6-03"]}, {"ind": "6.1", "stem": "Kamu sudah sampai di depan pintu ruang wawancara. Apa yang kamu lakukan sebelum membuka pintu?", "opts": ["Berbalik menghadap pewawancara, mengucapkan 「失礼します」 (shitsurei shimasu, “permisi”), lalu ojigi.", "Langsung membuka pintu tanpa menoleh agar tidak membuang waktu pewawancara.", "Melambaikan tangan kepada pewawancara sambil tersenyum lebar.", "Menanyakan kapan hasil wawancara akan diumumkan."], "key": "A", "exp": "salam terakhir di depan pintu menutup wawancara dengan sopan. B membelakangi pewawancara tanpa salam, C terlalu santai, dan D bukan waktunya bertanya.", "ok": "Tepat! Berbalik, 「失礼します」, ojigi, baru keluar.", "no": "Kurang tepat. Sebelum keluar, ada satu salam terakhir yang diucapkan sambil menghadap pewawancara. Pelajari lagi: B6-06.", "bab": null, "remed": ["B6-06"]}, {"ind": "6.1", "stem": "Karena terburu-buru, Dimas membanting pintu saat keluar ruang wawancara. Mengapa ini menjadi masalah?", "opts": ["Karena kandidat seharusnya membiarkan pintu terbuka untuk kandidat berikutnya.", "Karena menutup pintu adalah tugas staf perusahaan, bukan kandidat.", "Karena kandidat seharusnya keluar lewat pintu yang berbeda.", "Karena penilaian masih berlangsung, dan pintu yang dibanting memberi kesan kasar."], "key": "D", "exp": "sikap saat keluar ikut dinilai, dan suara pintu yang keras terkesan tidak sopan. A, B, dan C tidak sesuai etika masuk dan keluar ruangan yang dipelajari.", "ok": "Tepat! Penilaian belum selesai sampai kamu keluar, jadi tutup pintu dengan pelan.", "no": "Kurang tepat. Kandidat memang menutup pintu sendiri; masalahnya ada pada caranya. Pelajari lagi: B6-02 dan B6-06.", "bab": null, "remed": ["B6-02", "B6-06"]}, {"ind": "6.1", "stem": "Kamu baru saja mengucapkan terima kasih sambil duduk. Apa langkah berikutnya?", "opts": ["Langsung berjalan ke pintu sambil merapikan isi tas.", "Berdiri di samping kursi, mengucapkan terima kasih lagi, lalu ojigi dalam.", "Tetap duduk sampai pewawancara keluar ruangan lebih dulu.", "Menyalami tangan pewawancara satu per satu."], "key": "B", "exp": "setelah berdiri, berhenti dulu di samping kursi untuk ucapan terima kasih dan ojigi. A melewatkan langkah itu, C keliru karena kandidat yang keluar, dan D bukan kebiasaan dalam wawancara di Jepang.", "ok": "Tepat! Samping kursi, terima kasih, lalu 最敬礼 (saikeirei).", "no": "Kurang tepat. Ada satu titik berhenti antara kursi dan pintu. Pelajari lagi: B6-04 dan B6-05.", "bab": null, "remed": ["B6-04", "B6-05"]}, {"ind": "6.2", "stem": "Saat berdiri di samping kursi di akhir wawancara, ungkapan yang paling tepat adalah …", "opts": ["「じゃあ、また。」 (Jaa, mata. “Dah, sampai jumpa.”)", "「さようなら。」 (Sayounara. “Selamat tinggal.”)", "「ありがとうございました。」 (Arigatou gozaimashita. “Terima kasih banyak.”)", "「どうぞ。」 (Douzo. “Silakan.”)"], "key": "C", "exp": "ucapan terima kasih yang sopan diikuti ojigi dalam. A santai, B terdengar seperti perpisahan sehari-hari, dan D adalah ucapan untuk mempersilakan orang lain.", "ok": "Tepat! 「ありがとうございました」, lalu 最敬礼 (saikeirei).", "no": "Kurang tepat. Di samping kursi, yang diucapkan adalah terima kasih yang sopan, bukan salam perpisahan. Pelajari lagi: B6-05.", "bab": null, "remed": ["B6-05"]}, {"ind": "6.2", "stem": "Di depan pintu, sebelum keluar ruangan, ungkapan yang paling tepat adalah …", "opts": ["「失礼します。」 (Shitsurei shimasu. “Permisi.”)", "「はじめまして。」 (Hajimemashite. “Salam kenal.”)", "「お疲れさまでした。」 (Otsukaresama deshita. “Terima kasih atas kerja kerasnya.”)", "「よろしく。」 (Yoroshiku. “Salam kenal ya.”)"], "key": "A", "exp": "「失礼します」 dipakai saat masuk dan keluar ruangan. B untuk pertemuan pertama, C diucapkan antarrekan kerja dan tidak tepat untuk pewawancara, dan D terlalu santai.", "ok": "Tepat! 「失礼します」 membuka dan menutup kehadiranmu di ruangan.", "no": "Kurang tepat. Ingat ungkapan yang sama dengan saat kamu masuk ruangan di Bab 3. Pelajari lagi: B6-06 dan B6-09.", "bab": null, "remed": ["B6-06", "B6-09"]}, {"ind": "6.2", "stem": "Rina berdiri di samping kursi dan membungkuk dalam sambil mengucapkan 「ありがとうございました」 (arigatou gozaimashita, “terima kasih banyak”) pada saat yang sama. Apa yang sebaiknya diperbaiki?", "opts": ["Membungkuk lebih dangkal, cukup ±15°.", "Tidak perlu mengucapkan apa pun, cukup membungkuk.", "Mengganti ucapannya dengan 「さようなら」 (sayounara, “selamat tinggal”).", "Mengucapkan terima kasih dulu, baru membungkuk."], "key": "D", "exp": "prinsip 語先後礼 (gosen gorei): kata dulu, baru membungkuk. A terlalu dangkal untuk terima kasih penutup, B menghilangkan ucapan, dan C tidak sopan untuk wawancara.", "ok": "Tepat! Kata dulu, baru membungkuk, seperti di Bab 3.", "no": "Kurang tepat. Kedalaman ojigi dan ucapannya sudah benar; perhatikan urutan bicara dan membungkuk. Pelajari lagi: B6-05.", "bab": null, "remed": ["B6-05"]}, {"ind": "6.3", "stem": "Kamu sudah keluar dari ruang wawancara, tetapi masih berada di lorong kantor. Apa yang sebaiknya kamu lakukan?", "opts": ["Menelepon teman untuk menceritakan jalannya wawancara.", "Melonggarkan dasi dan duduk santai di kursi lorong.", "Tetap bersikap sopan, berterima kasih kepada resepsionis, lalu keluar gedung dengan tenang.", "Kembali ke ruang wawancara untuk menanyakan hasilnya."], "key": "C", "exp": "penilaian berlangsung sampai kamu keluar gedung. A dan B terlihat tidak sopan di area kantor, sedangkan D mengganggu proses wawancara.", "ok": "Tepat! Tetap sopan sampai kamu benar-benar keluar gedung.", "no": "Kurang tepat. Kamu masih di dalam kantor, jadi sikapmu masih terlihat. Pelajari lagi: B6-07.", "bab": null, "remed": ["B6-07"]}, {"ind": "6.3", "stem": "Wawancara sudah selesai dan kamu sudah keluar gedung. Menurut prinsip Hou-Ren-Sou, apa yang sebaiknya kamu lakukan?", "opts": ["Menunggu sampai instruktur LPK bertanya tentang wawancaramu.", "Melapor ke instruktur LPK bahwa wawancara sudah selesai dan bagaimana jalannya.", "Mengunggah cerita wawancara beserta nama perusahaan ke media sosial.", "Langsung mendaftar ke perusahaan lain tanpa memberi tahu LPK."], "key": "B", "exp": "melapor atas inisiatif sendiri adalah 報告 (houkoku). A menunggu ditanya, C tidak menjaga kerahasiaan proses seleksi, dan D melewati LPK tanpa kabar.", "ok": "Tepat! Houkoku: laporkan sendiri tanpa menunggu ditanya.", "no": "Kurang tepat. Ingat prinsip houkoku dari Bab 2: lapor atas inisiatif sendiri. Pelajari lagi: B6-07.", "bab": null, "remed": ["B6-07"]}, {"ind": "6.3", "stem": "Pada wawancara online, pewawancara berkata 「本日はありがとうございました。」 (Honjitsu wa arigatou gozaimashita. “Terima kasih untuk hari ini.”) Apa yang paling tepat kamu lakukan?", "opts": ["Berterima kasih sambil menatap kamera, ojigi dari kursi, lalu menunggu perusahaan memutus sambungan.", "Langsung menekan tombol keluar begitu pewawancara selesai berbicara.", "Mematikan kamera, lalu langsung mengobrol dengan keluarga di ruangan.", "Menanyakan hasil wawancara saat itu juga sebelum sambungan diputus."], "key": "A", "exp": "pada wawancara online, salam penutup dilakukan sambil menatap kamera, dan kandidat menunggu perusahaan memutus sambungan. B terlalu cepat, C berisiko suaramu masih terdengar, dan D bukan waktunya.", "ok": "Tepat! Tatap kamera, berterima kasih, ojigi, lalu tunggu sampai sambungan diputus.", "no": "Kurang tepat. Etika penutup online mirip tatap muka: jangan pergi lebih dulu. Pelajari lagi: B6-08.", "bab": null, "remed": ["B6-08"]}], "glos": [{"jp": "退室", "ro": "taishitsu", "ar": "keluar ruangan", "kat": "wawancara", "k": -1}, {"jp": "以上で面接を終わります", "ro": "ijou de mensetsu o owarimasu", "ar": "dengan ini wawancara selesai", "kat": "sopan", "k": 3}, {"jp": "本日はありがとうございました", "ro": "honjitsu wa arigatou gozaimashita", "ar": "terima kasih banyak untuk hari ini", "kat": "sopan", "k": 3}, {"jp": "お忙しい中", "ro": "oisogashii naka", "ar": "di tengah kesibukan (Anda)", "kat": "sopan", "k": 3}, {"jp": "失礼いたします", "ro": "shitsurei itashimasu", "ar": "permisi (lebih sopan dari 失礼します)", "kat": "sopan", "k": 5}, {"jp": "失礼しました", "ro": "shitsurei shimashita", "ar": "permisi (bentuk lampau, juga dipakai saat keluar)", "kat": "sopan", "k": 5}, {"jp": "最敬礼", "ro": "saikeirei", "ar": "ojigi sangat hormat (±45°)", "kat": "wawancara", "k": 4}, {"jp": "報告", "ro": "houkoku", "ar": "melapor", "kat": "kerja", "k": 6}, {"jp": "先生", "ro": "sensei", "ar": "guru, instruktur", "kat": "kerja", "k": 6}, {"jp": "お疲れさまでした", "ro": "otsukaresama deshita", "ar": "terima kasih atas kerja kerasnya (antarrekan kerja, bukan untuk pewawancara)", "kat": "sopan", "k": 8}]}], "latih": [{"no": 1, "g": "A", "q": {"jp": "自己紹介をお願いします。", "ro": "Jikoshoukai o onegai shimasu.", "ar": "Silakan perkenalkan diri."}, "topik": "Jikoshoukai", "acuan": "B4-10", "inti": "", "a": {"jp": "はじめまして。ラニと申します。インドネシアのバンドンから参りました。二十三歳です。高校を卒業してから、工場で二年働いていました。日本語は一年勉強して、N4に合格しました。私の長所は、時間を守ることです。工場では二年間、一度も遅刻しませんでした。日本の会社で技術を学んで、一生懸命働きたいです。どうぞよろしくお願いいたします。", "ro": "Hajimemashite. Rani to moushimasu. Indoneshia no Bandon kara mairimashita. Nijuusansai desu. Koukou o sotsugyou shite kara, koujou de ninen hataraite imashita. Nihongo wa ichinen benkyou shite, N4 ni goukaku shimashita. Watashi no chousho wa, jikan o mamoru koto desu. Koujou de wa ninenkan, ichido mo chikoku shimasen deshita. Nihon no kaisha de gijutsu o manande, isshoukenmei hatarakitai desu. Douzo yoroshiku onegai itashimasu.", "ar": "Salam kenal. Nama saya Rani. Saya berasal dari Bandung, Indonesia. Usia saya 23 tahun. Setelah lulus SMK, saya bekerja di pabrik selama dua tahun. Saya belajar bahasa Jepang satu tahun dan lulus N4. Kelebihan saya adalah selalu tepat waktu. Selama dua tahun di pabrik, saya tidak pernah sekali pun terlambat. Saya ingin mempelajari keterampilan di perusahaan Jepang dan bekerja dengan sungguh-sungguh. Mohon bimbingan dan kerja samanya."}, "dari": "B4-10", "mirip": ""}, {"no": 2, "g": "A", "q": {"jp": "どうして日本で働きたいのですか。", "ro": "Doushite Nihon de hatarakitai no desu ka.", "ar": "Mengapa kamu ingin bekerja di Jepang?"}, "topik": "Motivasi ke Jepang", "acuan": "Bab 5", "inti": "", "a": {"jp": "日本の技術を学びたいからです。日本の会社は時間を守って、ていねいに仕事をすると聞きました。私もそのように働きたいです。", "ro": "Nihon no gijutsu o manabitai kara desu. Nihon no kaisha wa jikan o mamotte, teinei ni shigoto o suru to kikimashita. Watashi mo sono you ni hatarakitai desu.", "ar": "Karena saya ingin mempelajari keterampilan kerja Jepang. Saya dengar perusahaan Jepang tepat waktu dan bekerja dengan teliti. Saya juga ingin bekerja seperti itu."}, "dari": "B5-03", "mirip": "なぜ日本で働きたいですか。"}, {"no": 3, "g": "A", "q": {"jp": "当社を選んだ理由を教えてください。", "ro": "Tousha o eranda riyuu o oshiete kudasai.", "ar": "Mengapa kamu memilih perusahaan kami?"}, "topik": "Alasan memilih perusahaan", "acuan": "B5-04", "inti": "", "a": {"jp": "御社は食品工場で、安全な食品を作っていると知りました。私も前に工場で働いていたので、その経験を生かしたいです。", "ro": "Onsha wa shokuhin koujou de, anzen na shokuhin o tsukutte iru to shirimashita. Watashi mo mae ni koujou de hataraite ita node, sono keiken o ikashitai desu.", "ar": "Saya tahu perusahaan Bapak/Ibu adalah pabrik makanan yang membuat makanan yang aman. Karena saya pernah bekerja di pabrik, saya ingin memanfaatkan pengalaman itu."}, "dari": "B5-04", "mirip": "志望動機を教えてください。"}, {"no": 4, "g": "A", "q": {"jp": "あなたの長所は何ですか。", "ro": "Anata no chousho wa nan desu ka.", "ar": "Apa kelebihanmu?"}, "topik": "Kelebihan", "acuan": "Bab 5", "inti": "", "a": {"jp": "長所は、時間を守ることです。短所は、心配しすぎることです。でも、メモを取って、確認するようにしています。", "ro": "Chousho wa, jikan o mamoru koto desu. Tansho wa, shinpai shisugiru koto desu. Demo, memo o totte, kakunin suru you ni shite imasu.", "ar": "Kelebihan saya adalah tepat waktu. Kekurangan saya adalah terlalu khawatir. Tetapi, saya selalu mencatat dan memeriksa ulang."}, "dari": "B5-05", "mirip": "あなたの長所と短所を教えてください。"}, {"no": 5, "g": "A", "q": {"jp": "あなたの短所は何ですか。", "ro": "Anata no tansho wa nan desu ka.", "ar": "Apa kekuranganmu?"}, "topik": "Kekurangan", "acuan": "Bab 5", "inti": "", "a": {"jp": "長所は、時間を守ることです。短所は、心配しすぎることです。でも、メモを取って、確認するようにしています。", "ro": "Chousho wa, jikan o mamoru koto desu. Tansho wa, shinpai shisugiru koto desu. Demo, memo o totte, kakunin suru you ni shite imasu.", "ar": "Kelebihan saya adalah tepat waktu. Kekurangan saya adalah terlalu khawatir. Tetapi, saya selalu mencatat dan memeriksa ulang."}, "dari": "B5-05", "mirip": "あなたの長所と短所を教えてください。"}, {"no": 6, "g": "A", "q": {"jp": "体力に自信がありますか。", "ro": "Tairyoku ni jishin ga arimasu ka.", "ar": "Apakah kamu yakin dengan stamina fisikmu?"}, "topik": "Stamina", "acuan": "Bab 5", "inti": "", "a": {"jp": "はい、あります。毎日、五キロ走っています。立ち仕事も大丈夫です。", "ro": "Hai, arimasu. Mainichi, go-kiro hashitte imasu. Tachi shigoto mo daijoubu desu.", "ar": "Ya. Saya berlari lima kilometer setiap hari. Pekerjaan sambil berdiri juga tidak masalah."}, "dari": "B5-05", "mirip": ""}, {"no": 7, "g": "A", "q": {"jp": "日本語はどのくらい勉強しましたか。", "ro": "Nihongo wa dono kurai benkyou shimashita ka.", "ar": "Berapa lama kamu belajar bahasa Jepang?"}, "topik": "Bahasa Jepang", "acuan": "B5-06", "inti": "", "a": {"jp": "N4に合格しました。ゆっくり話していただければ、だいたい分かります。まだ難しい言葉もありますが、毎日勉強しています。", "ro": "N4 ni goukaku shimashita. Yukkuri hanashite itadakereba, daitai wakarimasu. Mada muzukashii kotoba mo arimasu ga, mainichi benkyou shite imasu.", "ar": "Saya lulus N4. Kalau Bapak/Ibu berbicara pelan, saya umumnya paham. Masih ada kata yang sulit, tetapi saya belajar setiap hari."}, "dari": "B5-06", "mirip": "日本語はどのくらいできますか。"}, {"no": 8, "g": "A", "q": {"jp": "前の仕事について教えてください。", "ro": "Mae no shigoto ni tsuite oshiete kudasai.", "ar": "Ceritakan pekerjaanmu sebelumnya."}, "topik": "Pengalaman kerja", "acuan": "Bab 5", "inti": "", "a": {"jp": "工場で二年間、部品の検査をしていました。毎日、決められた時間に正確に仕事をしました。", "ro": "Koujou de ninenkan, buhin no kensa o shite imashita. Mainichi, kimerareta jikan ni seikaku ni shigoto o shimashita.", "ar": "Saya memeriksa komponen di pabrik selama dua tahun. Setiap hari saya bekerja dengan teliti sesuai waktu yang ditentukan."}, "dari": "B5-06", "mirip": ""}, {"no": 9, "g": "A", "q": {"jp": "日本で何年ぐらい働きたいですか。", "ro": "Nihon de nannen gurai hatarakitai desu ka.", "ar": "Berapa tahun kamu ingin bekerja di Jepang?"}, "topik": "Lama bekerja", "acuan": "Bab 5", "inti": "", "a": {"jp": "契約の三年間、最後までがんばりたいです。", "ro": "Keiyaku no sannenkan, saigo made ganbaritai desu.", "ar": "Saya ingin berusaha sampai akhir selama masa kontrak tiga tahun."}, "dari": "B5-07", "mirip": "日本でどのくらい働きたいですか。"}, {"no": 10, "g": "B", "q": {"jp": "なぜ日本を選んだのですか。", "ro": "Naze Nihon o eranda no desu ka.", "ar": "Mengapa kamu memilih Jepang?"}, "topik": "Motivasi ke Jepang", "acuan": "", "inti": "", "a": {"jp": "日本の技術を学びたいからです。日本の会社は時間を守って、ていねいに仕事をすると聞きました。私もそのように働きたいです。", "ro": "Nihon no gijutsu o manabitai kara desu. Nihon no kaisha wa jikan o mamotte, teinei ni shigoto o suru to kikimashita. Watashi mo sono you ni hatarakitai desu.", "ar": "Karena saya ingin mempelajari keterampilan kerja Jepang. Saya dengar perusahaan Jepang tepat waktu dan bekerja dengan teliti. Saya juga ingin bekerja seperti itu."}, "dari": "B5-03", "mirip": "なぜ日本で働きたいですか。"}, {"no": 11, "g": "B", "q": {"jp": "この会社で働きたい理由は何ですか。", "ro": "Kono kaisha de hatarakitai riyuu wa nan desu ka.", "ar": "Apa alasanmu ingin bekerja di perusahaan ini?"}, "topik": "Alasan memilih perusahaan", "acuan": "", "inti": "", "a": {"jp": "御社は食品工場で、安全な食品を作っていると知りました。私も前に工場で働いていたので、その経験を生かしたいです。", "ro": "Onsha wa shokuhin koujou de, anzen na shokuhin o tsukutte iru to shirimashita. Watashi mo mae ni koujou de hataraite ita node, sono keiken o ikashitai desu.", "ar": "Saya tahu perusahaan Bapak/Ibu adalah pabrik makanan yang membuat makanan yang aman. Karena saya pernah bekerja di pabrik, saya ingin memanfaatkan pengalaman itu."}, "dari": "B5-04", "mirip": "志望動機を教えてください。"}, {"no": 12, "g": "B", "q": {"jp": "自分のいいところを教えてください。", "ro": "Jibun no ii tokoro o oshiete kudasai.", "ar": "Ceritakan sisi baik dirimu."}, "topik": "Kelebihan", "acuan": "", "inti": "", "a": {"jp": "長所は、時間を守ることです。短所は、心配しすぎることです。でも、メモを取って、確認するようにしています。", "ro": "Chousho wa, jikan o mamoru koto desu. Tansho wa, shinpai shisugiru koto desu. Demo, memo o totte, kakunin suru you ni shite imasu.", "ar": "Kelebihan saya adalah tepat waktu. Kekurangan saya adalah terlalu khawatir. Tetapi, saya selalu mencatat dan memeriksa ulang."}, "dari": "B5-05", "mirip": "あなたの長所と短所を教えてください。"}, {"no": 13, "g": "B", "q": {"jp": "自分の弱いところはどこだと思いますか。", "ro": "Jibun no yowai tokoro wa doko da to omoimasu ka.", "ar": "Menurutmu, apa kelemahanmu?"}, "topik": "Kekurangan", "acuan": "", "inti": "", "a": {"jp": "長所は、時間を守ることです。短所は、心配しすぎることです。でも、メモを取って、確認するようにしています。", "ro": "Chousho wa, jikan o mamoru koto desu. Tansho wa, shinpai shisugiru koto desu. Demo, memo o totte, kakunin suru you ni shite imasu.", "ar": "Kelebihan saya adalah tepat waktu. Kekurangan saya adalah terlalu khawatir. Tetapi, saya selalu mencatat dan memeriksa ulang."}, "dari": "B5-05", "mirip": "あなたの長所と短所を教えてください。"}, {"no": 14, "g": "B", "q": {"jp": "体は丈夫ですか。", "ro": "Karada wa joubu desu ka.", "ar": "Apakah badanmu sehat dan kuat?"}, "topik": "Stamina", "acuan": "", "inti": "", "a": {"jp": "はい、あります。毎日、五キロ走っています。立ち仕事も大丈夫です。", "ro": "Hai, arimasu. Mainichi, go-kiro hashitte imasu. Tachi shigoto mo daijoubu desu.", "ar": "Ya. Saya berlari lima kilometer setiap hari. Pekerjaan sambil berdiri juga tidak masalah."}, "dari": "B5-05", "mirip": "体力に自信がありますか。"}, {"no": 15, "g": "B", "q": {"jp": "日本語の勉強はどのくらいしましたか。", "ro": "Nihongo no benkyou wa dono kurai shimashita ka.", "ar": "Sudah berapa lama kamu belajar bahasa Jepang?"}, "topik": "Bahasa Jepang", "acuan": "", "inti": "", "a": {"jp": "N4に合格しました。ゆっくり話していただければ、だいたい分かります。まだ難しい言葉もありますが、毎日勉強しています。", "ro": "N4 ni goukaku shimashita. Yukkuri hanashite itadakereba, daitai wakarimasu. Mada muzukashii kotoba mo arimasu ga, mainichi benkyou shite imasu.", "ar": "Saya lulus N4. Kalau Bapak/Ibu berbicara pelan, saya umumnya paham. Masih ada kata yang sulit, tetapi saya belajar setiap hari."}, "dari": "B5-06", "mirip": "日本語はどのくらいできますか。"}, {"no": 16, "g": "B", "q": {"jp": "前の会社ではどんな仕事をしていましたか。", "ro": "Mae no kaisha de wa donna shigoto o shite imashita ka.", "ar": "Di perusahaan sebelumnya kamu bekerja sebagai apa?"}, "topik": "Pengalaman kerja", "acuan": "", "inti": "", "a": {"jp": "工場で二年間、部品の検査をしていました。毎日、決められた時間に正確に仕事をしました。", "ro": "Koujou de ninenkan, buhin no kensa o shite imashita. Mainichi, kimerareta jikan ni seikaku ni shigoto o shimashita.", "ar": "Saya memeriksa komponen di pabrik selama dua tahun. Setiap hari saya bekerja dengan teliti sesuai waktu yang ditentukan."}, "dari": "B5-06", "mirip": "前の仕事について教えてください。"}, {"no": 17, "g": "B", "q": {"jp": "五年後、何をしていたいですか。", "ro": "Gonengo, nani o shite itai desu ka.", "ar": "Lima tahun lagi, kamu ingin sedang melakukan apa?"}, "topik": "Tujuan masa depan", "acuan": "", "inti": "", "a": {"jp": "日本で学んだ技術を生かして、将来はインドネシアの工場でリーダーになりたいです。", "ro": "Nihon de mananda gijutsu o ikashite, shourai wa Indoneshia no koujou de riidaa ni naritai desu.", "ar": "Saya ingin memanfaatkan keterampilan yang saya pelajari di Jepang dan kelak menjadi pemimpin di pabrik di Indonesia."}, "dari": "B5-07", "mirip": "将来の目標は何ですか。"}, {"no": 18, "g": "C", "q": {"jp": "趣味は何ですか。", "ro": "Shumi wa nan desu ka.", "ar": "Apa hobimu?"}, "topik": "Kehidupan sehari-hari", "acuan": "", "inti": "", "a": {"jp": "サッカーです。週末によく友達とします。チームで動くのが好きです。", "ro": "Sakkaa desu. Shuumatsu ni yoku tomodachi to shimasu. Chiimu de ugoku no ga suki desu.", "ar": "Sepak bola. Saya sering bermain bersama teman di akhir pekan. Saya suka bergerak sebagai tim."}, "dari": "B5-08", "mirip": ""}, {"no": 19, "g": "C", "q": {"jp": "休みの日は何をしていますか。", "ro": "Yasumi no hi wa nani o shite imasu ka.", "ar": "Apa yang kamu lakukan di hari libur?"}, "topik": "Kehidupan sehari-hari", "acuan": "", "inti": "", "a": {"jp": "日本語の勉強をしたり、家の手伝いをしたりしています。", "ro": "Nihongo no benkyou o shitari, ie no tetsudai o shitari shite imasu.", "ar": "Saya belajar bahasa Jepang dan membantu pekerjaan rumah."}, "dari": "B5-08", "mirip": ""}, {"no": 20, "g": "C", "q": {"jp": "日本の食べ物で、何が好きですか。", "ro": "Nihon no tabemono de, nani ga suki desu ka.", "ar": "Makanan Jepang apa yang kamu sukai?"}, "topik": "Kehidupan sehari-hari", "acuan": "", "inti": "", "a": {"jp": "おにぎりが好きです。簡単で、おいしいからです。", "ro": "Onigiri ga suki desu. Kantan de, oishii kara desu.", "ar": "Saya suka onigiri karena praktis dan enak."}, "dari": "B5-08", "mirip": ""}, {"no": 21, "g": "C", "q": {"jp": "今朝、何を食べましたか。", "ro": "Kesa, nani o tabemashita ka.", "ar": "Tadi pagi kamu makan apa?"}, "topik": "Kehidupan sehari-hari", "acuan": "", "inti": "", "a": {"jp": "ご飯と卵を食べました。", "ro": "Gohan to tamago o tabemashita.", "ar": "Saya makan nasi dan telur."}, "dari": "B5-08", "mirip": ""}, {"no": 22, "g": "C", "q": {"jp": "インドネシアのいいところを教えてください。", "ro": "Indoneshia no ii tokoro o oshiete kudasai.", "ar": "Ceritakan hal baik tentang Indonesia."}, "topik": "Kehidupan sehari-hari", "acuan": "", "inti": "", "a": {"jp": "人がやさしいところです。私の町のバンドンは、すずしくて、食べ物もおいしいです。", "ro": "Hito ga yasashii tokoro desu. Watashi no machi no Bandon wa, suzushikute, tabemono mo oishii desu.", "ar": "Orangnya ramah. Kota saya, Bandung, sejuk dan makanannya enak."}, "dari": "B5-08", "mirip": ""}, {"no": 23, "g": "D", "q": {"jp": "機械が急に止まったら、どうしますか。", "ro": "Kikai ga kyuu ni tomattara, dou shimasu ka.", "ar": "Kalau mesin tiba-tiba berhenti, apa yang kamu lakukan?"}, "topik": "Situasi kerja", "acuan": "", "inti": "報告 (houkoku, melapor)", "a": {"jp": "すぐに上司に報告して、謝ります。そして、同じミスをしないように気をつけます。", "ro": "Sugu ni joushi ni houkoku shite, ayamarimasu. Soshite, onaji misu o shinai you ni ki o tsukemasu.", "ar": "Saya segera melapor ke atasan dan meminta maaf, lalu berhati-hati agar tidak mengulanginya."}, "dari": "B2-10", "mirip": "仕事でミスをしたら、どうしますか。"}, {"no": 24, "g": "D", "q": {"jp": "仕事のやり方が分からないとき、どうしますか。", "ro": "Shigoto no yarikata ga wakaranai toki, dou shimasu ka.", "ar": "Kalau tidak tahu cara mengerjakan tugas, apa yang kamu lakukan?"}, "topik": "Situasi kerja", "acuan": "", "inti": "相談 (soudan, berkonsultasi)", "a": {"jp": "自分で決めないで、先輩や上司に相談します。", "ro": "Jibun de kimenaide, senpai ya joushi ni soudan shimasu.", "ar": "Saya tidak memutuskan sendiri, tetapi berkonsultasi dengan senior atau atasan."}, "dari": "B2-10", "mirip": ""}, {"no": 25, "g": "D", "q": {"jp": "仕事に遅れそうなとき、どうしますか。", "ro": "Shigoto ni okuresou na toki, dou shimasu ka.", "ar": "Kalau kamu akan terlambat masuk kerja, apa yang kamu lakukan?"}, "topik": "Situasi kerja", "acuan": "", "inti": "連絡 (renraku, memberi kabar)", "a": {"jp": "仕事が始まる前に、すぐ会社に連絡します。", "ro": "Shigoto ga hajimaru mae ni, sugu kaisha ni renraku shimasu.", "ar": "Saya segera mengabari perusahaan sebelum jam kerja dimulai."}, "dari": "B2-10", "mirip": "遅刻しそうなとき、どうしますか。"}], "eval": [{"no": 7, "id": "sim", "label": "Evaluasi", "title": "Simulasi Mensetsu", "kj": "模擬面接", "kjr": "mogi mensetsu · simulasi", "col": "#1E2A47", "colL": "#E4E7EF", "dur": "±15 menit", "lessons": ["Fase A–E · 13 momen"], "blurb": "Wawancara utuh dengan Tanaka-san dari さくら食品: 13 momen, dari tiba di depan gedung sampai menutup wawancara."}, {"no": 8, "id": "post", "label": "Evaluasi", "title": "Post-test & Rapor", "kj": "修了", "kjr": "shuuryou · selesai", "col": "#7B3F2B", "colL": "#F6E6DF", "dur": "±15 menit", "lessons": ["Post-test 20 soal", "Rapor Kesiapan"], "blurb": "20 soal post-test, lalu Rapor Kesiapan berisi nilai sumatif, skor komunikasi dan etika, serta rekomendasi."}], "pre": [{"ind": "1.2", "stem": "Saat kamu menunggu di ruang tunggu, seorang staf perusahaan lewat di depanmu. Sikap yang paling tepat adalah …", "opts": ["Tetap duduk tegak dan memberi salam ringan dengan 会釈 (eshaku, ojigi ±15°).", "Pura-pura sibuk dengan HP agar tidak perlu menyapa.", "Mengajak staf mengobrol santai tentang gaji karyawan.", "Memejamkan mata sebentar agar terlihat tenang."], "key": "A", "exp": "Penilaian sudah dimulai sejak kamu tiba; staf yang kamu temui bisa ikut menyampaikan kesan. (B1-05, B1-06)", "ok": "", "no": "", "bab": 1, "remed": ["B1-05", "B1-06"]}, {"ind": "1.3", "stem": "Malam sebelum wawancara, persiapan yang paling tepat adalah …", "opts": ["Begadang menghafal seluruh kosakata N3 agar terlihat pintar.", "Menyiapkan 履歴書 (rirekisho, daftar riwayat hidup), pakaian, rute, waktu berangkat, dan nomor kontak perusahaan.", "Mencari tahu besaran gaji karyawan lain di perusahaan itu.", "Membeli pakaian baru berwarna mencolok agar mudah diingat."], "key": "B", "exp": "Persiapan meliputi dokumen, penampilan, waktu, dan kontak untuk renraku bila ada kendala. (B1-07 s.d. B1-09)", "ok": "", "no": "", "bab": 1, "remed": ["B1-07", "B1-09"]}, {"ind": "2.1", "stem": "Pernyataan yang paling tepat tentang 連絡 (renraku) adalah … (Arti istilah tidak ditampilkan karena soal ini menguji pemahamannya.)", "opts": ["Disampaikan setelah kejadian agar informasinya lengkap.", "Hanya disampaikan kepada atasan langsung.", "Menyampaikan fakta secepatnya kepada pihak yang perlu tahu.", "Sama dengan meminta saran sebelum mengambil keputusan."], "key": "C", "exp": "Renraku = mengabari pihak terkait secepatnya, sebelum kejadian. D adalah soudan. (B2-05, B2-07)", "ok": "", "no": "", "bab": 2, "remed": ["B2-05", "B2-07"]}, {"ind": "2.2", "stem": "Atasan memintamu memindahkan “barang yang di sana”, tetapi ada beberapa tumpukan barang dan kamu tidak yakin yang mana. Tindakan yang sesuai Hou-Ren-Sou adalah …", "opts": ["Memindahkan semua tumpukan barang agar pasti benar.", "Menunggu sampai atasan menjelaskan lagi tanpa bertanya.", "Menebak tumpukan yang paling mungkin, lalu memindahkannya.", "Bertanya kepada atasan barang mana yang dimaksud sebelum mulai."], "key": "D", "exp": "Saat ragu, 相談 (soudan, berkonsultasi) sebelum bertindak mencegah kesalahan. (B2-06)", "ok": "", "no": "", "bab": 2, "remed": ["B2-06"]}, {"ind": "2.3", "stem": "Pewawancara bertanya 「仕事が予定より遅れそうなとき、どうしますか。」 (Shigoto ga yotei yori okuresou na toki, dou shimasu ka. “Jika pekerjaanmu tampaknya akan terlambat dari jadwal, apa yang kamu lakukan?”) Jawaban mana yang paling tepat?", "opts": ["「最後まで黙ってがんばります。」 (Saigo made damatte ganbarimasu. “Saya diam saja dan berusaha sampai akhir.”)", "「残りの仕事は、次の日にします。」 (Nokori no shigoto wa, tsugi no hi ni shimasu. “Sisa pekerjaannya saya kerjakan besok.”)", "「早めに上司に報告して、相談します。」 (Hayame ni joushi ni houkoku shite, soudan shimasu. “Saya segera melapor ke atasan dan berkonsultasi.”)", "「同僚に全部お願いします。」 (Douryou ni zenbu onegai shimasu. “Saya minta rekan kerja mengerjakan semuanya.”)"], "key": "C", "exp": "Kabar buruk dilaporkan lebih awal (houkoku), lalu meminta arahan (soudan). A diam, B menunda tanpa kabar, D melempar tanggung jawab. (B2-04, B2-10)", "ok": "", "no": "", "bab": 2, "remed": ["B2-04", "B2-10"]}, {"ind": "3.1", "stem": "Kamu sudah mengetuk pintu tiga kali dan terdengar 「どうぞ」 (douzo, “silakan”). Langkah selanjutnya adalah …", "opts": ["Membuka pintu, mengucapkan 「失礼します」 (shitsurei shimasu, “permisi”), masuk, menutup pintu, lalu ojigi.", "Mengetuk sekali lagi untuk memastikan kamu benar-benar dipersilakan.", "Masuk, lalu langsung berjalan dan duduk di kursi.", "Membuka pintu dan menunggu pewawancara datang menjemput."], "key": "A", "exp": "Setelah dipersilakan: masuk dengan salam, tutup pintu dengan tenang, menghadap pewawancara, lalu ojigi. (B3-03 s.d. B3-05)", "ok": "", "no": "", "bab": 3, "remed": ["B3-03", "B3-05"]}, {"ind": "3.2", "stem": "Kamu sudah memperkenalkan diri singkat di samping kursi, tetapi pewawancara diam sejenak sambil membaca berkas dan belum mempersilakan duduk. Apa yang kamu lakukan?", "opts": ["Langsung duduk karena sudah cukup lama berdiri.", "Tetap berdiri tegak dan menunggu sampai dipersilakan duduk.", "Bertanya 「座ってもいい？」 (Suwatte mo ii? “Boleh duduk?”, bahasa santai).", "Meletakkan tas di atas meja, lalu duduk."], "key": "B", "exp": "Kandidat duduk setelah 「どうぞおかけください」 (douzo okake kudasai, “silakan duduk”). C memakai bahasa santai, D salah menempatkan tas. (B3-06)", "ok": "", "no": "", "bab": 3, "remed": ["B3-06"]}, {"ind": "3.3", "stem": "Ojigi dengan sudut sekitar 15° paling tepat dipakai saat …", "opts": ["Meminta maaf karena datang terlambat.", "Memperkenalkan diri kepada pewawancara di samping kursi.", "Berpapasan dengan staf perusahaan di lorong.", "Mengucapkan terima kasih penutup di akhir wawancara."], "key": "C", "exp": "会釈 (eshaku, ±15°) adalah salam ringan. A dan D memakai ojigi yang lebih dalam; B memakai 敬礼 (keirei, ±30°). (B3-08, B3-10)", "ok": "", "no": "", "bab": 3, "remed": ["B3-08", "B3-10"]}, {"ind": "3.4", "stem": "Di tengah wawancara, kakimu mulai terasa pegal. Sikap yang tetap tepat adalah …", "opts": ["Menyilangkan kaki agar lebih nyaman.", "Bersandar penuh ke sandaran kursi.", "Menggoyangkan kaki pelan-pelan agar tidak kaku.", "Tetap duduk tegak tanpa bersandar dan tidak menyilangkan kaki."], "key": "D", "exp": "Sikap duduk dinilai sampai wawancara selesai; A, B, dan C termasuk hal yang perlu dihindari. (B3-11)", "ok": "", "no": "", "bab": 3, "remed": ["B3-11"]}, {"ind": "4.1", "stem": "Mengapa sebaiknya kamu menyebutkan hal yang siap kamu jelaskan di dalam jikoshoukai?", "opts": ["Karena pewawancara sering bertanya lebih lanjut dari isi jikoshoukai.", "Agar jikoshoukai menjadi lebih panjang dan lengkap.", "Agar kamu tidak perlu menjawab pertanyaan lain.", "Karena semua pengalaman wajib disebutkan dalam jikoshoukai."], "key": "A", "exp": "Jikoshoukai berfungsi seperti “daftar isi” dirimu; pewawancara memilih hal yang akan ditanyakan dari isinya. (B4-03)", "ok": "", "no": "", "bab": 4, "remed": ["B4-03"]}, {"ind": "4.3", "stem": "Usia 20 tahun ditulis 二十歳. Dalam jikoshoukai, bacaan yang lazim dipakai adalah … (Soal ini menguji cara baca.)", "opts": ["ふたとし (futatoshi)", "はたち (hatachi)", "はつか (hatsuka)", "にじゅうにさい (nijuunisai)"], "key": "B", "exp": "二十歳 punya bacaan khusus hatachi. C (hatsuka) berarti tanggal 20, D berarti 22 tahun. (B4-06)", "ok": "", "no": "", "bab": 4, "remed": ["B4-06"]}, {"ind": "4.4", "stem": "Kalimat mana yang paling tepat untuk blok 4 (kelebihan) jikoshoukai?", "opts": ["「私は二十二歳です。」 (Watashi wa nijuunisai desu. “Saya berusia 22 tahun.”)", "「日本で働きたいです。」 (Nihon de hatarakitai desu. “Saya ingin bekerja di Jepang.”)", "「私の長所は、全部です。」 (Watashi no chousho wa, zenbu desu. “Kelebihan saya adalah semuanya.”)", "「私の長所は、時間を守ることです。前の工場で一度も遅刻しませんでした。」 (Watashi no chousho wa, jikan o mamoru koto desu. Mae no koujou de ichido mo chikoku shimasen deshita. “Kelebihan saya adalah tepat waktu. Di pabrik sebelumnya, saya tidak pernah sekali pun terlambat.”)"], "key": "D", "exp": "Satu kelebihan + satu bukti singkat. A adalah blok 2, B blok 5, dan C tidak meyakinkan. (B4-08)", "ok": "", "no": "", "bab": 4, "remed": ["B4-08"]}, {"ind": "4.5", "stem": "Jikoshoukai Budi: 「はじめまして。ブディです。よろしく。日本語、ちょっとできる。」 (Hajimemashite. Budi desu. Yoroshiku. Nihongo, chotto dekiru. “Salam kenal. Saya Budi. Salam kenal. Bahasa Jepang, bisa sedikit.”) Apa kesalahan utamanya?", "opts": ["Terlalu panjang sehingga menjadi 自己PR (jiko PR, promosi diri).", "Memakai bahasa santai dan blok-bloknya tidak lengkap.", "Urutan salam dan nama terbalik.", "Menyebut usia dengan bacaan yang salah."], "key": "B", "exp": "よろしく (yoroshiku) dan できる (dekiru) adalah bentuk santai, dan asal, latar belakang, kelebihan, serta motivasi tidak disebut. (B4-13)", "ok": "", "no": "", "bab": 4, "remed": ["B4-13"]}, {"ind": "5.1", "stem": "Dengarkan pertanyaan pewawancara. Pewawancara menanyakan tentang …\nTranskrip (ditampilkan setelah menjawab): 「今まで、どんなアルバイトをしたことがありますか。」 (Ima made, donna arubaito o shita koto ga arimasu ka. “Selama ini, pekerjaan paruh waktu apa yang pernah kamu lakukan?”)", "opts": ["Motivasimu bekerja di Jepang", "Tujuanmu di masa depan", "Pengalaman kerja paruh waktumu", "Kemampuan bahasa Jepangmu"], "key": "C", "exp": "Kata kunci アルバイト (arubaito, kerja paruh waktu) dan したことがありますか (shita koto ga arimasu ka, pernah melakukan). (B5-06, B5-08)", "ok": "", "no": "", "bab": 5, "remed": ["B5-06", "B5-08"]}, {"ind": "5.2", "stem": "Pewawancara bertanya 「あなたの長所を教えてください。」 (Anata no chousho o oshiete kudasai. “Ceritakan kelebihanmu.”) Jawaban mana yang paling sesuai dengan pola Jawab → Alasan → Semangat?", "opts": ["「責任感が強いことです。前の仕事で、毎日最後まで確認しました。日本でもがんばります。」 (Sekininkan ga tsuyoi koto desu. Mae no shigoto de, mainichi saigo made kakunin shimashita. Nihon demo ganbarimasu. “Rasa tanggung jawab saya tinggi. Di pekerjaan sebelumnya, setiap hari saya memeriksa sampai tuntas. Di Jepang pun saya akan berusaha.”)", "「長所はたくさんあります。」 (Chousho wa takusan arimasu. “Kelebihan saya banyak.”)", "「分かりません。」 (Wakarimasen. “Saya tidak tahu.”)", "「友達は私をいい人だと言います。それだけです。」 (Tomodachi wa watashi o ii hito da to iimasu. Sore dake desu. “Teman-teman bilang saya orang baik. Itu saja.”)"], "key": "A", "exp": "A memuat jawaban, bukti, dan semangat. B dan C tidak menjawab, D tidak menyebut kelebihan yang jelas. (B5-03, B5-05)", "ok": "", "no": "", "bab": 5, "remed": ["B5-03", "B5-05"]}, {"ind": "5.3", "stem": "Pewawancara menanyakan hal yang perlu kamu pikirkan dulu sebelum menjawab. Apa yang paling tepat kamu ucapkan?", "opts": ["「えーと、えーと……」 (Eeto, eeto… “Eh, eh…”) cukup lama tanpa kata lain.", "「その質問は難しいので、次をお願いします。」 (Sono shitsumon wa muzukashii node, tsugi o onegai shimasu. “Pertanyaan itu sulit, mohon pertanyaan berikutnya.”)", "Diam sekitar 30 detik sambil menunduk.", "「少し考えてもいいですか。」 (Sukoshi kangaete mo ii desu ka. “Bolehkah saya berpikir sebentar?”)"], "key": "D", "exp": "Meminta waktu berpikir dengan sopan lebih baik daripada diam, bergumam lama, atau menolak pertanyaan. (B5-09)", "ok": "", "no": "", "bab": 5, "remed": ["B5-09"]}, {"ind": "5.4", "stem": "Saat 逆質問 (gyaku shitsumon, bertanya balik), pertanyaan mana yang paling pantas?", "opts": ["「この会社は何の会社ですか。」 (Kono kaisha wa nan no kaisha desu ka. “Perusahaan ini bergerak di bidang apa?”)", "「面接は何点でしたか。」 (Mensetsu wa nanten deshita ka. “Berapa nilai wawancara saya?”)", "「研修はどのくらいありますか。」 (Kenshuu wa dono kurai arimasu ka. “Berapa lama pelatihan kerjanya?”)", "「いいえ、ありません。」 (Iie, arimasen. “Tidak, tidak ada.”)"], "key": "C", "exp": "Pertanyaan tentang pelatihan menunjukkan kesiapan belajar. A menunjukkan kamu belum mencari tahu tentang perusahaan, B tidak pantas ditanyakan, dan D terkesan pasif. (B5-11)", "ok": "", "no": "", "bab": 5, "remed": ["B5-11"]}, {"ind": "6.1", "stem": "Kamu sudah berterima kasih di samping kursi. Saat berjalan ke pintu, kamu teringat ingin menanyakan sesuatu. Apa yang paling tepat?", "opts": ["Kembali ke kursi dan mengajukan pertanyaan panjang.", "Tetap menutup wawancara dengan sopan, lalu menanyakannya lewat LPK.", "Bertanya sambil membuka pintu tanpa berbalik.", "Menunggu di lorong sampai pewawancara keluar, lalu bertanya."], "key": "B", "exp": "Wawancara sudah ditutup; pertanyaan tambahan disampaikan lewat LPK (renraku). A dan C mengacaukan penutupan, D mengganggu jadwal pewawancara. (B6-03, B6-07)", "ok": "", "no": "", "bab": 6, "remed": ["B6-03", "B6-07"]}, {"ind": "6.2", "stem": "Urutan yang benar saat berada di depan pintu untuk keluar adalah …", "opts": ["「さようなら」 (sayounara, “selamat tinggal”) → melambaikan tangan → keluar", "Membuka pintu → 「失礼します」 (shitsurei shimasu) → ojigi sambil keluar", "Ojigi sambil mengucapkan 「失礼します」 → keluar tanpa berbalik", "Berbalik menghadap pewawancara → 「失礼します」 → ojigi → membuka pintu"], "key": "D", "exp": "Berbalik, salam, lalu ojigi (語先後礼, gosen gorei), baru membuka pintu. B dan C urutannya salah, A tidak sopan. (B6-06)", "ok": "", "no": "", "bab": 6, "remed": ["B6-06"]}, {"ind": "6.3", "stem": "Wawancara online sudah ditutup dan perusahaan sudah memutus sambungan. Apa yang perlu kamu lakukan sebelum bersantai?", "opts": ["Memastikan kamera dan mikrofon sudah benar-benar mati.", "Mengirim pesan ke pewawancara untuk menanyakan hasilnya.", "Mengunggah tangkapan layar wawancara ke media sosial.", "Langsung bercerita keras-keras kepada keluarga."], "key": "A", "exp": "Kamera atau mikrofon yang masih menyala bisa membuat sikapmu tetap terlihat atau terdengar. B, C, dan D tidak sesuai etika setelah wawancara. (B6-08)", "ok": "", "no": "", "bab": 6, "remed": ["B6-08"]}], "sim": [{"code": "SIM-01", "sit": "Jadwal wawancara pukul 10.00. Kamu tiba di depan gedung pukul 09.35.", "opts": [["Merapikan pakaian, mematikan HP, lalu melapor ke resepsionis sekitar pukul 09.50", 10], ["Langsung masuk dan melapor pukul 09.35", 5], ["Menunggu di kafe dan baru masuk pukul 10.00 tepat", 0]], "jenis": "Etika", "acuan": "B1-09"}, {"code": "SIM-02", "sit": "Di meja resepsionis.", "opts": [["「おはようございます。〇〇と申します。十時の面接に来ました。」 (Ohayou gozaimasu. … to moushimasu. Juuji no mensetsu ni kimashita. “Selamat pagi. Nama saya …. Saya datang untuk wawancara pukul 10.”)", 10], ["「面接です。」 (Mensetsu desu. “Wawancara.”)", 5], ["「田中さん、いる？」 (Tanaka-san, iru? “Tanaka ada?”)", 0]], "jenis": "Etika", "acuan": "B1-06"}, {"code": "SIM-03", "sit": "Kamu dipanggil dan berdiri di depan pintu ruang wawancara.", "opts": [["Mengetuk tiga kali, lalu menunggu 「どうぞ」", 10], ["Mengetuk dua kali, lalu menunggu", 5], ["Langsung membuka pintu tanpa mengetuk", 0]], "jenis": "Etika", "acuan": "B3-04"}, {"code": "SIM-04", "sit": "Terdengar 「どうぞ。」 (Douzo.)", "opts": [["Masuk sambil mengucapkan 「失礼します」 (shitsurei shimasu, “permisi”), menutup pintu pelan, menghadap Tanaka-san, lalu 敬礼 (keirei) 30°", 10], ["Masuk dan menutup pintu tanpa salam, lalu ojigi", 5], ["Masuk, membiarkan pintu terbuka, dan langsung berjalan ke kursi", 0]], "jenis": "Etika", "acuan": "B3-05"}, {"code": "SIM-05", "sit": "Kamu tiba di samping kursi. Setelah perkenalan singkat, Tanaka-san berkata 「どうぞおかけください。」 (Douzo okake kudasai.)", "opts": [["Sebelumnya: 「〇〇と申します。本日はよろしくお願いいたします。」 + ojigi; lalu 「失礼します」, duduk tegak, tas di lantai", 10], ["Perkenalan singkat dengan benar, tetapi tas diletakkan di pangkuan dan bersandar", 5], ["Langsung duduk sebelum perkenalan dan meletakkan tas di meja", 0]], "jenis": "Etika", "acuan": "B3-06, B3-11"}, {"code": "SIM-06", "sit": "「では、自己紹介をお願いします。」 (Dewa, jikoshoukai o onegai shimasu.)", "opts": [["Jikoshoukai lima blok ±40 detik (versi B4-10 atau hasil B4-14 milik peserta)", 10], ["「〇〇と申します。二十三歳です。よろしくお願いいたします。」 (… to moushimasu. Nijuusansai desu. Yoroshiku onegai itashimasu. “Nama saya …. 23 tahun. Mohon kerja samanya.”), hanya dua blok", 5], ["Bercerita sekitar tiga menit tentang kelebihan diri (menjadi 自己PR)", 0]], "jenis": "Komunikasi", "acuan": "B4-04, B4-10"}, {"code": "SIM-07", "sit": "「当社を選んだ理由を教えてください。」 (Tousha o eranda riyuu o oshiete kudasai.)", "opts": [["Jawaban Rani di B5-04 (menyebut pabrik makanan dan pengalaman kerja)", 10], ["「日本で働きたいからです。」 (Nihon de hatarakitai kara desu. “Karena saya ingin bekerja di Jepang.”), tidak menyebut perusahaan", 5], ["「友達がこの会社にいるからです。それだけです。」 (Tomodachi ga kono kaisha ni iru kara desu. Sore dake desu. “Karena teman saya bekerja di sini. Itu saja.”)", 0]], "jenis": "Komunikasi", "acuan": "B5-03, B5-04"}, {"code": "SIM-08", "sit": "「日本語で困ることはありますか。」 (Nihongo de komaru koto wa arimasu ka.)", "opts": [["Jujur + usaha: 「速い話を聞くのは苦手なので、ニュースを聞いて練習しています。」 (Hayai hanashi o kiku no wa nigate na node, nyuusu o kiite renshuu shite imasu. “Saya masih sulit memahami pembicaraan cepat, jadi saya berlatih dengan mendengarkan berita.”)", 10], ["「少しあります。」 (Sukoshi arimasu. “Ada sedikit.”), tanpa penjelasan", 5], ["「ありません。全部分かります。」 (Arimasen. Zenbu wakarimasu. “Tidak ada. Saya paham semuanya.”)", 0]], "jenis": "Komunikasi", "acuan": "B5-06, B5-10"}, {"code": "SIM-09", "sit": "「機械が急に止まったら、どうしますか。」 (Kikai ga kyuu ni tomattara, dou shimasu ka.)", "opts": [["「すぐに上司に報告して、指示を聞きます。」 (Sugu ni joushi ni houkoku shite, shiji o kikimasu. “Saya segera melapor ke atasan dan meminta instruksi.”)", 10], ["「自分で直してみます。」 (Jibun de naoshite mimasu. “Saya coba perbaiki sendiri.”)", 5], ["「休憩します。」 (Kyuukei shimasu. “Saya istirahat.”)", 0]], "jenis": "Etika & budaya", "acuan": "B2-04, B2-10"}, {"code": "SIM-10", "sit": "「夜勤はできますか。」 (Yakin wa dekimasu ka.) Kamu tidak tahu arti kata 夜勤 (yakin).", "opts": [["「すみません、「夜勤」はどういう意味ですか。」 (Sumimasen, “yakin” wa dou iu imi desu ka. “Maaf, apa arti ‘yakin’?”) → Tanaka-san: 「夜の仕事のことです。」 (Yoru no shigoto no koto desu. “Maksudnya kerja malam.”)", 10], ["「はい……たぶん。」 (Hai… tabun. “Ya… mungkin.”)", 5], ["「はい、できます。」 (Hai, dekimasu. “Ya, bisa.”), tanpa tahu artinya", 0]], "jenis": "Komunikasi", "acuan": "B5-09"}, {"code": "SIM-11", "sit": "Pertanyaan tak terduga: 「ところで、休みの日は何をしていますか。」 (Tokoro de, yasumi no hi wa nani o shite imasu ka.)", "opts": [["「日本語の勉強をしたり、友達とサッカーをしたりしています。」 (Nihongo no benkyou o shitari, tomodachi to sakkaa o shitari shite imasu. “Saya belajar bahasa Jepang dan bermain sepak bola dengan teman.”)", 10], ["「寝ます。」 (Nemasu. “Tidur.”), terlalu singkat tanpa detail", 5], ["「それは仕事と関係ありません。」 (Sore wa shigoto to kankei arimasen. “Itu tidak ada hubungannya dengan pekerjaan.”)", 0]], "jenis": "Komunikasi", "acuan": "B5-08"}, {"code": "SIM-12", "sit": "「最後に、何か質問はありますか。」 (Saigo ni, nanika shitsumon wa arimasu ka.)", "opts": [["「日本に行く前に、勉強しておいたほうがいいことはありますか。」 (Nihon ni iku mae ni, benkyou shite oita hou ga ii koto wa arimasu ka. “Apakah ada yang sebaiknya saya pelajari sebelum berangkat?”)", 10], ["「いいえ、特にありません。」 (Iie, toku ni arimasen. “Tidak, tidak ada.”)", 5], ["「給料はいくらですか。休みは多いですか。」 (Kyuuryou wa ikura desu ka. Yasumi wa ooi desu ka. “Berapa gajinya? Liburnya banyak?”)", 0]], "jenis": "Komunikasi", "acuan": "B5-11"}, {"code": "SIM-13", "sit": "「以上で面接を終わります。」 (Ijou de mensetsu o owarimasu.)", "opts": [["Terima kasih sambil duduk → di samping kursi 「ありがとうございました」 + 最敬礼 (saikeirei) → di pintu berbalik, 「失礼します」 + ojigi → tutup pintu pelan", 10], ["Terima kasih sambil duduk, lalu langsung keluar tanpa salam di pintu", 5], ["「さようなら」 (sayounara), lalu keluar tanpa menutup pintu", 0]], "jenis": "Etika", "acuan": "B6-03 s.d. B6-06"}], "slides": {"GLB-00": {"code": "GLB-00", "title": "Layar Pembuka", "treat": "Layar pembuka dipandu Navi: sapaan, isi nama, kartu misi, tiga ikon penjelas, lalu Pre-test.", "pel": "Pembuka", "tpl": "T03", "screen": [{"p": "1. Logo \"Mensetsu Navi 面接ナビ (mensetsu nabi, pemandu wawancara)\". 2. Isian nama panggilan (bawaan: Rani). 3. Kartu misi: \"Kamu akan diwawancarai 田中さん (Tanaka-san) dari さくら食品 (Sakura Shokuhin, Sakura Foods). Kumpulkan enam stempel bab, lalu yakinkan Tanaka-san di Simulasi.\" 4. Tiga ikon penjelas. 5. Tombol \"Mulai Pre-test\"."}], "narasi": "Halo, aku Navi, pemandumu. Wawancara kerja di Jepang bukan hanya soal bahasa, tetapi juga sikap. Ayo mulai dengan pre-test untuk melihat kemampuan awalmu.", "visual": "Latar ilustrasi gedung kantor Tokyo pagi hari (Canva/Figma). Logo \"Mensetsu Navi 面接ナビ\" di tengah; Navi menyapa di kiri bawah. Kartu berikutnya: kolom nama; kartu misi dengan avatar Tanaka-san dan logo fiktif さくら食品; tiga ikon (stempel, Trust Meter, Romaji/Arti); tombol \"Mulai Pre-test\"."}, "PRE-00": {"code": "PRE-00", "title": "Petunjuk Pre-test", "treat": "Petunjuk singkat pre-test: 20 soal, ±15 menit, tanpa umpan balik, tidak menentukan kelulusan.", "pel": "", "tpl": "T18", "screen": [{"p": "\"Pre-test berisi 20 soal pilihan ganda, satu soal per layar, sekitar 15 menit. Jawab sesuai yang kamu ketahui sekarang; hasilnya dipakai untuk melihat kemampuan awalmu, bukan untuk menentukan lulus.\""}], "narasi": "Tenang saja, belum ada yang dinilai untuk kelulusan. Jawab sebisamu, ya.", "visual": "Kartu petunjuk di tengah dengan tiga ikon (20 soal, jam ±15 menit, tanpa nilai lulus); Navi di pojok; tombol \"Mulai Pre-test\"."}, "PRE-01 s.d. PRE-20": {"code": "PRE-01 s.d. PRE-20", "title": "Soal Pre-test", "treat": "Dua puluh soal pilihan ganda, satu soal per layar, tanpa umpan balik.", "pel": "", "tpl": "T18", "screen": [{"p": "soal nomor 1–2 Bab 1, 3–5 Bab 2, 6–9 Bab 3, 10–13 Bab 4, 14–17 Bab 5, 18–20 Bab 6. Romaji tampil; arti tampil kecuali pada soal yang menguji arti atau menyimak. Teks soal dan pilihan: dokumen Evaluasi Sumatif."}], "narasi": "tidak ada.", "visual": "Penanda soal \"1/20\" dan penghitung waktu di atas; teks situasi; empat pilihan A–D sebagai tombol lebar; soal menyimak memakai tombol putar."}, "PRE-21": {"code": "PRE-21", "title": "Hasil Awal dan Peta Kemampuan", "treat": "Skor pre-test dan Peta Kemampuan Awal per bab, lalu menu bab terbuka.", "pel": "", "tpl": "T19", "screen": [{"p": "\"Skor awalmu: [skor]\" dan Peta Kemampuan Awal per bab."}], "narasi": "Ini titik awalmu. Bab yang ditandai bisa kamu pelajari lebih dulu.", "visual": "Skor besar di atas; enam bar per bab (Bab 1–6); label \"Disarankan dipelajari lebih dulu\" pada bab terendah; Navi menyemangati; tombol \"Ke Menu\"."}, "GLB-01": {"code": "GLB-01", "title": "Beranda, Menu ☰, dan Progres", "treat": "Beranda berbentuk peta belajar sepuluh bagian dengan status, progres, dan stempel; tombol ☰ membuka menu dari slide mana pun.", "pel": "", "tpl": "", "screen": [{"p": "\"X dari 10 bagian selesai\". Panel ☰: Beranda, daftar slide bab yang sedang dibuka, Bank Kosakata, Latihan Pertanyaan Acak, Tips dan Trik, Pengaturan. Saat dibuka lagi: \"Lanjutkan dari B3-06?\"."}], "narasi": "Selamat datang di Mensetsu Navi. Mulailah dari pre-test, lalu pelajari keenam bab sampai kamu siap menghadapi simulasi wawancara.\" · Navi (GLB-07) memberi saran bagian berikutnya, misalnya \"Stempel Bab 3 belum ada. Coba bab itu dulu?", "visual": "Peta belajar memakai visual peta tahap dari B1-04: Pre-test → Bab 1–6 → Simulasi → Post-test → Rapor. Kotak terkunci abu-abu dengan gembok, kotak terbuka berwarna, kotak selesai berstempel すばらしい. Bilah progres di atas, koleksi kartu Kata Mutiara di bawah. Panel ☰ muncul dari kiri."}, "B1-01": {"code": "B1-01", "title": "Sampul Bab 1", "treat": "Sampul Bab 1: judul, durasi, tiga tujuan bab, dan daftar tiga pelajaran.", "pel": "Pembuka", "tpl": "T01", "screen": [{"li": "Bab 1 · Mengenal Mensetsu (面接, mensetsu: wawancara kerja)", "lvl": 0, "num": null}, {"li": "±8 menit · 12 slide", "lvl": 0, "num": null}, {"li": "Setelah bab ini, kamu mampu:", "lvl": 0, "num": null}, {"li": "menjelaskan ciri khas wawancara kerja di perusahaan Jepang;", "lvl": 1, "num": "1."}, {"li": "menyebutkan tiga hal yang dinilai pewawancara;", "lvl": 1, "num": "2."}, {"li": "menyiapkan diri dengan tepat sebelum hari wawancara.", "lvl": 1, "num": "3."}], "narasi": "Selamat datang di Bab 1. Sebelum berlatih perkenalan diri dan menjawab pertanyaan, kita kenali dulu seperti apa wawancara kerja di perusahaan Jepang.", "visual": "Ilustrasi gedung kantor Jepang pagi hari; Rani berpakaian rapi di depan pintu. Judul bab dan 面接 (mensetsu) di tengah, kartu tujuan dan daftar P1– P3 di bawahnya, tombol \"Mulai Bab\"."}, "B1-02": {"code": "B1-02", "title": "Siapa yang Lolos? (Pemantik)", "treat": "Pemantik: peserta memilih kandidat yang lebih mungkin lolos dari dua profil.", "pel": "P1", "tpl": "T02", "screen": [{"p": "Dua kandidat melamar posisi yang sama."}, {"table": [["", "Kandidat A", "Kandidat B"], ["Bahasa", "Sertifikat N3", "Sertifikat N4"], ["Datang", "Tepat di jam wawancara", "10 menit lebih awal"], ["Sikap", "Duduk bersandar, tanpa salam", "Memberi salam dan ojigi"], ["Saat ditanya kemampuan bahasa", "\"Saya paham semua.\"", "\"Masih ada kata yang sulit, tetapi saya belajar setiap hari.\""]]}, {"p": "Pertanyaan: **Menurutmu, siapa yang lebih mungkin lolos?**"}], "narasi": "Perhatikan dua kandidat ini. Kandidat A punya level bahasa lebih tinggi. Kandidat B datang lebih awal dan bersikap sopan. Menurutmu, siapa yang lebih mungkin lolos?", "visual": "Dua kartu kandidat berdampingan (HP: atas-bawah): Kandidat A dan B, masing-masing dengan baris Bahasa, Datang, Sikap, dan kutipan jawaban. Pertanyaan di atas kartu."}, "B1-03": {"code": "B1-03", "title": "Apa Itu Mensetsu?", "treat": "Konsep mensetsu: perbandingan wawancara umum dan perusahaan Jepang, plus prinsip hire for attitude.", "pel": "P1", "tpl": "T04", "screen": [{"p": "面接 (mensetsu) = wawancara kerja · 面接官 (mensetsukan) = pewawancara"}, {"table": [["Wawancara pada umumnya menekankan…", "Perusahaan Jepang cenderung juga memperhatikan…"], ["Kemampuan dan pengalaman", "Sikap dan kepribadian, selain kemampuan"], ["Jawaban yang terdengar meyakinkan", "Jawaban yang jujur dan tidak melebih-lebihkan"], ["Penampilan yang cukup rapi", "Detail etika: salam, ojigi, cara duduk"], ["Kemampuan bekerja sendiri", "Kerja sama tim dan kepatuhan pada aturan"], ["Kecocokan untuk saat ini", "Kesungguhan dan komitmen bekerja jangka panjang"]]}, {"p": "Keterangan kecil: Ini kecenderungan umum; praktik tiap perusahaan bisa berbeda."}, {"p": "Kotak \"Tahukah kamu?\": calon pekerja asing umumnya tidak dituntut berbahasa Jepang sempurna. Kemauan belajar dan kemampuan diajak berkomunikasi sering lebih diperhatikan. Banyak perusahaan memegang prinsip \"hire for attitude, train for skill\": terima karena sikapnya, latih keterampilannya. Kandidat N4 yang sopan dan jujur bisa lebih dipilih daripada kandidat berbahasa lebih tinggi yang sombong."}], "narasi": "Mensetsu artinya wawancara kerja. Di perusahaan Jepang, pewawancara tidak hanya melihat kemampuanmu, tetapi juga sikap, kejujuran, dan kesungguhanmu untuk bekerja dalam tim.", "visual": "Istilah 面接 dan 面接官 dengan ikon speaker di atas. Tabel dua kolom yang muncul per baris (HP: kartu geser). Kotak \"Tahukah kamu?\" kuning muda di bawah."}, "B1-04": {"code": "B1-04", "title": "Alur Mensetsu", "treat": "Peta lima tahap wawancara; Hou-Ren-Sou sebagai jalur dasar di bawahnya.", "pel": "P1", "tpl": "T03", "screen": [{"p": "Lima tahap wawancara, digambarkan sebagai peta perjalanan. Bab 2 (Hou-Ren-Sou) ditampilkan sebagai jalur dasar di bawah kelima tahap karena berlaku di seluruh wawancara."}, {"table": [["Tahap", "Arti", "Isi pop-up", "Dipelajari di"], ["1. 入室 nyuushitsu", "Masuk ruangan", "Mengetuk pintu, mengucapkan 「失礼します」 (shitsurei shimasu, \"permisi\"), dan duduk setelah dipersilakan. Kesan pertama terbentuk di sini.", "Bab 3"], ["2. 自己紹介 jikoshoukai", "Perkenalan diri", "Pewawancara biasanya membuka dengan 「自己紹介をお願いします」 (jikoshoukai o onegai shimasu, \"silakan perkenalkan diri\"). Kamu memperkenalkan diri sekitar 30–60 detik.", "Bab 4"], ["3. 質疑応答 shitsugi outou", "Tanya jawab", "Pewawancara menanyakan motivasi, kelebihan, kemampuan bahasa, dan pengalamanmu.", "Bab 5"], ["4. 逆質問 gyaku shitsumon", "Bertanya balik", "Di akhir, biasanya ditanya 「何か質問はありますか」 (nanika shitsumon wa arimasu ka, \"apakah ada pertanyaan?\"). Siapkan satu pertanyaan yang sopan.", "Bab 5"], ["5. 退室 taishitsu", "Keluar ruangan", "Mengucapkan terima kasih, ojigi, lalu keluar dengan tenang. Penilaian belum selesai sampai kamu keluar ruangan.", "Bab 6"]]}], "narasi": "Setiap wawancara mengikuti alur yang mirip: masuk ruangan, perkenalan diri, tanya jawab, bertanya balik, lalu keluar ruangan. Ketuk setiap tahap untuk melihat apa yang terjadi.", "visual": "Garis perjalanan dengan lima ikon tahap (pintu, orang bicara, tanda tanya, gelembung balik, pintu keluar) dan jalur dasar \"Bab 2 Hou-Ren-Sou\". Penghitung tahap di pojok. Visual ini dipakai ulang sebagai menu bab."}, "B1-05": {"code": "B1-05", "title": "Tiga Hal yang Dinilai", "treat": "Tiga hal yang dinilai pewawancara dalam tiga kartu balik.", "pel": "P2", "tpl": "T03", "screen": [{"p": "tiga kartu yang bisa dibalik."}, {"li": "**Komunikasi:** memahami pertanyaan sederhana dan menjawab dengan jelas walau bahasanya belum sempurna; suara jelas, tempo tenang.", "lvl": 0, "num": "1."}, {"li": "**Sikap dan etika (マナー, manaa):** salam, ojigi, postur, kerapian, dan ketepatan waktu, yang menunjukkan kamu menghormati orang lain dan aturan.", "lvl": 0, "num": "2."}, {"li": "**Kejujuran dan kemauan beradaptasi:** jujur tentang kemampuan diri, mau terus belajar, dan siap mengikuti aturan serta budaya kerja Jepang.", "lvl": 0, "num": "3."}, {"p": "Kalimat kunci: **\"Bahasa membuka pintu; sikap yang membuatmu diterima.\"**"}], "narasi": "Ada tiga hal yang diperhatikan pewawancara: caramu berkomunikasi, sikap dan etikamu, serta kejujuran dan kemauanmu beradaptasi. Ketuk setiap kartu.", "visual": "Tiga kartu tertutup berikon (gelembung bicara, orang ojigi, tangan di dada); sisi belakang berisi penjelasan. Kalimat kunci di pita bawah."}, "B1-06": {"code": "B1-06", "title": "Penilaian Dimulai Sejak Kamu Tiba", "treat": "Penilaian dimulai sejak tiba: hotspot di lobi kantor.", "pel": "P2", "tpl": "T03", "screen": [{"p": "Kesan pertama (第一印象 daiichi inshou) terbentuk sebelum wawancara dimulai. Ilustrasi lobi kantor dengan empat titik hotspot:"}, {"table": [["Titik", "Pop-up"], ["Pintu masuk gedung", "Rapikan pakaian dan matikan HP sebelum masuk."], ["Meja resepsionis", "Sapa dengan sopan, sebutkan nama dan keperluan: 「おはようございます。〇〇と申します。10時の面接に来ました。」 (Ohayou gozaimasu. … to moushimasu. Juuji no mensetsu ni kimashita. Arti: \"Selamat pagi. Nama saya …. Saya datang untuk wawancara pukul 10.00.\")"], ["Ruang tunggu", "Duduk tegak dan tenang, tidak bermain HP, tidak mengobrol keras."], ["Saat dipanggil", "Jawab 「はい」 (hai, \"ya\") dengan jelas, berdiri, lalu ikuti petugas."]]}, {"p": "Keterangan: di beberapa perusahaan, staf yang kamu temui juga bisa menyampaikan kesan mereka kepada pewawancara."}], "narasi": "Penilaian tidak dimulai saat kamu duduk di depan pewawancara, tetapi sejak kamu tiba. Ketuk setiap titik di lobi ini.", "visual": "Ilustrasi lobi kantor: pintu masuk, meja resepsionis, ruang tunggu, petugas memanggil. Empat titik hotspot berdenyut; pop-up muncul di samping titik."}, "B1-07": {"code": "B1-07", "title": "Persiapan 1: Dokumen dan Pengetahuan", "treat": "Persiapan dokumen dan pengetahuan dalam lima kartu.", "pel": "P3", "tpl": "T03", "screen": [{"p": "lima kartu persiapan."}, {"table": [["Kartu", "Isi pop-up"], ["履歴書 rirekisho", "Daftar riwayat hidup format Jepang. Bawa salinannya dan pahami isinya, karena pertanyaan pewawancara sering diambil dari sana."], ["Info perusahaan", "Ketahui nama perusahaan, bidang usaha, lokasi kerja, dan pekerjaan yang kamu lamar."], ["Jikoshoukai", "Latih sampai lancar, sekitar 1 menit. (Bab 4)"], ["Jawaban pertanyaan umum", "Siapkan jawaban motivasi, kelebihan, dan kemampuan bahasa, ditambah satu pertanyaan balik. (Bab 5)"], ["Jadwal dan kontak", "Catat jam, alamat atau tautan wawancara online, dan nomor kontak perusahaan untuk mengabari jika ada kendala. (Bab 2)"]]}], "narasi": "Persiapan dimulai dari rumah. Pahami isi rirekisho-mu, kenali perusahaannya, latih perkenalan diri, dan catat kontak perusahaan.", "visual": "Lima kartu berikon (dokumen rirekisho, gedung, mikrofon, daftar tanya, kalender); tanda centang muncul di kartu yang sudah dibuka."}, "B1-08": {"code": "B1-08", "title": "Persiapan 2: Penampilan (身だしなみ)", "treat": "Penampilan (身だしなみ) lewat hotspot pada figur kandidat.", "pel": "P3", "tpl": "T03", "screen": [{"p": "身だしなみ (midashinami) = kerapian penampilan. Figur kandidat dengan enam titik hotspot dan tombol ganti figur (pria / wanita / wanita berhijab)."}, {"table": [["Titik", "Pop-up"], ["Rambut", "Rapi, bersih, tidak menutupi wajah, warna natural. Bagi yang berhijab: rapi, polos, warna netral."], ["Pakaian", "Setelan jas gelap (hitam, biru tua, atau abu tua) dengan kemeja putih, atau seragam yang ditentukan LPK. Bersih dan tidak kusut."], ["Wajah dan kuku", "Kuku pendek dan bersih. Pria bercukur rapi; riasan wanita natural."], ["Aksesori dan parfum", "Seminimal mungkin; parfum tidak menyengat."], ["Sepatu", "Sepatu pantofel gelap yang bersih."], ["Tas", "Sederhana; saat duduk diletakkan di lantai samping kursi. (Bab 3)"]]}], "narasi": "Penampilan rapi menunjukkan kamu menghargai wawancara ini. Ketuk setiap bagian untuk melihat ketentuannya.", "visual": "Figur kandidat setinggi badan dengan enam titik hotspot (rambut, pakaian, wajah, aksesori, sepatu, tas); tombol ganti figur pria, wanita, wanita berhijab di atas."}, "B1-09": {"code": "B1-09", "title": "Persiapan 3: Waktu, HP, Wawancara Online, dan Mental", "treat": "Waktu, HP, wawancara online, dan mengatasi gugup dalam empat tab.", "pel": "P3", "tpl": "T03", "screen": [{"p": "empat tab."}, {"li": "**Waktu:** tiba di lokasi sekitar 10 menit sebelum jadwal. Datang terlalu awal bisa merepotkan perusahaan; terlambat memberi kesan buruk. Jika akan terlambat, hubungi perusahaan **sebelum** jam wawancara (renraku, mengabari; dibahas di Bab 2).", "lvl": 0, "num": null}, {"li": "**HP:** matikan atau mode senyap sebelum masuk gedung, dan jangan dikeluarkan selama menunggu maupun wawancara.", "lvl": 0, "num": null}, {"li": "**Wawancara online:**", "lvl": 0, "num": null}, {"li": "cek koneksi dan perangkat 15 menit sebelumnya;", "lvl": 1, "num": null}, {"li": "masuk ruang virtual sekitar 5 menit sebelum jadwal;", "lvl": 1, "num": null}, {"li": "latar polos dan rapi, cahaya dari depan, kamera sejajar mata;", "lvl": 1, "num": null}, {"li": "berpakaian lengkap seperti wawancara tatap muka;", "lvl": 1, "num": null}, {"li": "pilih tempat yang tenang dan matikan notifikasi.", "lvl": 1, "num": null}, {"li": "**Mental (mengatasi gugup):**", "lvl": 0, "num": null}, {"li": "gugup itu wajar, dan pewawancara memaklumi sedikit rasa gugup;", "lvl": 1, "num": null}, {"li": "latih jikoshoukai dan jawaban sampai lancar (Bab 4 dan 5), karena latihan berulang adalah cara terbaik mengurangi gugup;", "lvl": 1, "num": null}, {"li": "sebelum masuk ruangan, tarik napas pelan beberapa kali dan tegakkan badan;", "lvl": 1, "num": null}, {"li": "jika tiba-tiba lupa, ucapkan 「少し考えてもいいですか。」 (Sukoshi kangaete mo ii desu ka. \"Bolehkah saya berpikir sebentar?\"), dipelajari di Bab 5;", "lvl": 1, "num": null}, {"li": "fokus menyampaikan maksud dengan jelas, bukan berbicara dengan tata bahasa yang sempurna.", "lvl": 1, "num": null}], "narasi": "Waktu adalah bagian dari etika. Datanglah sekitar sepuluh menit lebih awal, matikan HP, dan kalau wawancaranya online, siapkan perangkat dan tempatmu sebelum jadwal. Kalau gugup, itu wajar. Latihan berulang dan napas yang tenang akan membantumu.", "visual": "Empat tab berikon (jam, HP, laptop, hati). Panel isi berupa daftar poin pendek; tab Mental memakai ilustrasi Rani menarik napas."}, "B1-10": {"code": "B1-10", "title": "Aktivitas: Siap atau Belum Siap?", "treat": "Latihan mengelompokkan persiapan ke kolom Siap atau Belum siap.", "pel": "P3", "tpl": "T10", "screen": [{"p": "\"Jadwal wawancaramu pukul 10.00. Pindahkan setiap kartu ke kolom yang tepat.\" Dua kolom: **Siap** dan **Belum siap**."}, {"table": [["Kartu", "Jawaban", "Umpan balik jika salah"], ["Membawa salinan rirekisho dan sudah membaca isinya", "Siap", "Pewawancara sering bertanya dari isi rirekisho-mu."], ["Tiba di lokasi pukul 09.50", "Siap", "Sekitar 10 menit lebih awal adalah waktu yang dianjurkan."], ["Mematikan HP sebelum masuk gedung", "Siap", "HP yang berbunyi mengganggu dan terkesan tidak menghormati."], ["Sudah mencari tahu bidang usaha perusahaan", "Siap", "Ini menunjukkan kesungguhanmu melamar."], ["Memakai kaus dan sandal karena wawancara pagi", "Belum siap", "Kenakan pakaian rapi, apa pun jam wawancaranya."], ["Tiba tepat pukul 10.00 karena \"yang penting tidak terlambat\"", "Belum siap", "Tepat waktu belum cukup; kamu butuh waktu melapor ke resepsionis dan menenangkan diri."], ["Bermain HP di ruang tunggu sambil bersandar", "Belum siap", "Sikapmu sudah diperhatikan sejak di ruang tunggu."], ["Baru menghafal jikoshoukai di ruang tunggu", "Belum siap", "Latih jikoshoukai jauh hari agar lancar dan tenang."]]}], "narasi": "Sekarang giliranmu. Mana persiapan yang sudah tepat, dan mana yang belum?", "visual": "Instruksi \"Jadwal pukul 10.00\" di atas; tumpukan delapan kartu situasi; dua kolom hijau (Siap) dan abu (Belum siap)."}, "B1-11": {"code": "B1-11", "title": "Rangkuman Bab 1", "treat": "Rangkuman empat poin Bab 1, glosarium, dan kartu Kata Mutiara.", "pel": "Penutup", "tpl": "T17", "screen": [{"li": "Mensetsu di perusahaan Jepang menilai bahasa sekaligus sikap, etika, dan kejujuran.", "lvl": 0, "num": "1."}, {"li": "Alurnya: 入室 (nyuushitsu, masuk ruangan) → 自己紹介 (jikoshoukai, perkenalan diri) → 質疑応答 (shitsugi outou, tanya jawab) → 逆質問 (gyaku shitsumon, bertanya balik) → 退室 (taishitsu, keluar ruangan).", "lvl": 0, "num": "2."}, {"li": "Penilaian dimulai sejak kamu tiba (第一印象, daiichi inshou: kesan pertama).", "lvl": 0, "num": "3."}, {"li": "Persiapkan dokumen dan pengetahuan, penampilan, serta waktu dan HP.", "lvl": 0, "num": "4."}, {"p": "Kata Mutiara: **\"Bahasa membuka pintu; sikap yang membuatmu diterima.\"**"}], "narasi": "Kamu sudah mengenal mensetsu. Ingat, bahasa membuka pintu, sikap yang membuatmu diterima. Sekarang, uji pemahamanmu.", "visual": "Empat poin bernomor muncul bertahap; kartu Kata Mutiara bergambar Navi; tombol \"Glosarium Bab 1\" dan \"Mulai Kuis\"."}, "B1-12": {"code": "B1-12", "title": "Kuis Formatif Bab 1", "treat": "Kuis formatif 5 soal acak dari bank 10, lalu layar hasil dan remedial.", "pel": "Penutup", "tpl": "T18", "screen": [{"p": "bank 10 soal; tampil 5 soal acak (2 dari indikator 1.1, 1 dari 1.2, 2 dari 1.3), satu soal per layar, dengan umpan balik langsung; lulus bila skor ≥ 80 (4 dari 5 benar). Layar hasil (T19): skor ≥ 80 → \"Kamu lulus Bab 1!\" + animasi stempel. Skor < 80 → \"Hampir! Ulangi bagian berikut, lalu coba lagi.\" + daftar slide remedial sesuai soal yang salah."}], "narasi": "tidak ada; Navi bereaksi senang atau menyemangati di layar hasil (GLB-07). Soal, pilihan, kunci, dan umpan balik tiap soal: naskah Bab 1.", "visual": "Satu soal per layar: teks soal, empat pilihan A–D, penanda soal 1/5. Layar hasil: skor besar, stempel Bab 1 atau daftar slide remedial."}, "B2-01": {"code": "B2-01", "title": "Sampul Bab 2", "treat": "Sampul Bab 2: judul, durasi, tujuan, dan daftar pelajaran.", "pel": "Pembuka", "tpl": "T01", "screen": [{"li": "Bab 2 · Hou-Ren-Sou (報連相, hourensou: melapor, mengabari, berkonsultasi)", "lvl": 0, "num": null}, {"li": "±12 menit · 13 slide", "lvl": 0, "num": null}, {"li": "Setelah bab ini, kamu mampu:", "lvl": 0, "num": null}, {"li": "menjelaskan arti houkoku, renraku, dan soudan;", "lvl": 1, "num": "1."}, {"li": "membedakan ketiganya dalam situasi kerja;", "lvl": 1, "num": "2."}, {"li": "memilih tindakan dan jawaban yang sesuai Hou-Ren-Sou saat wawancara.", "lvl": 1, "num": "3."}], "narasi": "Di Bab 2, kamu akan mengenal Hou-Ren-Sou, cara berkomunikasi yang sangat dihargai di tempat kerja Jepang, dan sering muncul dalam pertanyaan wawancara.", "visual": "Ilustrasi daun bayam bertuliskan 報 (hou), 連 (ren), 相 (sou); judul bab, kartu tujuan, daftar P1–P3, tombol \"Mulai Bab\"."}, "B2-02": {"code": "B2-02", "title": "Apa Hubungan Bayam dengan Dunia Kerja? (Pemantik)", "treat": "Pemantik: arti pesan \"Jangan lupa hourensou!\" di kantor Jepang.", "pel": "P1", "tpl": "T02", "screen": [{"p": "gambar bayam dengan tulisan ほうれん草 (hourensou) = bayam. Pertanyaan: \"Di kantor Jepang, atasan sering berpesan ‘Jangan lupa hourensou!’. Apa maksudnya?\""}, {"li": "Pilihan 1: \"Makan bayam supaya kuat bekerja.\"", "lvl": 0, "num": null}, {"li": "Pilihan 2: \"Ini singkatan, bukan bayam sungguhan.\"", "lvl": 0, "num": null}, {"p": "Setelah memilih, Show: tiga huruf muncul satu per satu: **報**告 (houkoku, melapor) + **連**絡 (renraku, mengabari) + **相**談 (soudan, berkonsultasi) = 報連相 (hourensou), bunyinya sama dengan bayam."}, {"p": "Kotak \"Tahukah kamu?\": istilah ini pertama kali dicetuskan Yamazaki Tomio, presiden perusahaan sekuritas Yamatane. Agar karyawan terbiasa, ia menjadikan tanggal 1 setiap bulan sebagai \"hari Hou-Ren-Sou\" dan membagikan bayam sungguhan kepada karyawan."}], "narasi": "Hourensou artinya bayam. Tapi di kantor Jepang, kata ini punya arti lain. Ia singkatan dari tiga kebiasaan komunikasi kerja: houkoku, renraku, dan soudan.", "visual": "Gambar bayam ほうれん草 dan atasan memberi pesan; dua kartu pilihan. Setelah memilih, tiga huruf 報・連・相 terbentuk dari daun bayam."}, "B2-03": {"code": "B2-03", "title": "Apa Itu Hou-Ren-Sou?", "treat": "Definisi Hou-Ren-Sou dan alasan pentingnya dalam empat kartu.", "pel": "P1", "tpl": "T03", "screen": [{"p": "Hou-Ren-Sou = kebiasaan berbagi informasi di tempat kerja agar tim bekerja lancar. Empat kartu \"Mengapa penting?\":"}, {"li": "**Kerja tim:** pekerjaan di perusahaan Jepang dikerjakan bersama, jadi semua orang perlu tahu kondisi terbaru.", "lvl": 0, "num": "1."}, {"li": "**Atasan bertanggung jawab:** atasan perlu informasi yang benar untuk mengambil keputusan.", "lvl": 0, "num": "2."}, {"li": "**Masalah tetap kecil:** masalah yang cepat disampaikan lebih mudah diatasi sebelum membesar.", "lvl": 0, "num": "3."}, {"li": "**Bagi pekerja asing:** bertanya dan melapor lebih aman daripada menebak, apalagi saat bahasa belum lancar.", "lvl": 0, "num": "4."}, {"p": "Kalimat kunci: **\"Di tempat kerja Jepang, diam saat ada masalah dianggap lebih buruk daripada mengaku salah.\"**"}], "narasi": "Hou-Ren-Sou adalah kebiasaan berbagi informasi agar tim bekerja lancar. Pewawancara ingin tahu: kalau ada masalah, apakah kamu akan bicara, atau diam?", "visual": "Definisi di pita atas; empat kartu \"Mengapa penting?\" berikon (tim, atasan, masalah kecil, pekerja asing)."}, "B2-04": {"code": "B2-04", "title": "報告 Houkoku: Melapor", "treat": "報告 houkoku: kapan melapor, ungkapan, dan prinsip.", "pel": "P1", "tpl": "T05", "screen": [{"p": "報告 (houkoku) = melaporkan hasil atau perkembangan pekerjaan kepada atasan yang memberi tugas."}, {"li": "**Kapan:** setelah tugas selesai, di tengah pengerjaan (perkembangan), dan **segera** saat ada masalah atau kesalahan.", "lvl": 0, "num": null}, {"li": "**Prinsip:**", "lvl": 0, "num": null}, {"li": "sampaikan kesimpulan dulu, baru rinciannya (結論から ketsuron kara);", "lvl": 1, "num": null}, {"li": "kabar buruk disampaikan lebih cepat, bukan ditunda;", "lvl": 1, "num": null}, {"li": "melapor atas inisiatif sendiri, tidak menunggu ditanya.", "lvl": 1, "num": null}, {"table": [["Contoh ungkapan", "Cara baca", "Arti"], ["〇〇さん、今よろしいですか。ご報告があります。", "…san, ima yoroshii desu ka. Go-houkoku ga arimasu.", "Pak/Bu …, apakah sekarang ada waktu? Ada yang ingin saya laporkan."], ["〇〇の作業が終わりました。", "… no sagyou ga owarimashita.", "Pekerjaan … sudah selesai."], ["申し訳ありません。ミスをしてしまいました。", "Moushiwake arimasen. Misu o shite shimaimashita.", "Mohon maaf, saya telah membuat kesalahan."]]}], "narasi": "Houkoku artinya melapor. Laporkan hasil dan perkembangan pekerjaanmu kepada atasan. Kalau ada kesalahan, laporkan secepatnya, jangan disembunyikan.", "visual": "Ikon 報 besar di kiri; daftar \"Kapan\"; kartu ungkapan Jepang-romaji-arti dengan ikon speaker; tombol \"Prinsip\" membuka tiga prinsip bertahap."}, "B2-05": {"code": "B2-05", "title": "連絡 Renraku: Mengabari", "treat": "連絡 renraku: contoh situasi, ungkapan, dan prinsip.", "pel": "P1", "tpl": "T05", "screen": [{"p": "連絡 (renraku) = menyampaikan informasi atau fakta kepada semua pihak yang perlu tahu."}, {"li": "**Contoh situasi:** akan terlambat, sakit dan tidak bisa masuk, ada perubahan jadwal.", "lvl": 0, "num": null}, {"li": "**Prinsip:**", "lvl": 0, "num": null}, {"li": "cepat, sebelum kejadian, bukan sesudahnya;", "lvl": 1, "num": null}, {"li": "sampaikan fakta dengan jelas, bukan tebakan;", "lvl": 1, "num": null}, {"li": "kabari semua pihak yang terkait.", "lvl": 1, "num": null}, {"table": [["Contoh ungkapan", "Cara baca", "Arti"], ["すみません。電車が遅れていて、10分ほど遅れます。", "Sumimasen. Densha ga okurete ite, juppun hodo okuremasu.", "Maaf, kereta terlambat, saya akan terlambat sekitar 10 menit."], ["すみません。熱があるので、今日は休ませてください。", "Sumimasen. Netsu ga aru node, kyou wa yasumasete kudasai.", "Maaf, saya demam, izinkan saya tidak masuk hari ini."]]}], "narasi": "Renraku artinya mengabari. Begitu ada informasi yang perlu diketahui orang lain, sampaikan secepatnya, sebelum terjadi.", "visual": "Ikon 連 besar; contoh situasi (terlambat, sakit, perubahan jadwal); kartu ungkapan beraudio; tombol \"Prinsip\"."}, "B2-06": {"code": "B2-06", "title": "相談 Soudan: Berkonsultasi", "treat": "相談 soudan: kapan berkonsultasi, ungkapan, dan prinsip.", "pel": "P1", "tpl": "T05", "screen": [{"p": "相談 (soudan) = meminta pendapat atau saran atasan atau senior (先輩 senpai) **sebelum** mengambil keputusan."}, {"li": "**Kapan:** saat ragu, tidak tahu caranya, atau harus memilih di antara dua hal.", "lvl": 0, "num": null}, {"li": "**Prinsip:**", "lvl": 0, "num": null}, {"li": "jangan memutuskan sendiri hal yang belum kamu pahami;", "lvl": 1, "num": null}, {"li": "siapkan dulu apa yang ingin kamu tanyakan;", "lvl": 1, "num": null}, {"li": "tanyakan apakah lawan bicara punya waktu.", "lvl": 1, "num": null}, {"table": [["Contoh ungkapan", "Cara baca", "Arti"], ["すみません、ご相談したいことがあるんですが、今よろしいですか。", "Sumimasen, go-soudan shitai koto ga arun desu ga, ima yoroshii desu ka.", "Permisi, ada yang ingin saya konsultasikan, apakah sekarang ada waktu?"], ["この作業のやり方が分からないので、教えていただけますか。", "Kono sagyou no yarikata ga wakaranai node, oshiete itadakemasu ka.", "Saya belum paham cara mengerjakan ini, bolehkah saya diajari?"]]}], "narasi": "Soudan artinya berkonsultasi. Saat ragu, jangan menebak. Tanyakan dulu kepada atasan atau senior sebelum memutuskan.", "visual": "Ikon 相 besar; ilustrasi Rani bertanya kepada senpai; kartu ungkapan beraudio; tombol \"Prinsip\"."}, "B2-07": {"code": "B2-07", "title": "Bedanya Apa?", "treat": "Tabel perbandingan houkoku, renraku, soudan yang muncul per kolom.", "pel": "P2", "tpl": "T04", "screen": [{"p": "tabel perbandingan yang muncul per kolom."}, {"table": [["", "報告 Houkoku", "連絡 Renraku", "相談 Soudan"], ["Kepada siapa", "Atasan yang memberi tugas", "Semua pihak terkait (atasan, rekan, perusahaan)", "Atasan atau senior"], ["Kapan", "Setelah atau selama tugas, segera bila ada masalah", "Begitu ada informasi yang perlu diketahui", "Sebelum memutuskan, saat ragu"], ["Isinya", "Hasil dan perkembangan pekerjaan", "Fakta: jadwal, keterlambatan, izin", "Pertanyaan dan permintaan saran"], ["Arah", "Kamu → atasan", "Kamu → banyak pihak", "Dua arah (kamu bertanya, atasan memberi saran)"]]}, {"p": "Cara mudah mengingat: **Houkoku = hasil kerja · Renraku = kabar · Soudan = minta saran.**"}], "narasi": "Ingat cara mudahnya: houkoku untuk hasil kerja, renraku untuk kabar, dan soudan untuk minta saran.", "visual": "Tabel empat baris (Kepada siapa, Kapan, Isinya, Arah) dan tiga kolom berwarna; kolom muncul satu per satu. Jembatan keledai di bawah."}, "B2-08": {"code": "B2-08", "title": "Aktivitas: Hou, Ren, atau Sou?", "treat": "Latihan mengelompokkan sembilan situasi kerja ke 報, 連, atau 相.", "pel": "P2", "tpl": "T10", "screen": [{"p": "\"Kamu sudah bekerja di sebuah pabrik di Jepang. Pindahkan setiap situasi ke kotak yang tepat.\" Tiga kotak: 報告 (houkoku, melapor), 連絡 (renraku, mengabari), 相談 (soudan, berkonsultasi)."}, {"table": [["Situasi", "Jawaban", "Umpan balik jika salah"], ["Kamu selesai memeriksa 200 produk dan menyampaikan hasilnya ke atasan.", "報告", "Ini hasil pekerjaan yang ditugaskan, jadi termasuk melapor."], ["Kamu tidak sengaja merusak alat kerja dan segera memberi tahu atasan.", "報告", "Kesalahan dalam pekerjaan dilaporkan ke atasan secepatnya."], ["Pekerjaanmu baru selesai separuh, dan kamu menyampaikan perkembangannya sebelum tenggat.", "報告", "Perkembangan pekerjaan juga dilaporkan, bukan hanya hasil akhir."], ["Kamu demam dan mengabari kantor bahwa tidak bisa masuk hari ini.", "連絡", "Ini kabar yang perlu diketahui orang lain, bukan laporan hasil kerja."], ["Kereta terlambat, dan kamu mengabari bahwa kamu akan telat 10 menit.", "連絡", "Ini informasi fakta yang disampaikan sebelum kejadian."], ["Rapat dipindah ke pukul 15.00, dan kamu memberi tahu rekan satu tim.", "連絡", "Kamu meneruskan informasi kepada pihak yang terkait."], ["Kamu belum yakin cara memakai mesin baru, lalu bertanya ke senior sebelum mulai.", "相談", "Kamu meminta saran sebelum bertindak."], ["Ada dua tugas mendesak, dan kamu meminta pendapat atasan mana yang didahulukan.", "相談", "Kamu belum bisa memutuskan sendiri, jadi meminta saran."], ["Kamu punya ide cara kerja baru dan meminta pendapat atasan sebelum mencobanya.", "相談", "Ide baru dibicarakan dulu sebelum dijalankan."]]}], "narasi": "Sekarang coba kelompokkan. Mana yang melapor, mana yang mengabari, dan mana yang meminta saran?", "visual": "Instruksi situasi pabrik di atas; tumpukan kartu situasi; tiga kotak tujuan berwarna sesuai kolom B2-07."}, "B2-09": {"code": "B2-09", "title": "Hou-Ren-Sou Sebelum Wawancara", "treat": "Hou-Ren-Sou sebelum wawancara: contoh telepon renraku.", "pel": "P3", "tpl": "T05", "screen": [{"p": "Hou-Ren-Sou sudah dinilai bahkan sebelum kamu masuk ruangan. Ketiga situasi berikut termasuk 連絡 (renraku, mengabari)."}, {"li": "**Akan terlambat** → 連絡: telepon perusahaan **sebelum** jadwal. Sampaikan nama, jadwal wawancara, alasan singkat, perkiraan tiba, dan permintaan maaf.", "lvl": 0, "num": null}, {"li": "**Berhalangan hadir** → 連絡: kabari secepatnya dan tanyakan apakah jadwal bisa diatur ulang.", "lvl": 0, "num": null}, {"li": "**Wawancara online bermasalah** (koneksi putus) → 連絡: hubungi kontak perusahaan lewat telepon atau pesan, lalu masuk kembali.", "lvl": 0, "num": null}, {"p": "Contoh telepon (audio, dengan teks dan arti):"}, {"p": "「お忙しいところ申し訳ありません。本日10時から面接の〇〇と申します。電車が遅れていて、10時15分ごろに着きます。申し訳ありません。」"}, {"p": "Osogashii tokoro moushiwake arimasen. Honjitsu juuji kara mensetsu no … to moushimasu. Densha ga okurete ite, juuji juugofun goro ni tsukimasu. Moushiwake arimasen."}, {"p": "Arti: \"Mohon maaf mengganggu di tengah kesibukan. Saya …, yang dijadwalkan wawancara hari ini pukul 10.00. Kereta terlambat, saya akan tiba sekitar pukul 10.15. Mohon maaf.\""}], "narasi": "Hou-Ren-Sou dimulai sebelum wawancara. Kalau akan terlambat atau berhalangan, kabari perusahaan sebelum jadwal. Cara kamu mengabari sudah menjadi bagian dari penilaian.", "visual": "Tiga kartu situasi (terlambat, berhalangan, ganti jadwal) dengan ilustrasi telepon; contoh dialog telepon dan tombol \"Tampilkan arti\"."}, "B2-10": {"code": "B2-10", "title": "Pertanyaan Situasional di Wawancara", "treat": "Tiga pertanyaan situasional pewawancara dan pola jawabannya.", "pel": "P3", "tpl": "T06", "screen": [{"p": "Pewawancara sering bertanya \"Apa yang akan kamu lakukan jika…?\" untuk melihat apakah kamu memahami Hou-Ren-Sou. Tiga kartu pertanyaan:"}, {"table": [["Pertanyaan pewawancara", "Contoh jawaban", "Prinsip"], ["仕事でミスをしたら、どうしますか。 (Shigoto de misu o shitara, dou shimasu ka. Jika kamu membuat kesalahan dalam pekerjaan, apa yang kamu lakukan?)", "すぐに上司に報告して、謝ります。そして、同じミスをしないように気をつけます。 (Sugu ni joushi ni houkoku shite, ayamarimasu. Soshite, onaji misu o shinai you ni ki o tsukemasu. Saya segera melapor ke atasan dan meminta maaf, lalu berhati-hati agar tidak mengulanginya.)", "報告"], ["仕事のやり方が分からないとき、どうしますか。 (Shigoto no yarikata ga wakaranai toki, dou shimasu ka. Jika tidak tahu cara mengerjakan sesuatu, apa yang kamu lakukan?)", "自分で決めないで、先輩や上司に相談します。 (Jibun de kimenaide, senpai ya joushi ni soudan shimasu. Saya tidak memutuskan sendiri, tetapi berkonsultasi dengan senior atau atasan.)", "相談"], ["遅刻しそうなとき、どうしますか。 (Chikoku shisou na toki, dou shimasu ka. Jika kamu akan terlambat, apa yang kamu lakukan?)", "仕事が始まる前に、すぐ会社に連絡します。 (Shigoto ga hajimaru mae ni, sugu kaisha ni renraku shimasu. Saya segera mengabari perusahaan sebelum jam kerja dimulai.)", "連絡"]]}, {"p": "Pola jawaban: **tindakan Hou-Ren-Sou + komitmen** (misalnya \"berhati-hati agar tidak mengulanginya\")."}], "narasi": "Dengarkan setiap pertanyaan, pikirkan jawabanmu, lalu buka contoh jawabannya. Perhatikan: jawaban yang baik menyebutkan tindakan Hou-Ren-Sou dan komitmenmu.", "visual": "Tiga kartu pertanyaan dengan tombol putar dan ikon mata (sembunyikan teks); contoh jawaban muncul di bawah; pola jawaban di pita bawah."}, "B2-11": {"code": "B2-11", "title": "Komik Kasus: Apa yang Kamu Lakukan?", "treat": "Komik bercabang empat kasus dengan indikator Kepercayaan.", "pel": "P3", "tpl": "T13", "screen": [{"p": "komik bercabang berisi empat kasus pendek (dua di tempat kerja, dua di hari wawancara), masing-masing tiga panel dan tiga pilihan. Di pojok layar ada indikator kecil \"Kepercayaan\" (信頼, shinrai) yang naik atau turun sesuai pilihan, sebagai latihan sebelum Trust Meter di Simulasi."}, {"p": "**Kasus 1 (di tempat kerja):** \"Hari ketiga bekerja di pabrik, kamu sadar salah menempel label pada 20 produk. Belum ada yang tahu.\""}, {"table": [["Pilihan", "Hasil", "Umpan balik"], ["Segera melapor ke atasan, menjelaskan yang terjadi, dan meminta maaf.", "Tepat", "\"Tepat! Atasan bisa segera memeriksa produk lain yang mungkin sudah terkirim. Ini houkoku.\""], ["Diam-diam memperbaiki 20 label itu sendiri tanpa memberi tahu siapa pun.", "Kurang tepat", "\"Niatmu baik, tetapi atasan tetap perlu tahu. Bisa jadi ada produk lain yang ikut salah.\""], ["Menunggu sampai atasan menemukannya sendiri.", "Salah", "\"Menyembunyikan kesalahan merusak kepercayaan. Laporkan secepatnya.\""]]}, {"p": "**Kasus 2 (saat wawancara):** pewawancara bertanya 「分からないことがあったら、どうしますか。」 (Wakaranai koto ga attara, dou shimasu ka. Jika ada yang tidak kamu pahami, apa yang kamu lakukan?)"}, {"table": [["Pilihan", "Hasil", "Umpan balik"], ["「先輩や上司に相談します。」 (Senpai ya joushi ni soudan shimasu. Saya berkonsultasi dengan senior atau atasan.)", "Tepat", "\"Tepat! Kamu menunjukkan bahwa kamu akan soudan, bukan menebak.\""], ["「自分で調べて、全部一人でやります。」 (Jibun de shirabete, zenbu hitori de yarimasu. Saya cari tahu sendiri dan mengerjakan semuanya sendirian.)", "Kurang tepat", "\"Inisiatifmu bagus, tetapi untuk hal yang belum dipahami, sebaiknya tanyakan dulu agar tidak salah.\""], ["「分からないことはありません。」 (Wakaranai koto wa arimasen. Tidak ada yang tidak saya pahami.)", "Salah", "\"Jawaban ini terdengar tidak jujur dan menutup diri dari belajar.\""]]}, {"p": "Kasus 3 (hari wawancara): \"Kamu berangkat ke wawancara pukul 10.00. Pukul 09.30 kereta berhenti karena gangguan, dan kamu akan terlambat sekitar 15 menit.\""}, {"table": [["Pilihan", "Hasil", "Umpan balik"], ["Segera menelepon perusahaan sebelum pukul 10.00: menyebut nama, jadwal wawancara, alasan, perkiraan tiba, dan meminta maaf (contoh telepon B2-09).", "Tepat", "\"Tepat! Kabar sebelum terlambat menunjukkan tanggung jawab. Ini renraku.\""], ["Tidak menelepon, tetapi bergegas datang lalu meminta maaf saat tiba.", "Kurang tepat", "\"Meminta maaf itu baik, tetapi perusahaan perlu tahu sebelum jadwal, bukan sesudahnya.\""], ["Tidak mengabari dan berharap pewawancara juga belum siap.", "Salah", "\"Terlambat tanpa kabar langsung mengurangi kepercayaan. Kabari sebelum kejadian.\""]]}, {"p": "Kasus 4 (saat wawancara): pewawancara memakai kata yang tidak kamu pahami."}, {"table": [["Pilihan", "Hasil", "Umpan balik"], ["「すみません、もう一度お願いします。」 (Sumimasen, mou ichido onegai shimasu. \"Maaf, mohon diulangi sekali lagi.\")", "Tepat", "\"Tepat! Bertanya saat tidak paham lebih baik daripada menebak. Ungkapan lainnya dipelajari di B5-09.\""], ["Diam sejenak, lalu menjawab sesuai tebakanmu.", "Kurang tepat", "\"Kamu berusaha menjawab, tetapi jawaban yang salah arah bisa membuat pewawancara bingung.\""], ["「はい、分かりました。」 (Hai, wakarimashita. \"Ya, saya mengerti.\") padahal tidak paham.", "Salah", "\"Berpura-pura paham dianggap tidak jujur, dan di tempat kerja bisa menimbulkan kesalahan.\""]]}, {"p": "Panel penutup: indikator Kepercayaan akhir dan pesan \"Di Jepang, kepercayaan dibangun dari kebiasaan kecil: melapor, mengabari, dan bertanya.\""}], "narasi": "Saatnya menerapkan Hou-Ren-Sou. Ikuti ceritanya, lalu pilih tindakan yang paling tepat. Perhatikan bagaimana pilihanmu memengaruhi kepercayaan orang lain.", "visual": "Komik tiga panel per kasus; tiga tombol pilihan di bawah panel; indikator Kepercayaan (信頼) kecil di pojok kanan atas; ekspresi atasan/pewawancara berubah sesuai pilihan."}, "B2-12": {"code": "B2-12", "title": "Rangkuman Bab 2", "treat": "Rangkuman Bab 2, glosarium, dan kartu Kata Mutiara.", "pel": "Penutup", "tpl": "T17", "screen": [{"li": "報連相 (hourensou) = 報告 (houkoku, melapor hasil kerja) + 連絡 (renraku, mengabari) + 相談 (soudan, meminta saran).", "lvl": 0, "num": "1."}, {"li": "Kesalahan dilaporkan secepatnya; kabar disampaikan sebelum kejadian; saat ragu, tanyakan sebelum memutuskan.", "lvl": 0, "num": "2."}, {"li": "Sebelum wawancara: kabari perusahaan jika akan terlambat atau berhalangan.", "lvl": 0, "num": "3."}, {"li": "Saat wawancara: jawab pertanyaan situasional dengan tindakan Hou-Ren-Sou + komitmen.", "lvl": 0, "num": "4."}, {"p": "Kata Mutiara: **\"Masalah kecil yang cepat dilaporkan tidak akan menjadi masalah besar.\"**"}], "narasi": "Kamu sudah mengenal Hou- Ren-Sou. Di tempat kerja Jepang, berbicara saat ada masalah adalah tanda tanggung jawab. Sekarang, uji pemahamanmu.", "visual": "Poin rangkuman bertahap; kartu Kata Mutiara bergambar Navi; tombol \"Glosarium Bab 2\" dan \"Mulai Kuis\"."}, "B2-13": {"code": "B2-13", "title": "Kuis Formatif Bab 2", "treat": "Kuis formatif 5 soal acak dari bank 10, lalu layar hasil dan remedial.", "pel": "Penutup", "tpl": "T18", "screen": [{"p": "bank 10 soal; tampil 5 soal acak, satu soal per layar, dengan umpan balik langsung; lulus bila skor ≥ 80 (4 dari 5 benar). Layar hasil (T19): skor ≥ 80 → \"Kamu lulus Bab 2!\" + animasi stempel. Skor < 80 → \"Hampir! Ulangi bagian berikut, lalu coba lagi.\" + daftar slide remedial sesuai soal yang salah."}], "narasi": "tidak ada; Navi bereaksi senang atau menyemangati di layar hasil (GLB-07). Soal, kunci, dan umpan balik: naskah Bab 2.", "visual": "Satu soal per layar dengan empat pilihan; layar hasil berisi skor, stempel Bab 2 atau daftar slide remedial."}, "B3-01": {"code": "B3-01", "title": "Sampul Bab 3", "treat": "Sampul Bab 3: judul, durasi, empat tujuan, dan daftar pelajaran.", "pel": "Pembuka", "tpl": "T01", "screen": [{"li": "Bab 3 · Nyuushitsu & Ojigi (入室・お辞儀, nyuushitsu & ojigi: masuk ruangan & membungkuk memberi hormat)", "lvl": 0, "num": null}, {"li": "±12 menit · 13 slide", "lvl": 0, "num": null}, {"li": "Setelah bab ini, kamu mampu:", "lvl": 0, "num": null}, {"li": "mengurutkan langkah masuk ruang wawancara;", "lvl": 1, "num": "1."}, {"li": "menggunakan ungkapan yang tepat di setiap langkah;", "lvl": 1, "num": "2."}, {"li": "membedakan dan menerapkan tiga jenis ojigi;", "lvl": 1, "num": "3."}, {"li": "duduk dan meletakkan barang dengan benar.", "lvl": 1, "num": "4."}], "narasi": "Wawancara dimulai sejak kamu mengetuk pintu. Di Bab 3, kita berlatih masuk ruangan, membungkuk, dan duduk dengan benar.", "visual": "Rani berdiri di depan pintu ruang wawancara; judul bab 入室・お辞儀, kartu tujuan, daftar P1–P3, tombol \"Mulai Bab\"."}, "B3-02": {"code": "B3-02", "title": "Temukan 3 Kesalahan! (Pemantik)", "treat": "Pemantik video: temukan tiga kesalahan Dimas saat masuk ruangan.", "pel": "P1", "tpl": "T08", "screen": [{"p": "Video peragaan pendek (±20 detik): anggota tim berperan sebagai kandidat bernama Dimas yang masuk ruang wawancara. Video berhenti di tiga titik; peserta mengetuk bagian yang menurutnya salah."}, {"table": [["Titik henti", "Kesalahan Dimas", "Pop-up setelah ditemukan"], ["1", "Mengetuk pintu dua kali", "\"Dua ketukan sering dipakai untuk mengecek toilet. Di wawancara, ketuk tiga kali.\""], ["2", "Langsung masuk sebelum ada jawaban", "\"Tunggu sampai dipersilakan masuk.\""], ["3", "Langsung duduk tanpa salam", "\"Berdiri dulu di samping kursi, perkenalkan diri, lalu duduk setelah dipersilakan.\""]]}], "narasi": "Perhatikan Dimas. Ada tiga kesalahan saat ia masuk ruangan. Bisakah kamu menemukannya?", "visual": "Pemutar video 16:9 (HP: lebar penuh) yang berhenti di tiga titik; area salah bisa diketuk; penghitung kesalahan dan tombol \"Beri petunjuk\"."}, "B3-03": {"code": "B3-03", "title": "Tujuh Langkah Masuk Ruangan", "treat": "Peta tujuh langkah dari pintu ke kursi.", "pel": "P1", "tpl": "T03", "screen": [{"p": "Peta tujuh langkah berupa garis bergambar dari pintu ke kursi."}, {"li": "Ketuk pintu tiga kali.", "lvl": 0, "num": "1."}, {"li": "Tunggu sampai dipersilakan masuk.", "lvl": 0, "num": "2."}, {"li": "Buka pintu, ucapkan 「失礼します」 (shitsurei shimasu, \"permisi\"), lalu masuk.", "lvl": 0, "num": "3."}, {"li": "Tutup pintu dengan tenang, lalu menghadap pewawancara dan ojigi.", "lvl": 0, "num": "4."}, {"li": "Berjalan ke samping kursi.", "lvl": 0, "num": "5."}, {"li": "Perkenalkan diri singkat dan ojigi.", "lvl": 0, "num": "6."}, {"li": "Setelah dipersilakan, ucapkan 「失礼します」 (shitsurei shimasu, \"permisi\") dan duduk.", "lvl": 0, "num": "7."}], "narasi": "Ada tujuh langkah dari pintu sampai kursi. Kita pelajari satu per satu.", "visual": "Garis bergambar denah ruang: pintu → kursi, tujuh nomor langkah di sepanjang garis; ilustrasi kecil muncul di atas nomor yang diketuk; tombol \"Putar semua\"."}, "B3-04": {"code": "B3-04", "title": "Langkah 1–2: Mengetuk dan Menunggu", "treat": "Langkah 1–2: mengetuk tiga kali dan menunggu jawaban.", "pel": "P1", "tpl": "T03", "screen": [{"p": "**Langkah 1:** ketuk pintu tiga kali dengan tempo tenang (tok, tok, tok)."}, {"p": "**Langkah 2:** tunggu jawaban dari dalam: 「どうぞ」 (douzo) atau 「お入りください」 (ohairi kudasai), artinya \"Silakan masuk.\""}, {"li": "Jika belum ada jawaban setelah beberapa detik, ketuk lagi tiga kali.", "lvl": 0, "num": null}, {"li": "Jika pintu sudah terbuka, tetap ketuk pelan atau ucapkan 「失礼します」 (shitsurei shimasu, \"permisi\") sebelum masuk.", "lvl": 0, "num": null}, {"p": "Kotak \"Tahukah kamu?\": di perusahaan asing yang beroperasi di Jepang, ketukan empat kali juga lazim. Jika kamu terlanjur salah jumlah ketukan, jangan mengulang; tetap tenang dan tunjukkan sikap baik di langkah berikutnya, karena hasil wawancara dinilai secara keseluruhan. Pada wawancara kelompok, hanya orang pertama yang mengetuk."}], "narasi": "Ketuk pintu tiga kali, lalu tunggu sampai pewawancara mempersilakan masuk. Jangan masuk sebelum ada jawaban.", "visual": "Ilustrasi pintu besar yang bisa diketuk; gelembung suara pewawancara 「どうぞ」/「お入りください」 dengan ikon speaker; kotak \"Tahukah kamu?\"."}, "B3-05": {"code": "B3-05", "title": "Langkah 3–4: Masuk dan Menutup Pintu", "treat": "Langkah 3–4: masuk dengan salam dan menutup pintu tanpa membelakangi.", "pel": "P1", "tpl": "T07", "screen": [{"p": "**Langkah 3:** buka pintu, ucapkan 「失礼します」 (shitsurei shimasu, \"permisi\") dengan suara jelas, lalu masuk."}, {"p": "**Langkah 4:** putar badan sedikit ke arah pintu dan tutup pintu pelan dengan tangan, tanpa membelakangi pewawancara sepenuhnya. Setelah itu, menghadap pewawancara dan lakukan ojigi ±30°."}, {"p": "Kotak \"Hindari\": membanting pintu, menutup pintu dengan kaki atau tanpa melihat, dan membiarkan pintu terbuka."}], "narasi": "Ucapkan shitsurei shimasu dengan jelas saat masuk. Tutup pintu dengan tenang, lalu menghadap pewawancara dan membungkuk.", "visual": "Dua tombol \"Benar\" dan \"Salah\" di atas pemutar video; kartu ungkapan 「失礼します」 beraudio; kotak \"Hindari\"."}, "B3-06": {"code": "B3-06", "title": "Langkah 5–7: Perkenalan Singkat dan Duduk", "treat": "Langkah 5–7: berdiri di samping kursi, perkenalan singkat, duduk.", "pel": "P1", "tpl": "T05", "screen": [{"p": "**Langkah 5:** berjalan tenang ke samping kursi (biasanya sisi yang dekat pintu), bukan ke depan kursi."}, {"p": "**Langkah 6:** perkenalkan diri singkat, lalu ojigi ±30°: 「〇〇と申します。本日はよろしくお願いいたします。」 (… to moushimasu. Honjitsu wa yoroshiku onegai itashimasu. \"Nama saya …. Mohon kerja samanya hari ini.\")"}, {"p": "**Langkah 7:** pewawancara berkata 「どうぞおかけください」 (douzo okake kudasai, \"Silakan duduk\"). Jawab 「失礼します」 (shitsurei shimasu, \"permisi\"), ojigi ringan, lalu duduk."}, {"p": "Kotak \"Tahukah kamu? Wawancara online\": tidak ada pintu, tetapi salam tetap dilakukan. Saat terhubung, ucapkan perkenalan singkat dan ojigi ringan dari kursi, lalu duduk tegak."}], "narasi": "Berdirilah di samping kursi, perkenalkan dirimu secara singkat, lalu tunggu sampai dipersilakan duduk. Perkenalan lengkap atau jikoshoukai akan kamu pelajari di Bab 4.", "visual": "Denah kecil posisi samping kursi; kartu ungkapan langkah 6 dan 7 beraudio; tombol \"Wawancara online\" dan \"Latih ungkapan\"."}, "B3-07": {"code": "B3-07", "title": "Dengar dan Tirukan: Ungkapan Masuk Ruangan", "treat": "Layer B3-06: dengar dan tirukan lima ungkapan masuk ruangan.", "pel": "P1", "tpl": "T15", "screen": [{"p": "Lima kartu ungkapan dalam urutan kejadian."}, {"table": [["Siapa", "Ungkapan", "Cara baca", "Arti"], ["Pewawancara", "どうぞ。/ お入りください。", "douzo / ohairi kudasai", "Silakan (masuk)."], ["Kamu", "失礼します。", "shitsurei shimasu", "Permisi."], ["Kamu", "〇〇と申します。本日はよろしくお願いいたします。", "… to moushimasu. Honjitsu wa yoroshiku onegai itashimasu.", "Nama saya …. Mohon kerja samanya hari ini."], ["Pewawancara", "どうぞおかけください。", "douzo okake kudasai", "Silakan duduk."], ["Kamu", "失礼します。(lalu duduk)", "shitsurei shimasu", "Permisi."]]}], "narasi": "Dengarkan setiap ungkapan, lalu tirukan dengan suara jelas.", "visual": "Layer di atas B3-06: lima kartu ungkapan berurutan (pewawancara/kamu) dengan ikon speaker, tombol \"Rekam\" dan pemutar rekaman berdampingan dengan contoh."}, "B3-08": {"code": "B3-08", "title": "Tiga Jenis Ojigi", "treat": "Tiga jenis ojigi lewat penggeser sudut 0°–45°.", "pel": "P2", "tpl": "T09", "screen": [{"p": "お辞儀 (ojigi) = membungkuk untuk memberi hormat. Figur ilustrasi dengan penggeser sudut (slider) 0°–45°; saat penggeser melewati 15°, 30°, dan 45°, figur berhenti dan kartu jenis ojigi muncul."}, {"table": [["Jenis", "Sudut", "Kesan", "Contoh situasi"], ["会釈 eshaku", "±15°", "Salam ringan", "Berpapasan dengan staf di lorong; sebelum duduk setelah dipersilakan"], ["敬礼 keirei", "±30°", "Hormat, paling sering dipakai", "Menghadap pewawancara setelah masuk; memperkenalkan diri di samping kursi"], ["最敬礼 saikeirei", "±45°", "Sangat hormat", "Meminta maaf dengan sungguh-sungguh; ucapan terima kasih yang mendalam"]]}], "narasi": "Ada tiga jenis ojigi. Semakin dalam membungkuk, semakin besar rasa hormat yang ditunjukkan. Geser penggeser untuk melihat bedanya.", "visual": "Figur ilustrasi tampak samping di tengah; penggeser sudut di bawah; busur derajat tipis di belakang figur; kartu jenis ojigi muncul di 15°, 30°, 45°."}, "B3-09": {"code": "B3-09", "title": "Cara Ojigi yang Benar (語先後礼)", "treat": "Gosen gorei dan langkah membungkuk; video benar dan tiga video salah.", "pel": "P2", "tpl": "T07", "screen": [{"p": "語先後礼 (gosen gorei) = ucapkan kalimat dulu, baru membungkuk. Tidak berbicara sambil membungkuk."}, {"p": "Langkah membungkuk:"}, {"li": "berdiri tegak, pandangan ke lawan bicara;", "lvl": 0, "num": "1."}, {"li": "ucapkan salam;", "lvl": 0, "num": "2."}, {"li": "bungkukkan badan dari pinggang dengan punggung dan leher lurus;", "lvl": 0, "num": "3."}, {"li": "berhenti sejenak (±1 detik) di bawah;", "lvl": 0, "num": "4."}, {"li": "kembali tegak perlahan, lalu tatap lawan bicara lagi.", "lvl": 0, "num": "5."}, {"p": "Posisi tangan: pria di sisi badan; wanita ditumpuk di depan badan."}, {"p": "Perbandingan video peragaan \"Benar\" dan \"Salah\": salah 1 = berbicara sambil membungkuk; salah 2 = hanya menunduk dengan leher; salah 3 = membungkuk terlalu cepat tanpa berhenti."}], "narasi": "Ingat gosen gorei: kata dulu, baru membungkuk. Bungkukkan badan dari pinggang, berhenti sebentar, lalu kembali tegak perlahan.", "visual": "Prinsip 語先後礼 di pita atas; daftar lima langkah; empat tombol video (Benar, Salah 1–3) dengan pemutar di bawahnya."}, "B3-10": {"code": "B3-10", "title": "Ojigi yang Mana?", "treat": "Latihan memilih jenis ojigi untuk lima situasi.", "pel": "P2", "tpl": "T13", "screen": [{"p": "Lima situasi singkat; untuk setiap situasi, peserta memilih 会釈 (eshaku, 15°), 敬礼 (keirei, 30°), atau 最敬礼 (saikeirei, 45°)."}, {"table": [["Situasi", "Jawaban", "Umpan balik"], ["Berpapasan dengan staf perusahaan di lorong menuju ruang wawancara", "会釈 (15°)", "Salam ringan sudah cukup."], ["Menghadap pewawancara setelah menutup pintu", "敬礼 (30°)", "Ini salam hormat standar kepada pewawancara."], ["Memperkenalkan diri di samping kursi", "敬礼 (30°)", "Perkenalan diri memakai ojigi hormat."], ["Setelah dipersilakan duduk, sebelum duduk", "会釈 (15°)", "Cukup ojigi ringan sambil mengucapkan 「失礼します」 (shitsurei shimasu, \"permisi\")."], ["Meminta maaf karena datang terlambat", "最敬礼 (45°)", "Permintaan maaf yang sungguh-sungguh memakai ojigi terdalam."]]}], "narasi": "Sekarang coba pilih jenis ojigi yang tepat untuk setiap situasi.", "visual": "Kartu situasi bergambar; tiga tombol pilihan 会釈/敬礼/最敬礼 dengan sudut; figur membungkuk sesuai jawaban benar."}, "B3-11": {"code": "B3-11", "title": "Sikap Duduk dan Posisi Barang", "treat": "Sikap duduk dan posisi barang lewat hotspot pada figur duduk.", "pel": "P3", "tpl": "T03", "screen": [{"p": "Figur kandidat duduk (tampak samping dan depan) dengan lima titik hotspot; tombol ganti figur pria/wanita."}, {"table": [["Titik", "Pop-up"], ["Punggung", "Tegak, tidak bersandar ke sandaran kursi. Duduk kira-kira di dua pertiga bagian depan kursi."], ["Tangan", "Pria: tangan dikepal ringan di atas paha. Wanita: tangan ditumpuk di atas paha."], ["Kaki", "Pria: kaki dibuka selebar pinggul. Wanita: lutut dan kaki dirapatkan. Jangan menyilangkan kaki."], ["Pandangan", "Tatap pewawancara dengan natural. Jika gugup, pandang sekitar dagu atau simpul dasi pewawancara."], ["Tas", "Diletakkan di lantai, di samping kursi. Tidak di pangkuan, di meja, atau di kursi lain."]]}, {"p": "Kotak \"Hindari\": bersandar, menyilangkan kaki atau tangan, menggoyangkan kaki, memainkan rambut atau pulpen."}], "narasi": "Setelah duduk, jaga punggung tetap tegak dan jangan bersandar. Letakkan tas di lantai di samping kursi. Sikap dudukmu terus diperhatikan sampai wawancara selesai.", "visual": "Figur duduk tampak samping dan depan dengan lima titik hotspot; tombol ganti figur pria/wanita; kotak \"Hindari\"."}, "B3-12": {"code": "B3-12", "title": "Aktivitas: Susun Langkah Masuk Ruangan", "treat": "Latihan dua tahap: urutkan tujuh langkah lalu lengkapi ucapan.", "pel": "P3", "tpl": "T11", "screen": [{"p": "Dua tahap."}, {"p": "**Tahap A, urutkan:** tujuh kartu langkah (B3-03) dalam urutan acak; peserta menyusunnya dari pintu ke kursi."}, {"p": "**Tahap B, lengkapi ucapan:** pada empat langkah, muncul gelembung bicara kosong; peserta memilih ungkapan yang tepat dari lima pilihan:"}, {"li": "「失礼します」 (shitsurei shimasu, \"permisi\"; dipakai dua kali)", "lvl": 0, "num": null}, {"li": "「〇〇と申します。本日はよろしくお願いいたします」 (… to moushimasu. Honjitsu wa yoroshiku onegai itashimasu. \"Nama saya …. Mohon kerja samanya hari ini.\")", "lvl": 0, "num": null}, {"li": "「どうぞ」 (douzo, \"silakan\"; pengecoh, ini ucapan pewawancara)", "lvl": 0, "num": null}, {"li": "「失礼しました」 (shitsurei shimashita, \"permisi\" dalam bentuk lampau; pengecoh, dipakai saat keluar)", "lvl": 0, "num": null}], "narasi": "Susun ketujuh langkah dari pintu sampai kursi, lalu lengkapi apa yang kamu ucapkan di setiap langkah.", "visual": "Tahap A: tujuh kartu langkah acak dan tujuh slot bernomor. Tahap B: gelembung bicara kosong di empat langkah dengan lima pilihan ungkapan."}, "B3-13": {"code": "B3-13", "title": "Rangkuman Bab 3", "treat": "Rangkuman Bab 3, glosarium, dan kartu Kata Mutiara.", "pel": "Penutup", "tpl": "T17", "screen": [{"li": "Ketuk tiga kali → tunggu 「どうぞ」 (douzo, \"silakan\") → 「失礼します」 (shitsurei shimasu, \"permisi\") → tutup pintu, ojigi → ke samping kursi → perkenalan singkat, ojigi → 「失礼します」 (shitsurei shimasu), duduk.", "lvl": 0, "num": "1."}, {"li": "会釈 (eshaku) 15° salam ringan · 敬礼 (keirei) 30° hormat · 最敬礼 (saikeirei) 45° sangat hormat.", "lvl": 0, "num": "2."}, {"li": "語先後礼 (gosen gorei): kata dulu, baru membungkuk.", "lvl": 0, "num": "3."}, {"li": "Duduk tegak tanpa bersandar; tas di lantai di samping kursi.", "lvl": 0, "num": "4."}, {"p": "Kata Mutiara: **\"Kesan pertama sudah terbentuk sebelum kamu berbicara.\"**"}], "narasi": "Kamu sudah bisa masuk ruangan dan duduk dengan benar. Selanjutnya, pewawancara akan memintamu memperkenalkan diri. Tapi sebelum itu, uji pemahamanmu.", "visual": "Poin rangkuman bertahap (alur masuk berupa garis panah); kartu Kata Mutiara; tombol \"Glosarium Bab 3\" dan \"Mulai Kuis\"."}, "B3-14": {"code": "B3-14", "title": "Kuis Formatif Bab 3", "treat": "Kuis formatif 5 soal acak dari bank 10, lalu layar hasil dan remedial.", "pel": "Penutup", "tpl": "T18", "screen": [{"p": "bank 10 soal; tampil 5 soal acak (1 dari indikator 3.1, 1 dari 3.2, 2 dari 3.3, 1 dari 3.4), satu soal per layar, dengan umpan balik langsung; lulus bila skor ≥ 80 (4 dari 5 benar). Layar hasil (T19): skor ≥ 80 → \"Kamu lulus Bab 3!\" + animasi stempel. Skor < 80 → \"Hampir! Ulangi bagian berikut, lalu coba lagi.\" + daftar slide remedial sesuai soal yang salah."}], "narasi": "tidak ada; Navi bereaksi senang atau menyemangati di layar hasil (GLB-07). Soal, kunci, dan umpan balik: naskah Bab 3.", "visual": "Satu soal per layar dengan empat pilihan; layar hasil berisi skor, stempel Bab 3 atau daftar slide remedial."}, "B4-01": {"code": "B4-01", "title": "Sampul Bab 4", "treat": "Sampul Bab 4: judul, durasi, enam tujuan, dan daftar empat pelajaran.", "pel": "Pembuka", "tpl": "T01", "screen": [{"li": "Bab 4 · Jikoshoukai (自己紹介, jikoshoukai: perkenalan diri)", "lvl": 0, "num": null}, {"li": "±18 menit · 17 slide", "lvl": 0, "num": null}, {"li": "Setelah bab ini, kamu mampu:", "lvl": 0, "num": null}, {"li": "menjelaskan fungsi jikoshoukai dan bedanya dengan 自己PR (jiko PR, promosi diri);", "lvl": 1, "num": "1."}, {"li": "mengurutkan lima blok jikoshoukai;", "lvl": 1, "num": "2."}, {"li": "memilih ungkapan yang tepat untuk setiap blok;", "lvl": 1, "num": "3."}, {"li": "menyusun jikoshoukai tentang dirimu sendiri;", "lvl": 1, "num": "4."}, {"li": "mengenali dan memperbaiki kesalahan umum;", "lvl": 1, "num": "5."}, {"li": "mengucapkan jikoshoukai selama 30–60 detik dengan jelas.", "lvl": 1, "num": "6."}], "narasi": "Setelah kamu duduk, pewawancara hampir selalu memintamu memperkenalkan diri. Di Bab 4, kamu akan menyusun dan melatih jikoshoukai-mu sendiri.", "visual": "Rani duduk tegak di ruang wawancara dengan gelembung 「はじめまして」; judul 自己紹介, kartu tujuan, daftar P1–P4, tombol \"Mulai Bab\"."}, "B4-02": {"code": "B4-02", "title": "Mana yang Lebih Meyakinkan? (Pemantik)", "treat": "Pemantik audio: bandingkan dua jikoshoukai dan pilih yang lebih meyakinkan.", "pel": "P1", "tpl": "T02", "screen": [{"p": "dengarkan dua jikoshoukai."}, {"li": "**Kandidat A (±5 detik):** 「ラニです。二十三歳です。よろしく。」 (Rani desu. Nijuusan-sai desu. Yoroshiku. \"Saya Rani. 23 tahun. Salam kenal.\")", "lvl": 0, "num": null}, {"li": "**Kandidat B (±40 detik):** jikoshoukai lengkap Rani (teks lengkap di B4-10).", "lvl": 0, "num": null}, {"p": "Pertanyaan 1: \"Mana yang lebih meyakinkan?\" Pertanyaan 2 (boleh pilih lebih dari satu): \"Apa yang membuatnya lebih meyakinkan?\" — lebih lengkap · lebih sopan · menyebut kelebihan · menyebut motivasi · lebih panjang."}], "narasi": "Dengarkan dua perkenalan diri ini. Menurutmu, mana yang lebih meyakinkan pewawancara, dan mengapa?", "visual": "Dua kartu audio \"Kandidat A (±5 dtk)\" dan \"Kandidat B (±40 dtk)\" dengan gelombang suara; tombol pilihan di bawah."}, "B4-03": {"code": "B4-03", "title": "Apa Itu Jikoshoukai dalam Wawancara?", "treat": "Fungsi jikoshoukai dan cara pewawancara memintanya.", "pel": "P1", "tpl": "T03", "screen": [{"p": "pewawancara biasanya memintanya dengan:"}, {"li": "「自己紹介をお願いします。」 (Jikoshoukai o onegai shimasu. \"Silakan perkenalkan diri.\")", "lvl": 0, "num": null}, {"li": "「簡単に自己紹介をしてください。」 (Kantan ni jikoshoukai o shite kudasai. \"Silakan perkenalkan diri secara singkat.\")", "lvl": 0, "num": null}, {"p": "Empat kartu fungsi:"}, {"li": "**Kesan pertama:** cara bicara, sikap, dan raut wajahmu langsung dinilai.", "lvl": 0, "num": "1."}, {"li": "**\"Daftar isi\" dirimu:** pewawancara memilih hal yang akan ditanyakan lebih lanjut dari isi jikoshoukai-mu. Sebutkan hal yang siap kamu jelaskan.", "lvl": 0, "num": "2."}, {"li": "**Bukti kemampuan bahasa:** menunjukkan bahwa kamu bisa menyusun dan mengucapkan bahasa Jepang yang sopan.", "lvl": 0, "num": "3."}, {"li": "**Mencairkan suasana:** membuka percakapan sebelum pertanyaan utama.", "lvl": 0, "num": "4."}, {"p": "Durasi ideal: **30–60 detik.**"}], "narasi": "Jikoshoukai adalah perkenalan diri singkat, sekitar setengah sampai satu menit. Anggap saja sebagai daftar isi dirimu: pewawancara akan bertanya lebih jauh dari apa yang kamu sebutkan.", "visual": "Dua gelembung permintaan pewawancara beraudio di atas; empat kartu fungsi berikon di bawah."}, "B4-04": {"code": "B4-04", "title": "自己紹介 dan 自己PR, Bedanya Apa?", "treat": "Beda 自己紹介 dan 自己PR dalam tabel bertahap.", "pel": "P1", "tpl": "T04", "screen": [{"table": [["", "自己紹介 (jikoshoukai, perkenalan diri)", "自己PR (jiko PR, promosi diri)"], ["Tujuan", "Memberi informasi dasar tentang dirimu dan membentuk kesan pertama", "Meyakinkan pewawancara tentang kelebihanmu"], ["Durasi", "30 detik–1 menit", "1–3 menit"], ["Isi", "Nama, asal, latar belakang, satu kelebihan, motivasi singkat", "Satu kelebihan + contoh pengalaman + cara memakainya di perusahaan"], ["Diminta dengan", "「自己紹介をお願いします」", "「自己PRをお願いします」 (jiko PR o onegai shimasu, \"silakan promosikan dirimu\") atau 「あなたの長所を教えてください」 (anata no chousho o oshiete kudasai, \"ceritakan kelebihanmu\")"]]}, {"p": "Kotak \"Hindari\": diminta jikoshoukai, tetapi berbicara tiga menit tentang kelebihan diri. Di jikoshoukai, kelebihan cukup satu kalimat dan satu bukti singkat; penjelasan panjang disimpan untuk saat ditanya (Bab 5)."}], "narasi": "Jikoshoukai dan jiko PR sering tertukar. Jikoshoukai singkat dan mencakup banyak hal. Jiko PR lebih panjang dan fokus pada kelebihanmu. Jawablah sesuai yang diminta.", "visual": "Tabel dua kolom (自己紹介 vs 自己PR) yang muncul per baris (HP: kartu geser); kotak \"Hindari\" merah muda di bawah."}, "B4-05": {"code": "B4-05", "title": "Lima Blok Jikoshoukai", "treat": "Lima blok jikoshoukai sebagai peta isi.", "pel": "P2", "tpl": "T03", "screen": [{"p": "lima blok tertutup; cara mudah mengingat: **Siapa → Dari mana → Pernah apa → Bisa apa → Mau apa.**"}, {"table": [["Blok", "Nama blok", "Isi", "Pertanyaan pengingat"], ["1", "挨拶と名前 (aisatsu to namae, salam dan nama)", "Salam pembuka dan nama", "Siapa kamu?"], ["2", "出身と年齢 (shusshin to nenrei, asal dan usia)", "Kota asal dan usia", "Dari mana?"], ["3", "経歴 (keireki, latar belakang)", "Pendidikan, pengalaman kerja, belajar bahasa Jepang", "Pernah apa?"], ["4", "長所 (chousho, kelebihan)", "Satu kelebihan dan satu bukti singkat", "Bisa apa?"], ["5", "志望の気持ちと結び (shibou no kimochi to musubi, motivasi dan penutup)", "Keinginan bekerja dan salam penutup", "Mau apa?"]]}], "narasi": "Jikoshoukai terdiri atas lima blok. Ingat urutannya dengan lima pertanyaan: siapa, dari mana, pernah apa, bisa apa, mau apa.", "visual": "Lima blok bernomor berwarna tersusun vertikal, tertutup; jembatan keledai Siapa → Dari mana → Pernah apa → Bisa apa → Mau apa; penghitung blok."}, "B4-06": {"code": "B4-06", "title": "Blok 1–2: Salam, Nama, Asal, dan Usia", "treat": "Blok 1–2: salam, nama, asal, usia; pop-up baca usia.", "pel": "P2", "tpl": "T05", "screen": [{"table": [["Ungkapan", "Cara baca", "Arti", "Catatan"], ["はじめまして。", "hajimemashite.", "Salam kenal.", "Untuk pertemuan pertama"], ["〇〇と申します。", "… to moushimasu.", "Nama saya ….", "Lebih sopan dari 〇〇です (… desu)"], ["インドネシアの〇〇から参りました。", "Indoneshia no … kara mairimashita.", "Saya berasal dari …, Indonesia.", "Bentuk sopan"], ["〇〇から来ました。", "… kara kimashita.", "Saya datang dari ….", "Bentuk sederhana, masih wajar"], ["〇歳です。", "… sai desu.", "Usia saya … tahun.", ""]]}, {"p": "Pop-up \"Baca usiamu\" (dibuka lewat tombol, tidak tampil langsung di slide; dengan audio):"}, {"table": [["Usia", "Tulisan", "Cara baca"], ["18", "十八歳", "juuhassai"], ["19", "十九歳", "juukyuusai"], ["20", "二十歳", "**hatachi** (bacaan khusus)"], ["21", "二十一歳", "nijuuissai"], ["22", "二十二歳", "nijuunisai"], ["23", "二十三歳", "nijuusansai"], ["24", "二十四歳", "nijuuyonsai"], ["25", "二十五歳", "nijuugosai"]]}, {"p": "Tips: nama Indonesia ditulis dengan katakana (contoh: ラニ, Rani). Ucapkan nama perlahan dan jelas, karena nama asing sulit ditangkap pewawancara."}], "narasi": "Buka dengan hajimemashite, lalu sebutkan nama dengan to moushimasu. Setelah itu, sebutkan asal dan usiamu. Perhatikan, usia dua puluh tahun dibaca hatachi.", "visual": "Kartu geser satu ungkapan per kartu (Jepang, romaji, arti, speaker) berwarna blok 1–2; tombol \"Baca usiamu\" membuka tabel usia 18–25."}, "B4-07": {"code": "B4-07", "title": "Blok 3: Latar Belakang", "treat": "Blok 3: latar belakang pendidikan, bahasa, dan kerja.", "pel": "P2", "tpl": "T05", "screen": [{"p": "pilih satu atau dua hal yang paling berhubungan dengan pekerjaan yang dilamar."}, {"table": [["Ungkapan", "Cara baca", "Arti"], ["高校を卒業しました。", "Koukou o sotsugyou shimashita.", "Saya lulus SMA/SMK."], ["日本語を〇年勉強しています。", "Nihongo o …nen benkyou shite imasu.", "Saya sudah belajar bahasa Jepang selama … tahun."], ["日本語能力試験のN4に合格しました。", "Nihongo nouryoku shiken no N4 ni goukaku shimashita.", "Saya lulus JLPT N4."], ["前は〇〇で〇年働いていました。", "Mae wa … de …nen hataraite imashita.", "Sebelumnya saya bekerja di … selama … tahun."]]}, {"p": "Kosakata tempat kerja: 工場 (koujou, pabrik) · お店 (omise, toko) · レストラン (resutoran, restoran) · ホテル (hoteru, hotel) · 農場 (noujou, lahan pertanian)."}], "narasi": "Di blok tiga, ceritakan latar belakangmu: sekolah, pengalaman kerja, atau belajar bahasa Jepang. Pilih yang paling berhubungan dengan pekerjaan yang kamu lamar.", "visual": "Kartu ungkapan blok 3 beraudio; deret chip kosakata tempat kerja (工場, お店, レストラン, ホテル, 農場) yang bisa diketuk."}, "B4-08": {"code": "B4-08", "title": "Blok 4: Kelebihan (長所)", "treat": "Blok 4: kelebihan dengan pola dan satu bukti singkat.", "pel": "P2", "tpl": "T05", "screen": [{"p": "pola: 「私の長所は、〜ことです。」 (Watashi no chousho wa, … koto desu. \"Kelebihan saya adalah ….\") + satu bukti singkat."}, {"table": [["Kelebihan", "Cara baca", "Arti"], ["まじめなこと", "majime na koto", "rajin dan sungguh-sungguh"], ["時間を守ること", "jikan o mamoru koto", "selalu tepat waktu"], ["体力があること", "tairyoku ga aru koto", "punya stamina yang kuat"], ["責任感が強いこと", "sekininkan ga tsuyoi koto", "punya rasa tanggung jawab tinggi"], ["明るいこと", "akarui koto", "ceria dan mudah bergaul"]]}, {"p": "Contoh bukti singkat:"}, {"li": "「工場では二年間、一度も遅刻しませんでした。」 (Koujou de wa ninenkan, ichido mo chikoku shimasen deshita. \"Selama dua tahun di pabrik, saya tidak pernah sekali pun terlambat.\")", "lvl": 0, "num": null}, {"li": "「毎日、五キロ走っています。」 (Mainichi, go-kiro hashitte imasu. \"Saya berlari lima kilometer setiap hari.\")", "lvl": 0, "num": null}, {"p": "Tips: pilih kelebihan yang dibutuhkan di tempat kerja Jepang, misalnya tepat waktu, tanggung jawab, atau stamina, dan sertakan satu bukti."}], "narasi": "Sebutkan satu kelebihanmu dengan pola watashi no chousho wa, lalu tambahkan satu bukti singkat. Bukti membuat kelebihanmu lebih meyakinkan.", "visual": "Pola kalimat di pita atas; lima kartu kelebihan (まじめ, 時間を守る, 体力, 責任感, 明るい); contoh kalimat utuh muncul di bawah kartu yang dipilih."}, "B4-09": {"code": "B4-09", "title": "Blok 5: Motivasi dan Penutup", "treat": "Blok 5: motivasi dan penutup dengan ojigi.", "pel": "P2", "tpl": "T05", "screen": [{"table": [["Ungkapan", "Cara baca", "Arti"], ["日本の会社で一生懸命働きたいです。", "Nihon no kaisha de isshoukenmei hatarakitai desu.", "Saya ingin bekerja dengan sungguh-sungguh di perusahaan Jepang."], ["日本で技術を学びたいです。", "Nihon de gijutsu o manabitai desu.", "Saya ingin mempelajari keterampilan kerja di Jepang."], ["御社で働きたいです。", "Onsha de hatarakitai desu.", "Saya ingin bekerja di perusahaan Bapak/Ibu."], ["どうぞよろしくお願いいたします。", "Douzo yoroshiku onegai itashimasu.", "Mohon bimbingan dan kerja samanya."]]}, {"p": "Catatan kecil: 御社 (onsha) = \"perusahaan Anda\", dipakai saat berbicara langsung kepada pewawancara."}, {"p": "Penutup: ucapkan 「どうぞよろしくお願いいたします」, lalu 敬礼 (keirei, ojigi 30°) sesuai 語先後礼 (gosen gorei, kata dulu baru membungkuk) dari Bab 3. Jika duduk, ojigi dilakukan dari kursi."}, {"p": "Kotak \"Hindari\": motivasi yang hanya tentang uang, misalnya 「お金がほしいです」 (okane ga hoshii desu, \"saya ingin uang\"). Jujur boleh, tetapi sampaikan juga apa yang ingin kamu pelajari dan berikan."}], "narasi": "Tutup jikoshoukai dengan keinginanmu bekerja dan belajar, lalu ucapkan douzo yoroshiku onegai itashimasu sambil membungkuk setelahnya.", "visual": "Kartu ungkapan motivasi dan penutup beraudio; catatan 御社; ilustrasi kecil keirei 30°; tombol \"Hindari\"."}, "B4-10": {"code": "B4-10", "title": "Contoh Utuh: Jikoshoukai Rani", "treat": "Contoh utuh jikoshoukai Rani per blok dan mode Putar semua.", "pel": "P2", "tpl": "T05", "screen": [{"p": "jikoshoukai lengkap (±40 detik), ditampilkan satu blok per kartu (Jepang, romaji, arti) yang digeser; tombol \"Putar semua\" menampilkan teks Jepang utuh lima blok dengan warna per blok dan sorotan kalimat yang sedang diucapkan."}, {"table": [["Blok", "Bahasa Jepang", "Romaji", "Arti"], ["1", "はじめまして。ラニと申します。", "Hajimemashite. Rani to moushimasu.", "Salam kenal. Nama saya Rani."], ["2", "インドネシアのバンドンから参りました。二十三歳です。", "Indoneshia no Bandon kara mairimashita. Nijuusansai desu.", "Saya berasal dari Bandung, Indonesia. Usia saya 23 tahun."], ["3", "高校を卒業してから、工場で二年働いていました。日本語は一年勉強して、N4に合格しました。", "Koukou o sotsugyou shite kara, koujou de ninen hataraite imashita. Nihongo wa ichinen benkyou shite, N4 ni goukaku shimashita.", "Setelah lulus SMK, saya bekerja di pabrik selama dua tahun. Saya belajar bahasa Jepang satu tahun dan lulus N4."], ["4", "私の長所は、時間を守ることです。工場では二年間、一度も遅刻しませんでした。", "Watashi no chousho wa, jikan o mamoru koto desu. Koujou de wa ninenkan, ichido mo chikoku shimasen deshita.", "Kelebihan saya adalah selalu tepat waktu. Selama dua tahun di pabrik, saya tidak pernah sekali pun terlambat."], ["5", "日本の会社で技術を学んで、一生懸命働きたいです。どうぞよろしくお願いいたします。", "Nihon no kaisha de gijutsu o manande, isshoukenmei hatarakitai desu. Douzo yoroshiku onegai itashimasu.", "Saya ingin mempelajari keterampilan di perusahaan Jepang dan bekerja dengan sungguh-sungguh. Mohon bimbingan dan kerja samanya."]]}], "narasi": "Dengarkan jikoshoukai Rani. Perhatikan lima blok, jeda di akhir setiap blok, dan intonasi yang turun di kalimat terakhir.", "visual": "Lima kartu blok yang digeser; mode \"Putar semua\" menampilkan teks utuh berwarna per blok dengan sorotan kalimat; pilihan kecepatan Normal/Pelan."}, "B4-11": {"code": "B4-11", "title": "Aktivitas: Cocokkan Kosakata", "treat": "Permainan cocokkan 10 pasang kosakata jikoshoukai.", "pel": "P2", "tpl": "T12", "screen": [{"p": "permainan mencocokkan kartu (memory match), 20 kartu tertutup (10 pasang). Kartu Jepang menampilkan romaji kecil di bawahnya."}, {"table": [["Kartu Jepang", "Romaji", "Pasangan (arti)"], ["はじめまして", "hajimemashite", "salam kenal"], ["と申します", "to moushimasu", "nama saya … (sopan)"], ["参りました", "mairimashita", "datang / berasal (sopan)"], ["卒業しました", "sotsugyou shimashita", "sudah lulus sekolah"], ["働いていました", "hataraite imashita", "dulu bekerja"], ["合格しました", "goukaku shimashita", "lulus ujian"], ["長所", "chousho", "kelebihan"], ["遅刻", "chikoku", "terlambat"], ["一生懸命", "isshoukenmei", "sungguh-sungguh"], ["技術", "gijutsu", "keterampilan kerja"]]}], "narasi": "Cocokkan kata Jepang dengan artinya. Dengarkan setiap kata saat kartunya terbuka.", "visual": "Papan 20 kartu tertutup (4×5); penghitung pasangan, bar waktu santai, dan tombol \"Petunjuk\" Navi."}, "B4-12": {"code": "B4-12", "title": "Hatsuon dan Intonasi", "treat": "Enam tips hatsuon dan intonasi dengan audio benar-salah.", "pel": "P3", "tpl": "T07", "screen": [{"p": "enam tips, masing-masing dengan audio \"Benar\" dan \"Salah\"."}, {"li": "**Tempo sedang:** tidak terburu-buru; pewawancara perlu waktu memahami nama dan kota asing.", "lvl": 0, "num": "1."}, {"li": "**Jeda di akhir setiap blok:** sekitar 1 detik untuk menarik napas.", "lvl": 0, "num": "2."}, {"li": "**Vokal panjang dibaca panjang:** 高校 (koukou, SMA) berbeda dengan ここ (koko, di sini); 合格 (goukaku), 卒業 (sotsugyou), 二十 (nijuu).", "lvl": 0, "num": "3."}, {"li": "**Konsonan ganda っ diberi ketukan:** 一生懸命 (i**s**shoukenmei), いっしょうけんめい.", "lvl": 0, "num": "4."}, {"li": "**です dan ます di akhir kalimat:** bunyi \"u\" hampir tidak terdengar (desu → \"des\"), dan intonasi turun dengan mantap.", "lvl": 0, "num": "5."}, {"li": "**Suara jelas dan pandangan ke depan:** jangan menunduk atau bergumam.", "lvl": 0, "num": "6."}], "narasi": "Pelafalan yang jelas membuat jikoshoukai-mu mudah dipahami. Dengarkan perbedaan versi yang benar dan yang salah di setiap tips.", "visual": "Enam kartu tips bernomor, masing-masing dengan dua tombol audio \"Benar\" dan \"Salah\" serta gelombang suara kecil."}, "B4-13": {"code": "B4-13", "title": "Kesalahan Umum: Dengar dan Temukan", "treat": "Dengar empat rekaman dan temukan kesalahan utamanya.", "pel": "P3", "tpl": "T08", "screen": [{"p": "dengarkan empat rekaman jikoshoukai, lalu pilih kesalahan utama di setiap rekaman."}, {"table": [["Rekaman", "Isi", "Kesalahan utama", "Umpan balik"], ["1", "「ラニです。二十三歳です。よろしく。」 (Rani desu. Nijuusansai desu. Yoroshiku. \"Saya Rani. 23 tahun. Salam kenal.\"), ±5 detik", "Terlalu singkat dan kurang sopan", "Lengkapi lima blok dan pakai と申します (to moushimasu) serta よろしくお願いいたします (yoroshiku onegai itashimasu)."], ["2", "Isi lengkap, tetapi dibaca cepat tanpa berhenti dan nadanya datar", "Tanpa jeda, seperti menghafal", "Beri jeda di akhir setiap blok dan ucapkan seperti berbicara, bukan membaca."], ["3", "Berbicara 2,5 menit tentang kelebihan dan pengalaman", "Berubah menjadi 自己PR (jiko PR, promosi diri)", "Jikoshoukai cukup 30–60 detik; simpan cerita panjang untuk saat ditanya."], ["4", "Isi lengkap, tetapi suara pelan dan nada naik di akhir setiap kalimat", "Suara pelan dan intonasi naik", "Bicara lebih jelas dan turunkan nada di akhir kalimat agar terdengar yakin."]]}, {"p": "Ringkasan enam kesalahan umum: terlalu singkat · terlalu panjang (menjadi jiko PR) · bahasa santai (だ da, よろしく yoroshiku) · tanpa jeda karena menghafal · tidak menyebut kelebihan atau motivasi · menunduk dan suara pelan."}], "narasi": "Dengarkan empat perkenalan diri ini. Masing-masing punya satu kesalahan utama. Bisakah kamu menemukannya?", "visual": "Empat kartu rekaman bernomor dengan tombol putar; pilihan jenis kesalahan berupa chip; ringkasan enam kesalahan umum di bawah."}, "B4-14": {"code": "B4-14", "title": "Susun Jikoshoukai-mu", "treat": "Penyusun jikoshoukai lima langkah sampai jadi teks milik peserta.", "pel": "P4", "tpl": "T16", "screen": [{"p": "penyusun jikoshoukai lima langkah. Peserta memilih atau mengisi data dirinya; sistem merangkai kalimat Jepang yang sudah dicek SME, lengkap dengan romaji dan arti."}, {"table": [["Blok", "Yang diisi peserta", "Kalimat yang dihasilkan"], ["1", "Nama (katakana; ada panduan huruf katakana)", "「はじめまして。〇〇と申します。」 (Hajimemashite. … to moushimasu.)"], ["2", "Kota asal (daftar: ジャカルタ Jakaruta, バンドン Bandon, スラバヤ Surabaya, ジョグジャカルタ Jogujakaruta, スマラン Sumaran, メダン Medan, マカッサル Makassaru, atau ketik sendiri) dan usia 18–25", "「インドネシアの〇〇から参りました。〇歳です。」 (Indoneshia no … kara mairimashita. …sai desu.)"], ["3", "Centang 1–2: lulus SMA/SMK · lama belajar bahasa Jepang · lulus N4 · pengalaman kerja (tempat dan lama)", "Kalimat dari B4-07 sesuai pilihan"], ["4", "Pilih satu kelebihan dan satu bukti singkat (bukti boleh dilewati)", "「私の長所は、〜ことです。」 (Watashi no chousho wa, … koto desu.) + bukti"], ["5", "Pilih satu motivasi", "Kalimat motivasi dari B4-09 + 「どうぞよろしくお願いいたします。」"]]}, {"p": "Hasil akhir: teks utuh (Jepang, romaji, arti), perkiraan durasi bicara, dan tanda centang lima blok."}], "narasi": "Sekarang susun jikoshoukai-mu sendiri. Isi setiap blok, dan sistem akan merangkai kalimatnya untukmu.", "visual": "Wizard lima langkah dengan bilah langkah di atas; isian/pilihan per blok; panel hasil berisi teks utuh dan perkiraan durasi; tombol salin/unduh."}, "B4-15": {"code": "B4-15", "title": "Latihan Lisan: Rekam Jikoshoukai-mu (3 lapis)", "treat": "Latihan lisan jikoshoukai dengan penilaian tiga lapis.", "pel": "P4", "tpl": "T15", "screen": [{"p": "alur yang sama dengan prototipe penilaian lisan."}, {"li": "**Persiapan:** pilih mode panduan: \"Teks penuh\" (latihan awal) atau \"Hanya nama blok\" (latihan mandiri, seperti wawancara sungguhan).", "lvl": 0, "num": "1."}, {"li": "**Rekam:** tombol rekam, timer dengan zona target 30–60 detik, indikator volume; berhenti otomatis di 90 detik.", "lvl": 0, "num": "2."}, {"li": "**Lapis 1, analisis otomatis:** grafik gelombang suara dengan jeda yang ditandai, serta kartu Durasi, Jeda, dan Volume beserta umpan baliknya.", "lvl": 0, "num": "3."}, {"li": "**Lapis 2, penilaian diri:** putar rekamanmu dan contoh Rani per blok secara bergantian, lalu isi daftar periksa 7 butir.", "lvl": 0, "num": "4."}, {"li": "**Lapis 3, untuk instruktur:** ringkasan \"Profil Kesiapan Lisan\", tombol \"Unduh rekaman\" dan \"Unduh lembar rubrik\".", "lvl": 0, "num": "5."}], "narasi": "Saatnya berlatih bicara. Rekam jikoshoukai-mu, lihat hasil analisisnya, bandingkan dengan contoh, lalu unduh rekamanmu untuk instruktur. Kamu boleh berlatih berkali-kali.", "visual": "Pilihan mode panduan; tombol rekam bulat besar dan timer berzona 30–60 detik; panel hasil Lapis 1 (gelombang suara, Durasi, Jeda, Volume); checklist Lapis 2; tombol unduh untuk rubrik instruktur (Lapis 3)."}, "B4-16": {"code": "B4-16", "title": "Rangkuman Bab 4", "treat": "Rangkuman Bab 4, jikoshoukai-ku, glosarium, dan Kata Mutiara.", "pel": "Penutup", "tpl": "T17", "screen": [{"li": "Jikoshoukai = perkenalan diri singkat 30–60 detik, \"daftar isi\" dirimu. 自己PR (jiko PR) lebih panjang dan fokus pada kelebihan.", "lvl": 0, "num": "1."}, {"li": "Lima blok: Siapa → Dari mana → Pernah apa → Bisa apa → Mau apa.", "lvl": 0, "num": "2."}, {"li": "Ungkapan kunci: と申します (to moushimasu) · から参りました (kara mairimashita) · 私の長所は (watashi no chousho wa) · どうぞよろしくお願いいたします (douzo yoroshiku onegai itashimasu).", "lvl": 0, "num": "3."}, {"li": "Hindari: terlalu singkat, terlalu panjang, bahasa santai, tanpa jeda, menunduk.", "lvl": 0, "num": "4."}, {"p": "Kata Mutiara: **\"Jikoshoukai yang baik itu singkat, jelas, dan tidak terburu-buru.\"**"}], "narasi": "Kamu sudah punya jikoshoukai sendiri. Teruslah berlatih sampai lancar tanpa melihat teks. Sekarang, uji pemahamanmu.", "visual": "Poin rangkuman bertahap; tombol \"Lihat jikoshoukai-ku\"; kartu Kata Mutiara; tombol glosarium dan \"Mulai Kuis\"."}, "B4-17": {"code": "B4-17", "title": "Kuis Formatif Bab 4", "treat": "Kuis formatif 5 soal acak dari bank 10, lalu layar hasil dan remedial.", "pel": "Penutup", "tpl": "T18", "screen": [{"p": "bank 10 soal; tampil 5 soal acak (1 dari setiap indikator 4.1–4.5), satu soal per layar, dengan umpan balik langsung; lulus bila skor ≥ 80 (4 dari 5 benar). Indikator 4.6 diukur lewat penilaian lisan B4-15. Layar hasil (T19): skor ≥ 80 → \"Kamu lulus Bab 4!\" + animasi stempel. Skor < 80 → \"Hampir! Ulangi bagian berikut, lalu coba lagi.\" + daftar slide remedial."}], "narasi": "tidak ada; Navi bereaksi senang atau menyemangati di layar hasil (GLB-07). Soal, kunci, dan umpan balik: naskah Bab 4.", "visual": "Satu soal per layar dengan empat pilihan (soal audio memakai tombol putar); layar hasil berisi skor, stempel Bab 4 atau daftar slide remedial."}, "B5-01": {"code": "B5-01", "title": "Sampul Bab 5", "treat": "Sampul Bab 5: judul, durasi, empat tujuan, dan daftar lima pelajaran.", "pel": "Pembuka", "tpl": "T01", "screen": [{"li": "Bab 5 · Menjawab Pertanyaan (質疑応答, shitsugi outou: tanya jawab)", "lvl": 0, "num": null}, {"li": "±15 menit · 15 slide", "lvl": 0, "num": null}, {"li": "Setelah bab ini, kamu mampu:", "lvl": 0, "num": null}, {"li": "memahami maksud pertanyaan umum pewawancara;", "lvl": 1, "num": "1."}, {"li": "menjawab dengan pola Jawab → Alasan → Semangat secara jujur;", "lvl": 1, "num": "2."}, {"li": "tahu apa yang diucapkan saat tidak memahami pertanyaan;", "lvl": 1, "num": "3."}, {"li": "mengajukan pertanyaan balik yang sopan.", "lvl": 1, "num": "4."}], "narasi": "Setelah jikoshoukai, pewawancara akan bertanya lebih jauh tentang dirimu. Di Bab 5, kamu belajar memahami pertanyaan dan menjawabnya dengan jelas dan jujur.", "visual": "Rani duduk di depan pewawancara dengan gelembung tanda tanya; judul 質疑応答, kartu tujuan, daftar P1–P5, tombol \"Mulai Bab\"."}, "B5-02": {"code": "B5-02", "title": "Pertanyaannya Terlalu Cepat! (Pemantik)", "treat": "Pemantik: pertanyaan diucapkan terlalu cepat tanpa teks.", "pel": "P1", "tpl": "T02", "screen": [{"p": "audio pewawancara berbicara cepat tanpa teks. \"Kamu tidak menangkap pertanyaannya. Apa yang kamu lakukan?\""}, {"li": "Diam dan menunggu pewawancara bertanya lagi.", "lvl": 0, "num": null}, {"li": "Menjawab 「はい」 (hai, \"ya\") saja.", "lvl": 0, "num": null}, {"li": "Meminta pewawancara mengulang pertanyaannya.", "lvl": 0, "num": null}, {"li": "Menjawab dengan jawaban yang sudah kamu hafalkan.", "lvl": 0, "num": null}, {"p": "Setelah memilih, Show teks pertanyaan: 「志望動機を教えていただけますか。」 (Shibou douki o oshiete itadakemasu ka. \"Bolehkah Anda menceritakan alasan melamar?\")"}], "narasi": "Pewawancara tidak selalu berbicara pelan. Kalau kamu tidak menangkap pertanyaannya, apa yang sebaiknya kamu lakukan?", "visual": "Pewawancara berbicara (gelombang suara cepat, tanpa teks); empat kartu pilihan tindakan di bawah."}, "B5-03": {"code": "B5-03", "title": "Pola Menjawab: Jawab → Alasan → Semangat", "treat": "Pola menjawab Jawab → Alasan → Semangat.", "pel": "P1", "tpl": "T05", "screen": [{"p": "jawaban yang baik cukup 2–3 kalimat (±15–30 detik) dengan pola:"}, {"li": "**Jawab** (結論, ketsuron): langsung jawab pertanyaannya.", "lvl": 0, "num": "1."}, {"li": "**Alasan** (理由, riyuu): satu alasan atau contoh singkat.", "lvl": 0, "num": "2."}, {"li": "**Semangat** (意欲, iyoku): tunjukkan kemauanmu.", "lvl": 0, "num": "3."}, {"p": "Contoh untuk 「なぜ日本で働きたいですか。」 (Naze Nihon de hatarakitai desu ka. \"Mengapa kamu ingin bekerja di Jepang?\"):"}, {"table": [["Bagian", "Bahasa Jepang", "Romaji", "Arti"], ["Jawab", "日本の技術を学びたいからです。", "Nihon no gijutsu o manabitai kara desu.", "Karena saya ingin mempelajari keterampilan kerja Jepang."], ["Alasan", "日本の会社は時間を守って、ていねいに仕事をすると聞きました。", "Nihon no kaisha wa jikan o mamotte, teinei ni shigoto o suru to kikimashita.", "Saya dengar perusahaan Jepang tepat waktu dan bekerja dengan teliti."], ["Semangat", "私もそのように働きたいです。", "Watashi mo sono you ni hatarakitai desu.", "Saya juga ingin bekerja seperti itu."]]}, {"p": "Kotak \"Hindari\": hanya menjawab 「はい」 (hai, \"ya\") atau satu kata; bercerita panjang lebih dari satu menit."}], "narasi": "Jawab dulu, beri satu alasan, lalu tunjukkan semangatmu. Dua sampai tiga kalimat sudah cukup.", "visual": "Tabel tiga bagian berwarna (結論, 理由, 意欲) dengan contoh jawaban; bagian menyala saat diketuk; tombol \"Putar jawaban utuh\"."}, "B5-04": {"code": "B5-04", "title": "Kelompok 1: Pertanyaan tentang Motivasi", "treat": "Kelompok 1: pertanyaan motivasi, satu pertanyaan per kartu.", "pel": "P2", "tpl": "T06", "screen": [{"p": "kartu pertanyaan yang digeser, satu pertanyaan per layar (berlaku juga untuk B5-05 s.d. B5-07); setiap kartu berisi audio pertanyaan, lalu contoh jawaban dan tips yang dibuka dengan tombol."}, {"table": [["Pertanyaan", "Contoh jawaban Rani", "Tips"], ["「なぜ日本で働きたいですか。」 (Naze Nihon de hatarakitai desu ka. \"Mengapa kamu ingin bekerja di Jepang?\")", "Jawaban di B5-03.", "Sebutkan apa yang ingin kamu pelajari, bukan hanya uang."], ["「志望動機を教えてください。」 (Shibou douki o oshiete kudasai. \"Ceritakan alasanmu melamar ke perusahaan ini.\")", "「御社は食品工場で、安全な食品を作っていると知りました。私も前に工場で働いていたので、その経験を生かしたいです。」 (Onsha wa shokuhin koujou de, anzen na shokuhin o tsukutte iru to shirimashita. Watashi mo mae ni koujou de hataraite ita node, sono keiken o ikashitai desu. \"Saya tahu perusahaan Bapak/Ibu adalah pabrik makanan yang membuat makanan yang aman. Karena saya pernah bekerja di pabrik, saya ingin memanfaatkan pengalaman itu.\")", "Sebut satu hal spesifik tentang perusahaan dari hasil risetmu (Bab 1), lalu hubungkan dengan pengalamanmu."]]}, {"p": "Catatan kosakata: 志望動機 (shibou douki) = alasan melamar; 生かす (ikasu) = memanfaatkan."}], "narasi": "Pertanyaan tentang motivasi hampir selalu muncul. Pewawancara ingin tahu mengapa kamu memilih Jepang dan mengapa kamu memilih perusahaan ini.", "visual": "Kartu pertanyaan geser: tombol putar dan ikon mata di atas, tombol \"Lihat contoh jawaban\" dan \"Tips\"; catatan kosakata di bawah."}, "B5-05": {"code": "B5-05", "title": "Kelompok 2: Pertanyaan tentang Dirimu", "treat": "Kelompok 2: pertanyaan tentang diri (kelebihan, kekurangan, stamina).", "pel": "P2", "tpl": "T06", "screen": [{"table": [["Pertanyaan", "Contoh jawaban Rani", "Tips"], ["「あなたの長所と短所を教えてください。」 (Anata no chousho to tansho o oshiete kudasai. \"Ceritakan kelebihan dan kekuranganmu.\")", "「長所は、時間を守ることです。短所は、心配しすぎることです。でも、メモを取って、確認するようにしています。」 (Chousho wa, jikan o mamoru koto desu. Tansho wa, shinpai shisugiru koto desu. Demo, memo o totte, kakunin suru you ni shite imasu. \"Kelebihan saya adalah tepat waktu. Kekurangan saya adalah terlalu khawatir. Tetapi, saya selalu mencatat dan memeriksa ulang.\")", "Sebut kekurangan yang nyata tetapi tidak berbahaya bagi pekerjaan, lalu jelaskan usahamu memperbaikinya. Jangan menyebut \"sering terlambat\" atau \"tidak punya kekurangan\"."], ["「体力に自信がありますか。」 (Tairyoku ni jishin ga arimasu ka. \"Apakah kamu yakin dengan stamina fisikmu?\")", "「はい、あります。毎日、五キロ走っています。立ち仕事も大丈夫です。」 (Hai, arimasu. Mainichi, go-kiro hashitte imasu. Tachi shigoto mo daijoubu desu. \"Ya. Saya berlari lima kilometer setiap hari. Pekerjaan sambil berdiri juga tidak masalah.\")", "Banyak pekerjaan pabrik dan perawatan membutuhkan stamina. Beri bukti, bukan hanya \"ya\"."]]}, {"p": "Catatan kosakata: 短所 (tansho) = kekurangan; 体力 (tairyoku) = stamina fisik; 立ち仕事 (tachi shigoto) = pekerjaan sambil berdiri."}], "narasi": "Saat ditanya kekurangan, jujurlah, tetapi tunjukkan juga usahamu memperbaikinya. Itu justru membuatmu terlihat dewasa.", "visual": "Kartu pertanyaan geser: tombol putar dan ikon mata di atas, tombol \"Lihat contoh jawaban\" dan \"Tips\"; catatan kosakata di bawah; kartu pertanyaan geser dengan contoh jawaban dan tips."}, "B5-06": {"code": "B5-06", "title": "Kelompok 3: Kemampuan dan Pengalaman", "treat": "Kelompok 3: kemampuan bahasa dan pengalaman kerja.", "pel": "P2", "tpl": "T06", "screen": [{"table": [["Pertanyaan", "Contoh jawaban Rani", "Tips"], ["「日本語はどのくらいできますか。」 (Nihongo wa dono kurai dekimasu ka. \"Seberapa baik bahasa Jepangmu?\")", "「N4に合格しました。ゆっくり話していただければ、だいたい分かります。まだ難しい言葉もありますが、毎日勉強しています。」 (N4 ni goukaku shimashita. Yukkuri hanashite itadakereba, daitai wakarimasu. Mada muzukashii kotoba mo arimasu ga, mainichi benkyou shite imasu. \"Saya lulus N4. Kalau Bapak/Ibu berbicara pelan, saya umumnya paham. Masih ada kata yang sulit, tetapi saya belajar setiap hari.\")", "Sebut level dengan jujur dan tunjukkan usaha belajar."], ["「日本語で、得意なことと苦手なことは何ですか。」 (Nihongo de, tokui na koto to nigate na koto wa nan desu ka. \"Dalam bahasa Jepang, apa yang kamu kuasai dan apa yang masih sulit?\")", "「あいさつや簡単な会話は得意です。でも、速い話を聞くのは苦手なので、ニュースを聞いて練習しています。」 (Aisatsu ya kantan na kaiwa wa tokui desu. Demo, hayai hanashi o kiku no wa nigate na node, nyuusu o kiite renshuu shite imasu. \"Saya bisa memberi salam dan bercakap-cakap sederhana. Tetapi saya masih sulit memahami pembicaraan cepat, jadi saya berlatih dengan mendengarkan berita.\")", "Sama dengan pola kekurangan: jujur + usaha."], ["「前の仕事について教えてください。」 (Mae no shigoto ni tsuite oshiete kudasai. \"Ceritakan pekerjaanmu sebelumnya.\")", "「工場で二年間、部品の検査をしていました。毎日、決められた時間に正確に仕事をしました。」 (Koujou de ninenkan, buhin no kensa o shite imashita. Mainichi, kimerareta jikan ni seikaku ni shigoto o shimashita. \"Saya memeriksa komponen di pabrik selama dua tahun. Setiap hari saya bekerja dengan teliti sesuai waktu yang ditentukan.\")", "Sebut tugas utama dan satu sikap kerja yang baik. Jika belum pernah bekerja, ceritakan kegiatan sekolah atau LPK."]]}], "narasi": "Untuk pertanyaan tentang bahasa dan pengalaman, kuncinya jujur. Pewawancara lebih menghargai kandidat yang tahu kekurangannya dan terus belajar.", "visual": "Kartu pertanyaan geser: tombol putar dan ikon mata di atas, tombol \"Lihat contoh jawaban\" dan \"Tips\"; catatan kosakata di bawah; tiga kartu pertanyaan geser."}, "B5-07": {"code": "B5-07", "title": "Kelompok 4: Kesiapan Bekerja di Jepang", "treat": "Kelompok 4: kesiapan bekerja dan tujuan di Jepang.", "pel": "P2", "tpl": "T06", "screen": [{"p": "perusahaan ingin tahu apakah kamu akan bertahan dan berkembang (定着意欲, teichaku iyoku: kemauan untuk bertahan bekerja)."}, {"table": [["Pertanyaan", "Contoh jawaban Rani", "Tips"], ["「日本でどのくらい働きたいですか。」 (Nihon de dono kurai hatarakitai desu ka. \"Berapa lama kamu ingin bekerja di Jepang?\")", "「契約の三年間、最後までがんばりたいです。」 (Keiyaku no sannenkan, saigo made ganbaritai desu. \"Saya ingin berusaha sampai akhir selama masa kontrak tiga tahun.\")", "Tunjukkan bahwa kamu tidak akan berhenti di tengah jalan. Sesuaikan dengan masa kontrak yang sebenarnya."], ["「将来の目標は何ですか。」 (Shourai no mokuhyou wa nan desu ka. \"Apa tujuanmu di masa depan?\")", "「日本で学んだ技術を生かして、将来はインドネシアの工場でリーダーになりたいです。」 (Nihon de mananda gijutsu o ikashite, shourai wa Indoneshia no koujou de riidaa ni naritai desu. \"Saya ingin memanfaatkan keterampilan yang saya pelajari di Jepang dan kelak menjadi pemimpin di pabrik di Indonesia.\")", "Tujuan yang jelas dan berhubungan dengan pekerjaan menunjukkan kesungguhan."]]}, {"p": "Kotak \"Tahukah kamu?\": di Jepang, pertanyaan tentang hal di luar kemampuan dan kecocokan kerja, misalnya keluarga, agama, atau tempat asal keluarga, digolongkan berisiko menimbulkan diskriminasi dalam seleksi kerja. Jika pertanyaan seperti itu tetap muncul, jawablah singkat dan sopan sesuai kenyamananmu."}], "narasi": "Perusahaan berharap kamu bekerja sampai kontrak selesai dan terus berkembang. Tunjukkan kesiapan dan tujuanmu dengan jelas.", "visual": "Kartu pertanyaan geser: tombol putar dan ikon mata di atas, tombol \"Lihat contoh jawaban\" dan \"Tips\"; catatan kosakata di bawah; kotak \"Tahukah kamu?\" di bawah kartu."}, "B5-08": {"code": "B5-08", "title": "Pertanyaan Tak Terduga dan Latihan Pertanyaan Acak", "treat": "Pertanyaan tak terduga (bagian A) dan latihan pertanyaan acak (bagian B).", "pel": "P2", "tpl": "T06", "screen": [{"p": "pewawancara kadang menanyakan hal sehari-hari yang tidak berhubungan langsung dengan pekerjaan, untuk melihat apakah kamu benar-benar memahami bahasa Jepang, bukan hanya menghafal jawaban. Slide ini terdiri atas dua bagian."}, {"p": "**Bagian A, contoh pertanyaan tak terduga** (kartu geser, satu pertanyaan per kartu):"}, {"table": [["No", "Pertanyaan", "Contoh jawaban"], ["1", "「趣味は何ですか。」 (Shumi wa nan desu ka. \"Apa hobimu?\")", "「サッカーです。週末によく友達とします。チームで動くのが好きです。」 (Sakkaa desu. Shuumatsu ni yoku tomodachi to shimasu. Chiimu de ugoku no ga suki desu. \"Sepak bola. Saya sering bermain bersama teman di akhir pekan. Saya suka bergerak sebagai tim.\")"], ["2", "「休みの日は何をしていますか。」 (Yasumi no hi wa nani o shite imasu ka. \"Apa yang kamu lakukan di hari libur?\")", "「日本語の勉強をしたり、家の手伝いをしたりしています。」 (Nihongo no benkyou o shitari, ie no tetsudai o shitari shite imasu. \"Saya belajar bahasa Jepang dan membantu pekerjaan rumah.\")"], ["3", "「日本の食べ物で、何が好きですか。」 (Nihon no tabemono de, nani ga suki desu ka. \"Makanan Jepang apa yang kamu sukai?\")", "「おにぎりが好きです。簡単で、おいしいからです。」 (Onigiri ga suki desu. Kantan de, oishii kara desu. \"Saya suka onigiri karena praktis dan enak.\")"], ["4", "「今朝、何を食べましたか。」 (Kesa, nani o tabemashita ka. \"Tadi pagi kamu makan apa?\")", "「ご飯と卵を食べました。」 (Gohan to tamago o tabemashita. \"Saya makan nasi dan telur.\")"], ["5", "「インドネシアのいいところを教えてください。」 (Indoneshia no ii tokoro o oshiete kudasai. \"Ceritakan hal baik tentang Indonesia.\")", "「人がやさしいところです。私の町のバンドンは、すずしくて、食べ物もおいしいです。」 (Hito ga yasashii tokoro desu. Watashi no machi no Bandon wa, suzushikute, tabemono mo oishii desu. \"Orangnya ramah. Kota saya, Bandung, sejuk dan makanannya enak.\")"]]}, {"p": "Kiat menjawab pertanyaan tak terduga:"}, {"li": "jawab singkat, 1–2 kalimat, ditambah satu detail;", "lvl": 0, "num": null}, {"li": "isi jawaban bebas dan tidak ada yang salah; yang dinilai adalah kamu memahami pertanyaan dan menjawab dengan sopan;", "lvl": 0, "num": null}, {"li": "bila memungkinkan, hubungkan dengan sikap kerja (kerja sama tim, disiplin, rajin belajar);", "lvl": 0, "num": null}, {"li": "jika tidak paham, pakai ungkapan di B5-09.", "lvl": 0, "num": null}, {"p": "**Bagian B, latihan pertanyaan acak:** lima audio diputar acak dengan teks disembunyikan. Untuk setiap audio, peserta memilih topiknya dari sembilan kartu: motivasi ke Jepang · alasan memilih perusahaan · kekurangan · stamina · bahasa Jepang · pengalaman kerja · lama bekerja · tujuan masa depan · kehidupan sehari-hari."}, {"table": [["No", "Contoh audio (ditampilkan setelah menjawab)", "Topik"], ["1", "「どうして日本で働きたいと思ったんですか。」 (Doushite Nihon de hatarakitai to omottan desu ka. \"Mengapa kamu ingin bekerja di Jepang?\")", "Motivasi ke Jepang"], ["2", "「自分の弱いところはどこだと思いますか。」 (Jibun no yowai tokoro wa doko da to omoimasu ka. \"Menurutmu, apa kelemahanmu?\")", "Kekurangan"], ["3", "「日本語の勉強はどのくらいしましたか。」 (Nihongo no benkyou wa dono kurai shimashita ka. \"Berapa lama kamu belajar bahasa Jepang?\")", "Bahasa Jepang"], ["4", "「五年後、何をしていたいですか。」 (Gonengo, nani o shite itai desu ka. \"Lima tahun lagi, kamu ingin sedang melakukan apa?\")", "Tujuan masa depan"], ["5", "「週末はよく何をしますか。」 (Shuumatsu wa yoku nani o shimasu ka. \"Apa yang sering kamu lakukan di akhir pekan?\")", "Kehidupan sehari-hari"]]}, {"p": "Bank lengkap 25 pertanyaan untuk latihan acak tersedia di menu Fitur Global \"Latihan Pertanyaan Acak\"."}], "narasi": "Pewawancara bisa bertanya apa saja, bahkan tentang hobi atau makanan favoritmu. Tidak ada jawaban yang salah; yang penting kamu memahami pertanyaannya dan menjawab dengan sopan. Setelah itu, uji pendengaranmu dengan lima pertanyaan acak.", "visual": "Bagian A: lima kartu pertanyaan sehari-hari. Bagian B: pemutar audio tanpa teks, pilihan topik berupa kartu, pilihan kecepatan, penghitung benar."}, "B5-09": {"code": "B5-09", "title": "Saat Tidak Paham, Jangan Diam", "treat": "Ungkapan penyelamat saat tidak paham dan simulasi mini.", "pel": "P3", "tpl": "T05", "screen": [{"p": "ungkapan penyelamat (dengan audio):"}, {"table": [["Situasi", "Ungkapan", "Cara baca", "Arti"], ["Tidak menangkap pertanyaan", "すみません、もう一度お願いします。", "Sumimasen, mou ichido onegai shimasu.", "Maaf, mohon diulang sekali lagi."], ["Pewawancara bicara terlalu cepat", "すみません、ゆっくり話していただけませんか。", "Sumimasen, yukkuri hanashite itadakemasen ka.", "Maaf, bisakah Bapak/Ibu berbicara lebih pelan?"], ["Ada satu kata yang tidak dipahami", "すみません、「〇〇」はどういう意味ですか。", "Sumimasen, \"…\" wa dou iu imi desu ka.", "Maaf, apa arti \"…\"?"], ["Ingin memastikan maksud", "〇〇ということですか。", "… to iu koto desu ka.", "Maksudnya …, ya?"], ["Butuh waktu berpikir", "少し考えてもいいですか。", "Sukoshi kangaete mo ii desu ka.", "Bolehkah saya berpikir sebentar?"]]}, {"p": "Langkah bila tetap tidak paham setelah dua kali bertanya: jujur dengan sopan, 「申し訳ありません。まだ分からないところがあります。」 (Moushiwake arimasen. Mada wakaranai tokoro ga arimasu. \"Mohon maaf, masih ada bagian yang belum saya pahami.\")"}, {"p": "Kotak \"Hindari\": pura-pura paham dengan 「はい、分かりました」 (hai, wakarimashita, \"ya, saya mengerti\"); diam lama; menjawab topik lain; bertanya dengan santai seperti 「え？何？」 (e? nani?, \"hah? apa?\")."}, {"p": "Kotak \"Gugup di tengah wawancara?\": berhenti sejenak, tarik napas, lalu lanjutkan dengan kalimat pendek. Kamu juga boleh mengucapkan 「少し考えてもいいですか。」 (Sukoshi kangaete mo ii desu ka. \"Bolehkah saya berpikir sebentar?\"). Pewawancara lebih menghargai jawaban pendek yang tenang daripada jawaban panjang yang terburu-buru."}], "narasi": "Tidak paham itu wajar. Yang dinilai adalah caramu menghadapinya. Minta diulang dengan sopan jauh lebih baik daripada menebak.", "visual": "Tabel situasi → ungkapan beraudio (HP: kartu); langkah bila tetap tidak paham; kotak \"Hindari\"; tombol \"Coba\" membuka simulasi mini pewawancara bicara cepat."}, "B5-10": {"code": "B5-10", "title": "Jujur Itu Nilai Plus", "treat": "Dua situasi: jawaban jujur vs menyelamatkan diri, lalu akibatnya.", "pel": "P3", "tpl": "T13", "screen": [{"p": "dua situasi; peserta memilih jawaban jujur atau jawaban \"menyelamatkan diri\", lalu melihat akibatnya."}, {"table": [["Situasi", "Jawaban tidak jujur", "Jawaban jujur", "Mengapa"], ["「日本語はどのくらいできますか。」 (Nihongo wa dono kurai dekimasu ka. \"Seberapa baik bahasa Jepangmu?\")", "「全部分かります。」 (Zenbu wakarimasu. \"Saya paham semuanya.\")", "Jawaban Rani di B5-06", "Kemampuan bahasa akan terlihat dalam hari pertama bekerja."], ["「フォークリフトの経験はありますか。」 (Fookurifuto no keiken wa arimasu ka. \"Apakah kamu punya pengalaman mengoperasikan forklift?\")", "「はい、あります。」 (Hai, arimasu. \"Ya, ada.\"), padahal belum pernah", "「経験はありませんが、一生懸命覚えます。」 (Keiken wa arimasen ga, isshoukenmei oboemasu. \"Saya belum punya pengalaman, tetapi saya akan mempelajarinya dengan sungguh-sungguh.\")", "Mengaku bisa padahal belum pernah bisa membahayakan keselamatan kerja."]]}, {"p": "Kalimat kunci: **\"Belum bisa tidak apa-apa, asal mau belajar. Berbohong yang merusak kepercayaan.\"**"}], "narasi": "Pewawancara tidak mencari kandidat yang bisa semuanya. Mereka mencari kandidat yang jujur dan mau belajar.", "visual": "Kartu pertanyaan dengan dua pilihan; animasi singkat akibat (hari pertama kerja / pewawancara mengangguk); kalimat kunci di pita bawah."}, "B5-11": {"code": "B5-11", "title": "逆質問: Saatnya Kamu Bertanya", "treat": "逆質問: menyiapkan pertanyaan balik yang sopan.", "pel": "P4", "tpl": "T05", "screen": [{"p": "di akhir wawancara, pewawancara biasanya bertanya 「何か質問はありますか。」 (Nanika shitsumon wa arimasu ka. \"Apakah ada pertanyaan?\"). Siapkan satu atau dua pertanyaan."}, {"table": [["Contoh pertanyaan baik", "Cara baca", "Arti"], ["入社したら、最初にどんな仕事をしますか。", "Nyuusha shitara, saisho ni donna shigoto o shimasu ka.", "Jika saya diterima, pekerjaan apa yang pertama saya lakukan?"], ["日本に行く前に、勉強しておいたほうがいいことはありますか。", "Nihon ni iku mae ni, benkyou shite oita hou ga ii koto wa arimasu ka.", "Apakah ada yang sebaiknya saya pelajari sebelum berangkat ke Jepang?"], ["職場には、外国人の先輩もいますか。", "Shokuba ni wa, gaikokujin no senpai mo imasu ka.", "Apakah di tempat kerja juga ada senior dari luar negeri?"]]}, {"p": "Kotak \"Hindari\":"}, {"li": "Langsung menanyakan gaji dan libur, misalnya 「給料はいくらですか。」 (Kyuuryou wa ikura desu ka. \"Berapa gajinya?\"). Informasi gaji dan kontrak tetap penting; tanyakan lewat LPK atau saat penjelasan kontrak.", "lvl": 0, "num": null}, {"li": "Menanyakan hal yang sudah dijelaskan atau hal dasar seperti 「何の会社ですか。」 (Nan no kaisha desu ka. \"Ini perusahaan apa?\"), yang menunjukkan kamu tidak mencari tahu.", "lvl": 0, "num": null}, {"li": "Hanya menjawab 「ありません。」 (Arimasen. \"Tidak ada.\").", "lvl": 0, "num": null}, {"p": "Jika semua sudah terjawab: 「詳しく説明していただいたので、今は大丈夫です。ありがとうございます。」 (Kuwashiku setsumei shite itadaita node, ima wa daijoubu desu. Arigatou gozaimasu. \"Karena sudah dijelaskan dengan rinci, untuk saat ini sudah cukup. Terima kasih.\")"}], "narasi": "Pertanyaan balik adalah kesempatan terakhir menunjukkan minatmu. Tanyakan tentang pekerjaan atau persiapan, bukan langsung tentang gaji.", "visual": "Gelembung 「何か質問はありますか」 beraudio; tiga kartu contoh pertanyaan; tombol \"Hindari\" dan \"Jika semua sudah terjawab\"."}, "B5-12": {"code": "B5-12", "title": "Aktivitas: Pilih Jawaban Terbaik", "treat": "Latihan memilih jawaban terbaik untuk empat pertanyaan.", "pel": "P4", "tpl": "T13", "screen": [{"p": "empat pertanyaan; setiap pertanyaan punya tiga pilihan jawaban. Pewawancara bereaksi sesuai pilihan (mengangguk, ragu, atau mengernyit)."}, {"table": [["Pertanyaan", "Tepat", "Kurang tepat", "Salah"], ["「体力に自信がありますか。」 (Tairyoku ni jishin ga arimasu ka.)", "Jawaban Rani di B5-05 (dengan bukti)", "「はい、大丈夫です。」 (Hai, daijoubu desu. \"Ya, tidak masalah.\"): benar, tetapi tanpa bukti", "「疲れるのは苦手です。」 (Tsukareru no wa nigate desu. \"Saya tidak suka capek.\")"], ["「前の仕事について教えてください。」 (Mae no shigoto ni tsuite oshiete kudasai.)", "Jawaban Rani di B5-06", "「工場です。」 (Koujou desu. \"Di pabrik.\"): terlalu singkat", "「前の会社は悪かったので、やめました。」 (Mae no kaisha wa warukatta node, yamemashita. \"Perusahaan saya sebelumnya buruk, jadi saya berhenti.\"): menjelekkan tempat kerja lama"], ["「将来の目標は何ですか。」 (Shourai no mokuhyou wa nan desu ka.)", "Jawaban Rani di B5-07", "「まだ分かりません。」 (Mada wakarimasen. \"Belum tahu.\"): jujur, tetapi terkesan tanpa arah", "「お金をためて、すぐ仕事をやめたいです。」 (Okane o tamete, sugu shigoto o yametai desu. \"Saya ingin menabung lalu segera berhenti bekerja.\")"], ["「日本語で、苦手なことは何ですか。」 (Nihongo de, nigate na koto wa nan desu ka. \"Dalam bahasa Jepang, apa yang masih sulit bagimu?\")", "Jawaban Rani di B5-06 (jujur + usaha)", "「全部苦手です。」 (Zenbu nigate desu. \"Semuanya sulit.\"): terlalu merendah", "「苦手なことはありません。」 (Nigate na koto wa arimasen. \"Tidak ada yang sulit.\"): tidak jujur"]]}], "narasi": "Pilih jawaban terbaik untuk setiap pertanyaan, lalu perhatikan reaksi pewawancara.", "visual": "Avatar pewawancara di atas (ekspresi berubah); kartu pertanyaan beraudio; tiga pilihan jawaban; tombol \"Coba lagi\"."}, "B5-13": {"code": "B5-13", "title": "Latihan Lisan: Jawab Tiga Pertanyaan", "treat": "Latihan lisan menjawab tiga pertanyaan acak (tiga lapis).", "pel": "P5", "tpl": "T15", "screen": [{"p": "sistem memutar tiga pertanyaan acak dari B5-04 sampai B5-07. Peserta menjawab dengan suara sendiri memakai pola Jawab → Alasan → Semangat."}, {"li": "**Rekam:** satu rekaman per pertanyaan, target 15–30 detik.", "lvl": 0, "num": null}, {"li": "**Lapis 1:** analisis durasi, jeda, dan volume (target durasi disesuaikan menjadi 10–30 detik).", "lvl": 0, "num": null}, {"li": "**Lapis 2:** dengarkan rekamanmu dan contoh jawaban Rani, lalu centang 4 butir: ☐ langsung menjawab pertanyaan ☐ ada satu alasan atau contoh ☐ ada kalimat semangat ☐ memakai bentuk sopan (です desu / ます masu).", "lvl": 0, "num": null}, {"li": "**Lapis 3:** unduh ketiga rekaman untuk instruktur.", "lvl": 0, "num": null}], "narasi": "Sekarang jawab dengan suaramu sendiri. Ingat polanya: jawab, alasan, semangat.", "visual": "Tombol putar pertanyaan, tombol rekam bulat, timer 10–30 dtk; panel Lapis 1 dan checklist Lapis 2; penanda pertanyaan 1/3."}, "B5-14": {"code": "B5-14", "title": "Rangkuman Bab 5", "treat": "Rangkuman Bab 5, glosarium, dan kartu Kata Mutiara.", "pel": "Penutup", "tpl": "T17", "screen": [{"li": "Pola menjawab: Jawab → Alasan → Semangat, 2–3 kalimat.", "lvl": 0, "num": "1."}, {"li": "Empat kelompok pertanyaan: motivasi · dirimu · kemampuan dan pengalaman · kesiapan bekerja.", "lvl": 0, "num": "2."}, {"li": "Tidak paham? 「すみません、もう一度お願いします」 (sumimasen, mou ichido onegai shimasu, \"maaf, mohon diulang\"). Jangan pura-pura paham.", "lvl": 0, "num": "3."}, {"li": "Jujur dan mau belajar lebih dihargai daripada terlihat bisa semuanya.", "lvl": 0, "num": "4."}, {"li": "逆質問 (gyaku shitsumon): tanyakan tentang pekerjaan atau persiapan, bukan langsung gaji.", "lvl": 0, "num": "5."}, {"p": "Kata Mutiara: **\"Jawaban sederhana yang jujur lebih berharga daripada jawaban hebat yang dihafal.\"**"}], "narasi": "Kamu sudah siap menghadapi tanya jawab. Tinggal satu tahap lagi: menutup wawancara. Tapi sebelum itu, uji pemahamanmu.", "visual": "Poin rangkuman bertahap; kartu Kata Mutiara; tombol glosarium dan \"Mulai Kuis\"."}, "B5-15": {"code": "B5-15", "title": "Kuis Formatif Bab 5", "treat": "Kuis formatif 5 soal acak dari bank 10, lalu layar hasil dan remedial.", "pel": "Penutup", "tpl": "T18", "screen": [{"p": "bank 10 soal; tampil 5 soal acak (1 dari 5.1, 2 dari 5.2, 1 dari 5.3, 1 dari 5.4), satu soal per layar, dengan umpan balik langsung. Soal 1–2 adalah soal menyimak: teks pertanyaan tidak ditampilkan sebelum peserta menjawab. Lulus bila skor ≥ 80. Layar hasil (T19): skor ≥ 80 → \"Kamu lulus Bab 5!\" + animasi stempel. Skor < 80 → \"Hampir! Ulangi bagian berikut, lalu coba lagi.\" + daftar slide remedial."}], "narasi": "tidak ada; Navi bereaksi di layar hasil (GLB-07). Soal, kunci, dan umpan balik: naskah Bab 5.", "visual": "Satu soal per layar dengan empat pilihan (soal menyimak memakai tombol putar, teks tersembunyi); layar hasil berisi skor, stempel Bab 5 atau daftar slide remedial."}, "B6-01": {"code": "B6-01", "title": "Sampul Bab 6", "treat": "Sampul Bab 6: judul, durasi, tiga tujuan, dan daftar pelajaran.", "pel": "Pembuka", "tpl": "T01", "screen": [{"li": "Bab 6 · Taishitsu (退室, taishitsu: keluar ruangan)", "lvl": 0, "num": null}, {"li": "±8 menit · 10 slide", "lvl": 0, "num": null}, {"li": "Setelah bab ini, kamu mampu:", "lvl": 0, "num": null}, {"li": "mengurutkan langkah menutup wawancara dan keluar ruangan;", "lvl": 1, "num": "1."}, {"li": "memakai ungkapan dan ojigi penutup yang tepat;", "lvl": 1, "num": "2."}, {"li": "menjaga sikap setelah keluar ruangan dan melapor ke LPK.", "lvl": 1, "num": "3."}], "narasi": "Kesan terakhir sama pentingnya dengan kesan pertama. Di Bab 6, kita belajar menutup wawancara dengan baik.", "visual": "Rani berdiri di samping kursi, pewawancara tersenyum; judul 退室, kartu tujuan, daftar P1–P3, tombol \"Mulai Bab\"."}, "B6-02": {"code": "B6-02", "title": "Wawancara Selesai, Boleh Santai? (Pemantik)", "treat": "Pemantik video: apakah penilaian selesai saat keluar ruangan?", "pel": "P1", "tpl": "T08", "screen": [{"p": "Video peragaan pendek: Dimas (diperankan anggota tim) selesai wawancara, berdiri tanpa salam, menutup pintu keras, lalu di lorong menghela napas keras, melonggarkan dasi, dan langsung menelepon temannya sambil tertawa."}, {"p": "Pertanyaan: **\"Menurutmu, apakah penilaian sudah selesai saat Dimas keluar ruangan?\"** Ya / Tidak."}], "narasi": "Wawancara Dimas berjalan lancar. Tapi lihat apa yang ia lakukan setelahnya. Apakah penilaian sudah selesai?", "visual": "Pemutar video Dimas keluar ruangan dan di lorong; dua tombol Ya/Tidak; tiga titik kesalahan yang bisa diketuk setelah memilih."}, "B6-03": {"code": "B6-03", "title": "Lima Langkah Keluar Ruangan", "treat": "Peta lima langkah dari kursi ke pintu.", "pel": "P1", "tpl": "T03", "screen": [{"p": "Peta lima langkah dari kursi ke pintu."}, {"li": "Pewawancara menutup wawancara.", "lvl": 0, "num": "1."}, {"li": "Berterima kasih sambil duduk, lalu berdiri dan mengambil tas.", "lvl": 0, "num": "2."}, {"li": "Berdiri di samping kursi, berterima kasih sekali lagi, lalu ojigi dalam.", "lvl": 0, "num": "3."}, {"li": "Berjalan ke pintu, berbalik menghadap pewawancara, mengucapkan 「失礼します」 (shitsurei shimasu, \"permisi\"), lalu ojigi.", "lvl": 0, "num": "4."}, {"li": "Keluar dan menutup pintu dengan pelan.", "lvl": 0, "num": "5."}], "narasi": "Ada lima langkah dari kursi sampai keluar ruangan. Kita pelajari satu per satu.", "visual": "Garis bergambar denah ruang: kursi → pintu, lima nomor langkah; ilustrasi kecil di atas nomor; tombol \"Putar semua\"."}, "B6-04": {"code": "B6-04", "title": "Langkah 1–2: Berterima Kasih Sambil Duduk", "treat": "Langkah 1–2: berterima kasih sambil duduk, lalu berdiri.", "pel": "P1", "tpl": "T05", "screen": [{"table": [["Siapa", "Ungkapan", "Cara baca", "Arti"], ["Pewawancara", "以上で面接を終わります。", "Ijou de mensetsu o owarimasu.", "Dengan ini wawancara selesai."], ["Kamu (duduk)", "本日はありがとうございました。", "Honjitsu wa arigatou gozaimashita.", "Terima kasih banyak untuk hari ini."], ["Kamu (versi lebih sopan)", "本日はお忙しい中、ありがとうございました。", "Honjitsu wa oisogashii naka, arigatou gozaimashita.", "Terima kasih atas waktunya di tengah kesibukan hari ini."]]}, {"p": "Setelah mengucapkan terima kasih: ojigi dari kursi, lalu berdiri dengan tenang dan mengambil tas."}], "narasi": "Saat pewawancara menutup wawancara, ucapkan terima kasih sambil masih duduk dan membungkuk, lalu berdiri dengan tenang.", "visual": "Tabel ungkapan (pewawancara / kamu / versi sopan) beraudio (HP: kartu); tombol \"Lihat gerakan\" membuka video."}, "B6-05": {"code": "B6-05", "title": "Langkah 3: Berdiri di Samping Kursi", "treat": "Langkah 3: terima kasih di samping kursi dan saikeirei 45°.", "pel": "P1", "tpl": "T07", "screen": [{"p": "Berdiri di samping kursi (sisi yang sama seperti saat masuk), tas di tangan."}, {"p": "Ucapkan sekali lagi: 「ありがとうございました。」 (Arigatou gozaimashita. \"Terima kasih banyak.\")"}, {"p": "Lalu 最敬礼 (saikeirei, ojigi ±45°), sesuai 語先後礼 (gosen gorei): kata dulu, baru membungkuk."}], "narasi": "Berdirilah di samping kursi, ucapkan terima kasih sekali lagi, lalu membungkuk dalam. Ini ucapan terima kasih yang paling hormat.", "visual": "Figur di samping kursi dengan tas; ungkapan beraudio; tombol \"Benar\" dan \"Salah\" di atas pemutar video."}, "B6-06": {"code": "B6-06", "title": "Langkah 4–5: Di Depan Pintu dan Keluar", "treat": "Langkah 4–5: salam di depan pintu dan keluar dengan tenang.", "pel": "P1", "tpl": "T07", "screen": [{"p": "**Langkah 4:** berjalan tenang ke pintu. Di depan pintu, berbalik menghadap pewawancara, ucapkan 「失礼します。」 (Shitsurei shimasu. \"Permisi.\") atau versi lebih sopan 「失礼いたします。」 (Shitsurei itashimasu.), lalu 敬礼 (keirei, ojigi ±30°). Ungkapan 「失礼しました」 (shitsurei shimashita) juga sering dipakai saat keluar."}, {"p": "**Langkah 5:** buka pintu dengan tangan yang tidak memegang tas agar tidak membelakangi pewawancara sepenuhnya. Setelah di luar, tutup pintu dengan pelan tanpa suara keras."}, {"p": "Kotak \"Hindari\": berbalik membelakangi pewawancara lalu langsung pergi; membanting pintu; mengenakan jaket atau mantel di dalam kantor (pakai setelah keluar gedung)."}], "narasi": "Di depan pintu, berbaliklah, ucapkan shitsurei shimasu, dan membungkuk. Keluar dan tutup pintu dengan pelan.", "visual": "Ilustrasi pintu dan figur berbalik; ungkapan 「失礼します」/「失礼いたします」 beraudio; tombol \"Benar\"/\"Salah\"; kotak \"Hindari\"."}, "B6-07": {"code": "B6-07", "title": "Setelah Keluar Ruangan", "treat": "Setelah keluar ruangan: empat kartu termasuk wawancara online.", "pel": "P2", "tpl": "T03", "screen": [{"p": "Penilaian belum selesai sampai kamu keluar gedung. Empat kartu (kartu keempat, wawancara online, berisi B6-08):"}, {"li": "**Di dalam gedung:** jika diantar petugas, berjalan sedikit di belakangnya. Tetap tenang; jangan menelepon, bermain HP, atau mengomentari wawancara dengan suara keras.", "lvl": 0, "num": "1."}, {"li": "**Di meja resepsionis:** 「ありがとうございました。失礼いたします。」 (Arigatou gozaimashita. Shitsurei itashimasu. \"Terima kasih banyak. Permisi.\") dan 会釈 (eshaku, ojigi ±15°).", "lvl": 0, "num": "2."}, {"li": "**Setelah keluar gedung, 報告 (houkoku):** lapor ke instruktur LPK bahwa wawancara sudah selesai: 「先生、面接が終わりました。」 (Sensei, mensetsu ga owarimashita. \"Pak/Bu, wawancara sudah selesai.\"). Ceritakan pertanyaan yang muncul dan bagian yang terasa sulit, lalu catat sebagai bahan latihan berikutnya.", "lvl": 0, "num": "3."}, {"li": "**Wawancara online:** membuka kartu B6-08.", "lvl": 0, "num": "4."}], "narasi": "Sikapmu tetap diperhatikan sampai kamu keluar gedung. Setelah itu, jangan lupa houkoku: laporkan ke instruktur LPK bagaimana wawancaramu berjalan.", "visual": "Empat kartu berikon (gedung, meja resepsionis, LPK, laptop); kartu ke-4 membuka B6-08; tombol \"Catatan setelah wawancara\"."}, "B6-08": {"code": "B6-08", "title": "Menutup Wawancara Online", "treat": "Kartu ke-4 B6-07: menutup wawancara online.", "pel": "P2", "tpl": "T03", "screen": [{"li": "Saat pewawancara menutup wawancara, tatap kamera (bukan layar), ucapkan 「本日はありがとうございました。」 (Honjitsu wa arigatou gozaimashita. \"Terima kasih banyak untuk hari ini.\"), lalu ojigi dari kursi.", "lvl": 0, "num": "1."}, {"li": "Jangan langsung menekan tombol keluar. Tunggu sampai pihak perusahaan memutus sambungan.", "lvl": 0, "num": "2."}, {"li": "Jika pewawancara memintamu keluar lebih dulu, ucapkan 「失礼いたします。」 (Shitsurei itashimasu. \"Permisi.\"), lalu keluar.", "lvl": 0, "num": "3."}, {"li": "Setelah sambungan terputus, pastikan kamera dan mikrofon sudah mati sebelum bersantai.", "lvl": 0, "num": "4."}], "narasi": "Pada wawancara online, berterima kasihlah sambil menatap kamera, lalu tunggu sampai perusahaan memutus sambungan.", "visual": "Kartu terbuka berisi empat langkah dengan ilustrasi layar video call (tatap kamera, ojigi dari kursi, tunggu diputus, cek kamera dan mikrofon)."}, "B6-09": {"code": "B6-09", "title": "Aktivitas: Susun dan Lengkapi Langkah Penutup", "treat": "Latihan dua tahap: urutkan lima langkah lalu pilih ungkapan dan ojigi.", "pel": "P3", "tpl": "T11", "screen": [{"p": "Dua tahap."}, {"p": "**Tahap A, urutkan:** lima kartu langkah (B6-03) dalam urutan acak."}, {"p": "**Tahap B, lengkapi:** pada langkah 2–4, pilih ungkapan dan jenis ojigi yang tepat."}, {"table": [["Langkah", "Ungkapan yang benar", "Ojigi yang benar", "Pengecoh"], ["2 (duduk)", "「本日はありがとうございました」 (honjitsu wa arigatou gozaimashita)", "Ojigi dari kursi", "「じゃあ、また」 (jaa, mata, \"dah, sampai jumpa\", santai)"], ["3 (samping kursi)", "「ありがとうございました」 (arigatou gozaimashita)", "最敬礼 (saikeirei) 45°", "「さようなら」 (sayounara, \"selamat tinggal\")"], ["4 (pintu)", "「失礼します」 (shitsurei shimasu)", "敬礼 (keirei) 30°", "「お疲れさまでした」 (otsukaresama deshita, \"terima kasih atas kerja kerasnya\", diucapkan antarrekan kerja)"]]}], "narasi": "Susun lima langkah penutup, lalu pilih ucapan dan ojigi yang tepat di setiap langkah.", "visual": "Tahap A: lima kartu langkah dan lima slot. Tahap B: tabel langkah 2–4 dengan dua pilihan per langkah (ungkapan, jenis ojigi)."}, "B6-10": {"code": "B6-10", "title": "Rangkuman Bab 6 dan Peta Alur Lengkap", "treat": "Rangkuman Bab 6 dan peta alur lengkap Bab 1–6.", "pel": "Penutup", "tpl": "T17", "screen": [{"li": "Duduk: 「本日はありがとうございました」 (honjitsu wa arigatou gozaimashita) + ojigi → berdiri, ambil tas.", "lvl": 0, "num": "1."}, {"li": "Samping kursi: 「ありがとうございました」 (arigatou gozaimashita) + 最敬礼 (saikeirei) 45°.", "lvl": 0, "num": "2."}, {"li": "Pintu: berbalik, 「失礼します」 (shitsurei shimasu) + 敬礼 (keirei) 30° → keluar, tutup pintu pelan.", "lvl": 0, "num": "3."}, {"li": "Tetap sopan sampai keluar gedung, lalu 報告 (houkoku) ke LPK.", "lvl": 0, "num": "4."}, {"p": "Peta alur lengkap Mensetsu Navi (visual garis waktu): persiapan (Bab 1) → 入室 nyuushitsu (Bab 3) → 自己紹介 jikoshoukai (Bab 4) → 質疑応答 shitsugi outou dan 逆質問 gyaku shitsumon (Bab 5) → 退室 taishitsu (Bab 6) → 報告 houkoku ke LPK; dengan Hou-Ren-Sou (Bab 2) sebagai dasar di sepanjang alur."}, {"p": "Kata Mutiara: **\"Wawancara baru selesai saat pintu sudah tertutup.\"**"}], "narasi": "Selamat, kamu sudah mempelajari seluruh alur wawancara. Setelah kuis ini, kamu bisa mencoba simulasi wawancara lengkap.", "visual": "Poin rangkuman; garis waktu alur lengkap (persiapan → masuk → jikoshoukai → tanya jawab → keluar → houkoku) yang bisa diketuk; kartu Kata Mutiara."}, "B6-11": {"code": "B6-11", "title": "Kuis Formatif Bab 6", "treat": "Kuis formatif 5 soal acak; lulus membuka Simulasi bila enam stempel lengkap.", "pel": "Penutup", "tpl": "T18", "screen": [{"p": "bank 10 soal; tampil 5 soal acak (2 dari 6.1, 2 dari 6.2, 1 dari 6.3), satu soal per layar, dengan umpan balik langsung; lulus bila skor ≥ 80. Layar hasil (T19): skor ≥ 80 → \"Kamu lulus Bab 6!\" + animasi stempel; bila stempel Bab 1–6 lengkap → \"Simulasi Mensetsu terbuka!\". Skor < 80 → \"Hampir! Ulangi bagian berikut, lalu coba lagi.\" + daftar slide remedial."}], "narasi": "tidak ada; Navi bereaksi di layar hasil (GLB-07). Soal, kunci, dan umpan balik: naskah Bab 6.", "visual": "Satu soal per layar; layar hasil berisi skor, stempel Bab 6, dan pesan \"Simulasi Mensetsu terbuka!\" bila stempel lengkap."}, "SIM-00": {"code": "SIM-00", "title": "Pengantar dan Aturan Simulasi", "treat": "Pengantar skenario, aturan penilaian, dan pilihan Mode Latihan atau simulasi resmi.", "pel": "", "tpl": "T20", "screen": [{"p": "perusahaan fiktif さくら食品 (Sakura Shokuhin, pabrik makanan); pewawancara 田中さん (Tanaka-san); kamu berperan sebagai kandidat bernama sesuai isianmu. Aturan: 13 momen keputusan, tiap momen tiga pilihan, 20 detik, waktu habis = 0 poin; ucapan pewawancara tampil dalam teks Jepang dan romaji tanpa arti; Trust Meter (信頼度) mulai dari 50 dan hanya umpan balik visual."}], "narasi": "Ini wawancara lengkap dari tiba di kantor sampai keluar ruangan. Kalau ingin mencoba dulu tanpa nilai, pilih Mode Latihan.", "visual": "Ilustrasi lobi kantor さくら食品; kartu profil Tanaka-san (kepala bagian produksi); empat ikon aturan (13 momen, 20 detik, Trust Meter, skor); dua tombol \"Mode Latihan\" dan \"Mulai Simulasi\"."}, "SIM-01": {"code": "SIM-01", "title": "Fase A: Tiba di Depan Gedung", "treat": "Momen 1: jadwal 10.00, kamu tiba pukul 09.35; pilih tindakan sebelum masuk.", "pel": "", "tpl": "T20", "screen": [{"p": "\"Jadwal wawancara pukul 10.00. Kamu tiba di depan gedung pukul 09.35.\""}], "narasi": "tidak ada selama momen. Pilihan jawaban (posisi diacak) ada pada tabel di bawah kartu ini. Ucapan Tanaka-san tampil dalam teks Jepang dan romaji tanpa arti.", "visual": "Ilustrasi depan gedung さくら食品 dengan jam 09.35; kotak situasi di atas; tiga kartu pilihan; timer melingkar 20 detik dan Trust Meter di pojok kanan atas; penanda \"Momen 1/13\"."}, "SIM-02": {"code": "SIM-02", "title": "Fase A: Di Meja Resepsionis", "treat": "Momen 2: memilih ucapan saat melapor ke resepsionis.", "pel": "", "tpl": "T20", "screen": [{"p": "\"Kamu tiba di meja resepsionis.\""}], "narasi": "tidak ada. Pilihan jawaban (posisi diacak) ada pada tabel di bawah kartu ini. Ucapan Tanaka-san tampil dalam teks Jepang dan romaji tanpa arti.", "visual": "Ilustrasi meja resepsionis dengan staf tersenyum; tiga kartu ucapan berbahasa Jepang (romaji dan arti); timer dan Trust Meter."}, "SIM-03": {"code": "SIM-03", "title": "Fase B: Di Depan Pintu", "treat": "Momen 3: dipanggil dan berdiri di depan pintu ruang wawancara.", "pel": "", "tpl": "T20", "screen": [{"p": "\"Kamu dipanggil dan berdiri di depan pintu ruang wawancara.\""}], "narasi": "tidak ada. Pilihan jawaban (posisi diacak) ada pada tabel di bawah kartu ini. Ucapan Tanaka-san tampil dalam teks Jepang dan romaji tanpa arti.", "visual": "Ilustrasi pintu ruang wawancara dari sudut pandang kandidat; tiga kartu tindakan; timer dan Trust Meter."}, "SIM-04": {"code": "SIM-04", "title": "Fase B: Masuk dan Menutup Pintu", "treat": "Momen 4: terdengar 「どうぞ。」; pilih cara masuk.", "pel": "", "tpl": "T20", "screen": [{"p": "Tanaka-san: 「どうぞ。」 (Douzo.)"}], "narasi": "tidak ada. Pilihan jawaban (posisi diacak) ada pada tabel di bawah kartu ini. Ucapan Tanaka-san tampil dalam teks Jepang dan romaji tanpa arti.", "visual": "Pintu terbuka sebagian, Tanaka-san terlihat di balik meja; tiga kartu tindakan; timer dan Trust Meter."}, "SIM-05": {"code": "SIM-05", "title": "Fase B: Di Samping Kursi", "treat": "Momen 5: setelah perkenalan singkat, Tanaka-san mempersilakan duduk.", "pel": "", "tpl": "T20", "screen": [{"p": "Tanaka-san: 「どうぞおかけください。」"}], "narasi": "tidak ada. Pilihan jawaban (posisi diacak) ada pada tabel di bawah kartu ini. Ucapan Tanaka-san tampil dalam teks Jepang dan romaji tanpa arti.", "visual": "Kandidat di samping kursi, Tanaka-san menunjuk kursi; tiga kartu tindakan; timer dan Trust Meter."}, "SIM-06": {"code": "SIM-06", "title": "Fase C: Jikoshoukai", "treat": "Momen 6: Tanaka-san meminta jikoshoukai; pilih versi yang tepat, lalu rekam versi sendiri (opsional).", "pel": "", "tpl": "T20", "screen": [{"p": "Tanaka-san: 「では、自己紹介をお願いします。」 Setelah memilih: \"Sekarang ucapkan jikoshoukai-mu sendiri\" (opsional)."}], "narasi": "tidak ada. Pilihan jawaban (posisi diacak) ada pada tabel di bawah kartu ini. Ucapan Tanaka-san tampil dalam teks Jepang dan romaji tanpa arti.", "visual": "Kandidat duduk berhadapan dengan Tanaka-san; tiga kartu ringkasan jikoshoukai; timer dan Trust Meter; setelah memilih, panel rekam opsional."}, "SIM-07": {"code": "SIM-07", "title": "Fase D: Alasan Memilih Perusahaan", "treat": "Momen 7: 「当社を選んだ理由を教えてください。」", "pel": "", "tpl": "T20", "screen": [{"p": "Tanaka-san: 「当社を選んだ理由を教えてください。」"}], "narasi": "tidak ada. Pilihan jawaban (posisi diacak) ada pada tabel di bawah kartu ini. Ucapan Tanaka-san tampil dalam teks Jepang dan romaji tanpa arti.", "visual": "Tanaka-san bertanya (gelembung teks Jepang + romaji); tiga kartu jawaban; timer dan Trust Meter."}, "SIM-08": {"code": "SIM-08", "title": "Fase D: Kesulitan Bahasa Jepang", "treat": "Momen 8: 「日本語で困ることはありますか。」", "pel": "", "tpl": "T20", "screen": [{"p": "Tanaka-san: 「日本語で困ることはありますか。」"}], "narasi": "tidak ada. Pilihan jawaban (posisi diacak) ada pada tabel di bawah kartu ini. Ucapan Tanaka-san tampil dalam teks Jepang dan romaji tanpa arti.", "visual": "Tanaka-san bertanya (gelembung teks Jepang + romaji); tiga kartu jawaban; timer dan Trust Meter."}, "SIM-09": {"code": "SIM-09", "title": "Fase D: Mesin Tiba-tiba Berhenti", "treat": "Momen 9: pertanyaan situasional Hou-Ren-Sou.", "pel": "", "tpl": "T20", "screen": [{"p": "Tanaka-san: 「機械が急に止まったら、どうしますか。」"}], "narasi": "tidak ada. Pilihan jawaban (posisi diacak) ada pada tabel di bawah kartu ini. Ucapan Tanaka-san tampil dalam teks Jepang dan romaji tanpa arti.", "visual": "Tanaka-san bertanya (gelembung teks Jepang + romaji); tiga kartu jawaban; timer dan Trust Meter; ikon kecil mesin pabrik di gelembung pertanyaan."}, "SIM-10": {"code": "SIM-10", "title": "Fase D: Kata yang Tidak Dipahami", "treat": "Momen 10: 「夜勤はできますか。」 dan kamu tidak tahu arti 夜勤.", "pel": "", "tpl": "T20", "screen": [{"p": "Tanaka-san: 「夜勤はできますか。」"}], "narasi": "tidak ada. Pilihan jawaban (posisi diacak) ada pada tabel di bawah kartu ini. Ucapan Tanaka-san tampil dalam teks Jepang dan romaji tanpa arti.", "visual": "Tanaka-san bertanya (gelembung teks Jepang + romaji); tiga kartu jawaban; timer dan Trust Meter; kata 夜勤 diberi garis bawah titik-titik."}, "SIM-11": {"code": "SIM-11", "title": "Fase D: Pertanyaan Tak Terduga", "treat": "Momen 11: 「ところで、休みの日は何をしていますか。」", "pel": "", "tpl": "T20", "screen": [{"p": "Tanaka-san: 「ところで、休みの日は何をしていますか。」"}], "narasi": "tidak ada. Pilihan jawaban (posisi diacak) ada pada tabel di bawah kartu ini. Ucapan Tanaka-san tampil dalam teks Jepang dan romaji tanpa arti.", "visual": "Tanaka-san bertanya (gelembung teks Jepang + romaji); tiga kartu jawaban; timer dan Trust Meter; ekspresi Tanaka-san lebih santai."}, "SIM-12": {"code": "SIM-12", "title": "Fase D: Pertanyaan Balik", "treat": "Momen 12: 「最後に、何か質問はありますか。」", "pel": "", "tpl": "T20", "screen": [{"p": "Tanaka-san: 「最後に、何か質問はありますか。」"}], "narasi": "tidak ada. Pilihan jawaban (posisi diacak) ada pada tabel di bawah kartu ini. Ucapan Tanaka-san tampil dalam teks Jepang dan romaji tanpa arti.", "visual": "Tanaka-san bertanya (gelembung teks Jepang + romaji); tiga kartu jawaban; timer dan Trust Meter."}, "SIM-13": {"code": "SIM-13", "title": "Fase E: Menutup Wawancara", "treat": "Momen 13: 「以上で面接を終わります。」; pilih urutan keluar ruangan.", "pel": "", "tpl": "T20", "screen": [{"p": "Tanaka-san: 「以上で面接を終わります。」"}], "narasi": "tidak ada. Pilihan jawaban (posisi diacak) ada pada tabel di bawah kartu ini. Ucapan Tanaka-san tampil dalam teks Jepang dan romaji tanpa arti.", "visual": "Tanaka-san menutup map; tiga kartu urutan tindakan; timer dan Trust Meter."}, "SIM-14": {"code": "SIM-14", "title": "Transisi Penilaian", "treat": "Layar jeda \"Tanaka-san sedang menilai…\", lalu ekspresi akhir Tanaka-san sesuai Trust Meter.", "pel": "", "tpl": "T20", "screen": [{"p": "「田中さんが評価しています…」 (Tanaka-san ga hyouka shite imasu, \"Tanaka-san sedang menilai…\")."}], "narasi": "tidak ada.", "visual": "Ruang wawancara kosong yang meredup; teks 「田中さんが評価しています…」; lalu wajah Tanaka-san: tersenyum (Trust Meter ≥ 70), netral (40–69), atau kecewa (< 40)."}, "SIM-15": {"code": "SIM-15", "title": "Pembahasan 13 Momen", "treat": "Pembahasan tiap momen: pilihanmu, pilihan tepat, alasan, dan slide acuan.", "pel": "", "tpl": "T19", "screen": [{"p": "tiap baris: situasi, pilihanmu, pilihan tepat, penjelasan singkat, tombol menuju slide acuan."}], "narasi": "Simulasi selesai. Lihat bagian mana yang sudah tepat dan mana yang perlu dilatih lagi.", "visual": "Daftar 13 baris momen dengan tanda tepat/kurang tepat/salah; baris bisa dibuka; ringkasan Skor Komunikasi dan Skor Etika di atas; tombol \"Lanjut ke Post-test\"."}, "POST-00": {"code": "POST-00", "title": "Petunjuk Post-test", "treat": "Petunjuk post-test: 20 soal yang sama dengan pre-test, urutan soal dan pilihan diacak.", "pel": "", "tpl": "T18", "screen": [{"p": "\"Post-test berisi 20 soal, sekitar 15 menit. Skornya masuk 50% Nilai Sumatif. Pembahasan semua soal ditampilkan setelah selesai.\""}], "narasi": "Ini langkah terakhir. Tunjukkan apa yang sudah kamu pelajari.", "visual": "Kartu petunjuk di tengah dengan tiga ikon (20 soal, jam ±15 menit, masuk 50% Nilai Sumatif); Navi di pojok; tombol \"Mulai Post-test\"."}, "POST-01 s.d. POST-20": {"code": "POST-01 s.d. POST-20", "title": "Soal Post-test dan Pembahasan", "treat": "Dua puluh soal yang sama dengan pre-test (diacak), lalu pembahasan semua soal.", "pel": "", "tpl": "T18", "screen": [{"p": "soal sama dengan pre-test, urutan soal dan pilihan diacak. Pembahasan: kunci, penjelasan, dan slide acuan tiap soal."}], "narasi": "tidak ada.", "visual": "Penanda soal \"1/20\" dan penghitung waktu di atas; teks situasi; empat pilihan A–D sebagai tombol lebar; soal menyimak memakai tombol putar; setelah soal 20, layar pembahasan berupa daftar soal dengan tanda benar/salah yang bisa dibuka."}, "RAP-01": {"code": "RAP-01", "title": "Hasil Utama", "treat": "Nilai Sumatif, status lulus, kategori, dua gauge skor, Trust Meter akhir, dan enam stempel.", "pel": "", "tpl": "T21", "screen": [{"p": "Nilai Sumatif (0–100) = 50% Skor Simulasi + 50% Skor Post-test. Status: Lulus (≥ 75) atau Belum Lulus (< 75). Kategori: ≥ 85 \"Siap Wawancara\" · 75–84 \"Lulus, Perlu Penguatan\" · < 75 \"Belum Lulus, Ulangi Bagian yang Disarankan\"."}], "narasi": "Wawancaramu selesai. Inilah rapor kesiapanmu.", "visual": "Angka besar Nilai Sumatif di tengah; label status dan kategori berwarna dengan ikon; dua gauge (Skor Komunikasi, Skor Etika dan Budaya Kerja); bar Trust Meter akhir dengan wajah Tanaka-san; baris enam stempel bab."}, "RAP-02": {"code": "RAP-02", "title": "Rincian dan Peningkatan", "treat": "Post-test per bab, pre-test vs post-test dengan N-gain, rincian 13 momen, nilai formatif, dan Profil Kesiapan Lisan.", "pel": "", "tpl": "T21", "screen": [{"p": "N-gain = (Post − Pre) ÷ (100 − Pre); kategori tinggi (≥ 0,7), sedang (0,3–0,69), rendah (< 0,3); bila pre-test 100: \"Sudah maksimal sejak awal\". Profil lisan dari rekaman terakhir B4-15, B5-13, dan SIM-06 (tidak masuk kelulusan)."}], "narasi": "tidak ada.", "visual": "Bagian bertumpuk: bar persentase benar per bab; dua bar pre/post berdampingan dengan angka N-gain dan kategorinya; daftar SIM-01 s.d. 13 bertanda; skor kuis Bab 1–6; kartu profil lisan (durasi, jeda, volume, checklist)."}, "RAP-03": {"code": "RAP-03", "title": "Umpan Balik dan Rekomendasi", "treat": "Maksimal tiga umpan balik dan rekomendasi bab, lalu langkah berikutnya sesuai status.", "pel": "", "tpl": "T21", "screen": [{"p": "contoh aturan: Skor Komunikasi < 70 → \"Isi jawabanmu perlu lebih lengkap dan jelas.\" (Bab 4, B5-03) · Skor Etika < 70 → \"Perhatikan lagi urutan masuk, duduk, dan keluar ruangan.\" (B3-03, B6-03) · SIM-09 kurang tepat/salah → \"Ingat Hou-Ren-Sou: laporkan masalah, jangan diatasi sendiri.\" · SIM-11 kurang tepat/salah → B5-08; aturan lengkap di dokumen Evaluasi. Lulus: \"Mensetsu Navi adalah persiapan. Lanjutkan dengan praktik wawancara langsung bersama instruktur LPK.\" Belum lulus: daftar bab yang disarankan."}], "narasi": "membacakan kalimat langkah berikutnya.", "visual": "Kartu umpan balik (maks. tiga, diurutkan dari skor terendah) masing-masing dengan tombol menuju bab/slide; panel \"Langkah berikutnya\"; tombol unduh."}, "GLB-02": {"code": "GLB-02", "title": "Tombol Romaji/Arti", "treat": "Dua sakelar di bilah atas untuk menyalakan atau mematikan romaji dan arti di semua bab.", "pel": "", "tpl": "", "screen": [{"p": "format tetap 「日本語」 (romaji, \"arti\")."}], "narasi": "tidak ada.", "visual": "Dua tombol sakelar kecil \"Romaji\" dan \"Arti\" di bilah atas setiap slide; keduanya menyala secara bawaan."}, "GLB-03": {"code": "GLB-03", "title": "Bank Kosakata dan Kartu Hafalan", "treat": "Gabungan glosarium Bab 1–6 (±75 istilah) dengan pencarian, filter, dan kartu hafalan Leitner tiga kotak.", "pel": "", "tpl": "T12", "screen": [{"p": "filter Bab 1–6 dan kategori (ungkapan sopan, istilah kerja, istilah wawancara, angka dan usia); tautan \"Lihat di slide\". Kotak 1 Belum hafal (setiap sesi) · Kotak 2 Hampir hafal (setiap 2 sesi) · Kotak 3 Hafal (setiap 4 sesi). Satu sesi 10 kartu."}], "narasi": "Kosakata wawancara akan lebih mudah diingat kalau diulang sedikit demi sedikit. Tebak artinya, lalu balik kartunya.", "visual": "Tab \"Daftar\": kolom cari, filter bab dan kategori, daftar entri (Jepang, romaji, arti, ikon audio, bintang). Tab \"Kartu hafalan\": satu kartu besar di tengah (depan: Jepang + audio; belakang: arti dan contoh kalimat), tiga kotak bernomor di bawah."}, "GLB-04": {"code": "GLB-04", "title": "Latihan Pertanyaan Acak", "treat": "Bank 25 pertanyaan wawancara diputar acak dalam mode Dengar atau Jawab-rekam.", "pel": "", "tpl": "T14", "screen": [{"p": "Mode Dengar: audio diputar (teks disembunyikan) → pilih topik → benar/salah, teks, romaji, arti, contoh jawaban. Mode Jawab-rekam: audio → 5 detik bersiap → rekam jawaban (maks. 60 detik) → analisis Lapis 1 → bandingkan dengan contoh jawaban. Bank: A. Inti (9), B. Varian (8), C. Sehari-hari (5), D. Situasional Hou-Ren-Sou (3). Ringkasan: \"Topik yang tertebak: 8 dari 10\"."}], "narasi": "Di wawancara sungguhan, kamu tidak tahu pertanyaan mana yang akan muncul. Dengarkan baik-baik, lalu jawab.", "visual": "Layar pilih mode (dua kartu besar) dan jumlah soal 5/10/25; layar latihan: tombol putar besar, pilihan kecepatan, kartu topik atau tombol rekam dengan timer, penghitung soal."}, "GLB-05": {"code": "GLB-05", "title": "Tips dan Trik Mensetsu", "treat": "Delapan kartu tips dalam tiga tahap (Sebelum, Saat, Sesudah) dengan tautan ke slide acuan.", "pel": "", "tpl": "T03", "screen": [{"p": "Sebelum: 1. cari tahu perusahaan tujuan (B5-04); 2. rekam dan perbaiki jikoshoukai 30–60 detik (B4-15); 3. siapkan pakaian, dokumen, rute, atau perangkat online (B1-09). Saat: 4. datang dan melapor ±10 menit sebelum jadwal (B1-09); 5. duduk tegak dan bicara jelas (B3-11); 6. tidak paham? minta diulang dengan sopan (B5-09); 7. jawab singkat dulu, lalu satu alasan (B5-03). Sesudah: 8. catat pertanyaan dan latih lagi (GLB-04)."}], "narasi": "Ini delapan kebiasaan kecil yang membuat wawancaramu lebih lancar, dari persiapan sampai setelah wawancara.", "visual": "Tiga tab di atas (Sebelum/Saat/Sesudah); kartu tips besar bergambar ikon, satu kalimat tips, alasan singkat, tombol \"Pelajari\"; titik penanda kartu di bawah."}, "GLB-06": {"code": "GLB-06", "title": "Penyimpanan Lokal dan Pengaturan", "treat": "Penyimpanan otomatis di perangkat (tanpa server) dan menu Pengaturan untuk menghapus data.", "pel": "", "tpl": "", "screen": [{"p": "data yang disimpan: nama, progres, nilai (pre-test, kuis Bab 1–6, stempel, Simulasi, Post-test, jumlah percobaan), Profil Kesiapan Lisan, kartu hafalan, pengaturan. Rekaman suara tidak disimpan otomatis; unduh lewat \"Unduh rekaman\". Pesan bila penyimpanan ditolak peramban: data hanya bertahan sampai halaman ditutup."}], "narasi": "tidak ada.", "visual": "Panel Pengaturan: sakelar Romaji/Arti, pilihan kecepatan audio, tombol \"Hapus semua data\" berwarna merah; jendela konfirmasi di dalam produk."}, "GLB-07": {"code": "GLB-07", "title": "Pemandu Navi dan Kata Mutiara", "treat": "Maskot Navi memandu, memberi petunjuk, bereaksi di hasil kuis, dan membawakan Kata Mutiara di setiap rangkuman bab.", "pel": "", "tpl": "T19", "screen": [{"p": "tempat muncul Navi: layar pembuka (menyapa, misi); beranda (saran bagian berikutnya); tombol \"Petunjuk Navi\" di aktivitas dan Mode Latihan Simulasi (satu petunjuk yang menunjuk slide terkait; tidak muncul di kuis, pre/post-test, dan Simulasi resmi); layar hasil kuis (senang atau menyemangati); rangkuman bab (Kata Mutiara). Kata Mutiara Bab 1–6 ada di kartu rangkuman tiap bab."}], "narasi": "dibacakan narator yang sama dengan nada lebih ceria.", "visual": "Navi: karakter orisinal buatan tim (Canva/Figma) dengan ekspresi senang, menyemangati, dan berpikir; gelembung bicara kecil. Kartu Kata Mutiara bergambar Navi; koleksi enam kartu di beranda."}}, "order": ["GLB-00", "PRE-00", "PRE-01 s.d. PRE-20", "PRE-21", "GLB-01", "B1-01", "B1-02", "B1-03", "B1-04", "B1-05", "B1-06", "B1-07", "B1-08", "B1-09", "B1-10", "B1-11", "B1-12", "B2-01", "B2-02", "B2-03", "B2-04", "B2-05", "B2-06", "B2-07", "B2-08", "B2-09", "B2-10", "B2-11", "B2-12", "B2-13", "B3-01", "B3-02", "B3-03", "B3-04", "B3-05", "B3-06", "B3-07", "B3-08", "B3-09", "B3-10", "B3-11", "B3-12", "B3-13", "B3-14", "B4-01", "B4-02", "B4-03", "B4-04", "B4-05", "B4-06", "B4-07", "B4-08", "B4-09", "B4-10", "B4-11", "B4-12", "B4-13", "B4-14", "B4-15", "B4-16", "B4-17", "B5-01", "B5-02", "B5-03", "B5-04", "B5-05", "B5-06", "B5-07", "B5-08", "B5-09", "B5-10", "B5-11", "B5-12", "B5-13", "B5-14", "B5-15", "B6-01", "B6-02", "B6-03", "B6-04", "B6-05", "B6-06", "B6-07", "B6-08", "B6-09", "B6-10", "B6-11", "SIM-00", "SIM-01", "SIM-02", "SIM-03", "SIM-04", "SIM-05", "SIM-06", "SIM-07", "SIM-08", "SIM-09", "SIM-10", "SIM-11", "SIM-12", "SIM-13", "SIM-14", "SIM-15", "POST-00", "POST-01 s.d. POST-20", "RAP-01", "RAP-02", "RAP-03", "GLB-02", "GLB-03", "GLB-04", "GLB-05", "GLB-06", "GLB-07"]};
